    /// Acquire the process-local configuration mutation gate. Callers that
    /// persist settings/profiles must hold this through the write transaction
    /// and the subsequent live-config application so concurrent writers cannot
    /// apply an older catalog after a newer commit.
    pub async fn configuration_mutation_guard(&self) -> tokio::sync::MutexGuard<'_, ()> {
        self.config_mutation.lock().await
    }

    /// Wire process-local reliability metrics (production: shared AppState Arc).
    pub fn with_metrics(
        mut self,
        metrics: Arc<crate::acp::delegation::metrics::DelegationMetrics>,
    ) -> Self {
        self.metrics = metrics;
        self
    }

    /// Inject the attention store used by Join (`list_open_for_tasks`) and the
    /// parent-decision lifecycle (`request_parent_decision` / `reply_to_delegation`).
    pub fn with_attention_store(
        mut self,
        attention_store: Arc<dyn DelegationAttentionStore>,
    ) -> Self {
        self.attention_store = attention_store;
        self
    }

    /// Child requests a blocking parent decision. Persists an open attention
    /// row first, wakes Join via `result_notify`, then parks until a durable
    /// resolution appears in `wait_snapshot`. Dropping this future (MCP socket
    /// close) does not resolve or delete the row; a replay of the same
    /// internal tool call id recovers it.
    pub async fn request_parent_decision(
        &self,
        child_connection_id: &str,
        child_tool_call_id: &str,
        message: &str,
    ) -> ParentDecisionResult {
        if child_tool_call_id.is_empty() {
            return ParentDecisionResult::Rejected {
                code: "invalid_tool_call_id".into(),
                message: "decision request is missing its internal call id".into(),
            };
        }
        if let Err(error) = validate_attention_payload(message) {
            return rejected_decision(error);
        }
        let identity = {
            self.pending
                .inner
                .lock()
                .await
                .coordination_by_child
                .get(child_connection_id)
                .cloned()
        };
        let Some(identity) = identity else {
            return ParentDecisionResult::Rejected {
                code: "not_delegation_child".into(),
                message: "only a live Codeg delegation child can request a parent decision".into(),
            };
        };
        let persisted = match self.task_store.load(&identity.task_id).await {
            Ok(Some(task)) if task.parent_id == Some(identity.parent_conversation_id) => task,
            _ => {
                return ParentDecisionResult::Rejected {
                    code: "task_unavailable".into(),
                    message: "delegation task is unavailable".into(),
                };
            }
        };
        let opened = match self
            .attention_store
            .open_or_recover(NewAttentionRequest {
                task_id: identity.task_id.clone(),
                parent_conversation_id: identity.parent_conversation_id,
                child_conversation_id: persisted.child_conversation_id,
                child_tool_call_id: child_tool_call_id.to_string(),
                message: message.to_string(),
                created_at: Utc::now(),
            })
            .await
        {
            Ok(opened) => opened,
            Err(error) => return rejected_decision(error),
        };
        let request_id = opened.record().summary.request_id.clone();

        match &opened {
            AttentionOpenResult::Opened(record) | AttentionOpenResult::Recovered(record)
                if record.resolution_code.is_none() =>
            {
                // Newly-open or recovered-open: publish running meta + event
                // only after start publication and while non-terminal.
                self.publish_attention_open_if_live(
                    &identity,
                    &record.summary,
                    persisted.child_conversation_id,
                )
                .await;
            }
            AttentionOpenResult::Recovered(record) if record.resolution_code.is_some() => {
                // Recovered resolved: return stored reply/closure; no open
                // meta/event (already closed durably).
            }
            _ => {}
        }

        // The row is durable before either waiter is nudged.
        self.result_notify.notify_waiters();
        loop {
            let notified = self.attention_notify.notified();
            tokio::pin!(notified);
            notified.as_mut().enable();
            let record = match self.attention_store.wait_snapshot(&request_id).await {
                Ok(record) => record,
                Err(error) => return rejected_decision(error),
            };
            if let Some(code) = record.resolution_code {
                return if code == AttentionResolutionCode::ParentReply {
                    match record.reply {
                        Some(reply) => ParentDecisionResult::Replied { request_id, reply },
                        None => ParentDecisionResult::Rejected {
                            code: "attention_invariant".into(),
                            message: "parent reply resolution is missing its reply".into(),
                        },
                    }
                } else {
                    ParentDecisionResult::Closed {
                        request_id,
                        resolution_code: code,
                    }
                };
            }
            notified.await;
        }
    }

    /// Direct parent replies to an open attention request. Authorization is
    /// the durable parent conversation id plus a live coordination edge while
    /// the request is still open. Persist resolution before waking the child
    /// or Join waiters.
    pub async fn reply_to_delegation(
        &self,
        caller_connection_id: &str,
        caller_conversation_id: Option<i32>,
        request_id: &str,
        reply: &str,
    ) -> DelegationReplyResult {
        if let Err(error) = validate_attention_payload(reply) {
            return rejected_reply(error);
        }
        let Some(caller_conversation_id) = caller_conversation_id else {
            return DelegationReplyResult::Unauthorized;
        };
        let record = match self.attention_store.wait_snapshot(request_id).await {
            Ok(record) => record,
            Err(AttentionStoreError::NotFound) => return DelegationReplyResult::Missing,
            Err(error) => return rejected_reply(error),
        };
        if record.parent_conversation_id != caller_conversation_id {
            return DelegationReplyResult::Unauthorized;
        }
        if record.resolution_code.is_none() {
            let owns_live_edge = self
                .pending
                .inner
                .lock()
                .await
                .coordination_by_child
                .values()
                .any(|identity| {
                    identity.task_id == record.summary.task_id
                        && identity.parent_connection_id == caller_connection_id
                        && identity.parent_conversation_id == caller_conversation_id
                });
            if !owns_live_edge {
                return DelegationReplyResult::Unauthorized;
            }
        }

        let result = match self
            .attention_store
            .reply(caller_conversation_id, request_id, reply, Utc::now())
            .await
        {
            Ok(result) => result,
            Err(error) => return rejected_reply(error),
        };
        let public = map_reply_result(request_id, result);
        if matches!(
            public,
            DelegationReplyResult::Replied { .. } | DelegationReplyResult::Idempotent { .. }
        ) {
            // Durable CAS won (or was already resolved). Publish clear only
            // while non-terminal and after start; terminal path owns the lock
            // and does not double-clear. Always wake waiters after.
            if matches!(public, DelegationReplyResult::Replied { .. }) {
                self.publish_attention_clear_if_live(
                    caller_connection_id,
                    caller_conversation_id,
                    &record.summary.task_id,
                )
                .await;
            }
            self.attention_notify.notify_waiters();
            self.result_notify.notify_waiters();
        }
        public
    }

    /// Close any open attention for `task_id` with a terminal resolution code.
    /// Persist-before-notify; storage errors are logged and do not undo a
    /// winning task CAS. Always nudges attention waiters so a stuck child can
    /// recheck (and fail open via NotFound / already-resolved snapshot).
    /// Does **not** publish running-meta clear (terminal path removes the card).
    async fn close_task_attention(
        &self,
        task_id: &str,
        code: AttentionResolutionCode,
    ) -> Option<AttentionRecord> {
        match self
            .attention_store
            .resolve_task(task_id, code, Utc::now())
            .await
        {
            Ok(record) => {
                if record.is_some() {
                    self.attention_notify.notify_waiters();
                    self.result_notify.notify_waiters();
                }
                record
            }
            Err(error) => {
                let (error_code, _) = attention_rejection(&error);
                tracing::error!(
                    %task_id,
                    error_code,
                    "[delegation] failed to close attention"
                );
                self.attention_notify.notify_waiters();
                None
            }
        }
    }

    /// Nonterminal publication for a newly/recovered-open attention request.
    async fn publish_attention_open_if_live(
        &self,
        identity: &CoordinationIdentity,
        summary: &crate::acp::delegation::attention::AttentionRequestSummary,
        child_conversation_id: i32,
    ) {
        let runtime = &identity.runtime;
        let _publication = runtime.publication_lock.lock().await;
        LiveRuntimeState::honor_gate(&runtime.publication_gate).await;
        if runtime.terminal.load(Ordering::Acquire)
            || !runtime.started_published.load(Ordering::Acquire)
        {
            return;
        }
        let stats = runtime.projector.lock().await.snapshot();
        self.write_meta_if_real(
            &identity.parent_connection_id,
            &identity.parent_tool_use_id,
            build_delegation_meta(&DelegationMetaSnapshot {
                status: "running".into(),
                task_preview: Some(identity.task_preview.clone()),
                task_id: identity.task_id.clone(),
                child_connection_id: Some(identity.child_connection_id.clone()),
                child_conversation_id,
                error_code: None,
                text_preview: None,
                started_at: stats.started_at,
                finished_at: None,
                runtime_stats: Some(stats),
                attention_request: Some(summary.clone()),
            }),
        )
        .await;
        self.emit_attention_changed_if_real(
            &identity.parent_connection_id,
            &identity.parent_tool_use_id,
            &identity.task_id,
            Some(summary.clone()),
        )
        .await;
    }

    /// Nonterminal publication for parent-reply clear. Skips when terminal.
    async fn publish_attention_clear_if_live(
        &self,
        parent_connection_id: &str,
        parent_conversation_id: i32,
        task_id: &str,
    ) {
        let identity = {
            self.pending
                .inner
                .lock()
                .await
                .coordination_by_child
                .values()
                .find(|id| {
                    id.task_id == task_id
                        && id.parent_connection_id == parent_connection_id
                        && id.parent_conversation_id == parent_conversation_id
                })
                .cloned()
        };
        let Some(identity) = identity else {
            return;
        };
        let runtime = &identity.runtime;
        let _publication = runtime.publication_lock.lock().await;
        LiveRuntimeState::honor_gate(&runtime.publication_gate).await;
        if runtime.terminal.load(Ordering::Acquire)
            || !runtime.started_published.load(Ordering::Acquire)
        {
            return;
        }
        let stats = runtime.projector.lock().await.snapshot();
        let child_conversation_id = {
            let from_running = self
                .pending
                .inner
                .lock()
                .await
                .running
                .get(task_id)
                .map(|t| t.child_conversation_id);
            if let Some(id) = from_running {
                id
            } else if let Ok(Some(task)) = self.task_store.load(task_id).await {
                task.child_conversation_id
            } else {
                return;
            }
        };
        self.write_meta_if_real(
            &identity.parent_connection_id,
            &identity.parent_tool_use_id,
            build_delegation_meta(&DelegationMetaSnapshot {
                status: "running".into(),
                task_preview: Some(identity.task_preview.clone()),
                task_id: identity.task_id.clone(),
                child_connection_id: Some(identity.child_connection_id.clone()),
                child_conversation_id,
                error_code: None,
                text_preview: None,
                started_at: stats.started_at,
                finished_at: None,
                runtime_stats: Some(stats),
                attention_request: None,
            }),
        )
        .await;
        self.emit_attention_changed_if_real(
            &identity.parent_connection_id,
            &identity.parent_tool_use_id,
            &identity.task_id,
            None,
        )
        .await;
    }

    async fn latest_open_attention(
        &self,
        parent_conversation_id: i32,
        task_id: &str,
    ) -> Option<crate::acp::delegation::attention::AttentionRequestSummary> {
        let open = self
            .attention_store
            .list_open_for_tasks(parent_conversation_id, &[task_id.to_string()])
            .await
            .ok()?;
        open.into_iter().next()
    }

    /// Shared metrics handle for supervisor / listener / tests.
    pub fn metrics(&self) -> Arc<crate::acp::delegation::metrics::DelegationMetrics> {
        self.metrics.clone()
    }

    #[allow(clippy::too_many_arguments)] // Stable telemetry schema mirrors the metric event fields.
    fn record_recovery_event(
        &self,
        kind: RecoveryMetricEventKind,
        task_id: Option<&str>,
        authorization_id: Option<&str>,
        parent_conversation_id: Option<i32>,
        child_conversation_id: Option<i32>,
        action: Option<&str>,
        cause: Option<&str>,
        risk: Option<&str>,
        code: Option<&str>,
    ) {
        let Some(event) = DelegationRecoveryMetricEvent::validated(
            kind,
            task_id,
            authorization_id,
            parent_conversation_id.map(|id| id.to_string()),
            child_conversation_id.map(|id| id.to_string()),
            action,
            cause,
            risk,
            code,
        ) else {
            tracing::warn!(
                target: "codeg::delegation::recovery",
                event = kind.as_str(),
                "invalid stable recovery telemetry value rejected"
            );
            return;
        };
        self.metrics.record_recovery_event(event);
    }

    fn record_recovery_admission_error(
        &self,
        error: &TaskStoreError,
        task_id: &str,
        parent_conversation_id: i32,
        child_conversation_id: Option<i32>,
        action: &'static str,
    ) {
        match error {
            TaskStoreError::RecoveryConfirmationRequired(projection) => {
                self.record_recovery_event(
                    RecoveryMetricEventKind::Decision,
                    Some(task_id),
                    None,
                    Some(parent_conversation_id),
                    child_conversation_id,
                    projection.proposed_action.as_deref(),
                    Some(&projection.cause_code),
                    Some(&projection.risk_class),
                    Some("recovery_confirmation_required"),
                );
                self.record_recovery_event(
                    RecoveryMetricEventKind::ConfirmationRequested,
                    Some(task_id),
                    None,
                    Some(parent_conversation_id),
                    child_conversation_id,
                    projection.proposed_action.as_deref(),
                    Some(&projection.cause_code),
                    Some(&projection.risk_class),
                    Some("recovery_confirmation_required"),
                );
            }
            TaskStoreError::RecoveryAuthorizationRejected { code } => {
                if *code == "recovery_authorization_declined" {
                    self.record_recovery_event(
                        RecoveryMetricEventKind::ConfirmationDeclined,
                        Some(task_id),
                        None,
                        Some(parent_conversation_id),
                        child_conversation_id,
                        Some(action),
                        None,
                        None,
                        Some(code),
                    );
                }
                self.record_recovery_event(
                    RecoveryMetricEventKind::AuthorizationRejected,
                    Some(task_id),
                    None,
                    Some(parent_conversation_id),
                    child_conversation_id,
                    Some(action),
                    None,
                    None,
                    Some(code),
                );
            }
            _ => {}
        }
    }

    /// Record one status-wait outcome (exact-once per request return path).
    fn record_status_wait(
        &self,
        mode: crate::acp::delegation::metrics::WaitModeLabel,
        requested_wait_ms: Option<u64>,
        started: Instant,
        reason: crate::acp::delegation::metrics::WaitReturnReason,
    ) {
        let wall = started.elapsed();
        self.metrics.record_wait(mode, wall, reason);
        crate::acp::delegation::metrics::DelegationAuditRecord::wait(
            mode,
            requested_wait_ms,
            wall,
            reason,
        )
        .emit_wait();
    }

    /// Install the soft-supervisor wake handle (production bootstrap). Tests
    /// leave the default noop.
    pub fn set_supervisor_wake(&self, wake: SupervisorWake) {
        *self.supervisor_wake.lock().expect("supervisor_wake lock") = wake;
    }

    /// Park the wake receiver until startup takes it after reconcile.
    pub fn park_supervisor_wake_rx(&self, rx: tokio::sync::mpsc::Receiver<()>) {
        *self
            .supervisor_wake_rx
            .lock()
            .expect("supervisor_wake_rx lock") = Some(rx);
    }

    /// Take the parked wake receiver exactly once (desktop/server startup).
    pub fn take_supervisor_wake_rx(&self) -> Option<tokio::sync::mpsc::Receiver<()>> {
        self.supervisor_wake_rx
            .lock()
            .expect("supervisor_wake_rx lock")
            .take()
    }

    /// Nudge the soft supervisor (non-blocking; coalesces when channel is full).
    pub fn notify_supervisor(&self) {
        self.supervisor_wake
            .lock()
            .expect("supervisor_wake lock")
            .notify();
    }

    /// Logical Running Broker tasks as `(task_id, child_connection_id)` for
    /// the observation source: `pending.running` ∪ `pending.settling` — the
    /// same set Task 8 status/wait classify as [`TaskStatus::Running`].
    /// Child connection id is preserved for both maps so the production
    /// source can join `SessionState` through settlement.
    pub async fn running_task_child_ids(&self) -> Vec<(String, String)> {
        let inner = self.pending.inner.lock().await;
        let mut out: Vec<(String, String)> = inner
            .running
            .iter()
            .map(|(id, t)| (id.clone(), t.child_connection_id.clone()))
            .collect();
        out.extend(
            inner
                .settling
                .iter()
                .map(|(id, t)| (id.clone(), t.child_connection_id.clone())),
        );
        out
    }

    /// Cache a soft-supervisor observation (observe-only; never mutates status).
    /// On a real transition: bumps status version, wakes waiters, emits
    /// `DelegationObservationChanged` for the parent card.
    pub async fn cache_observation(&self, task_id: &str, snap: ObservationSnapshot) {
        let changed = {
            let mut cache = self.observation_cache.lock().await;
            let changed = cache.get(task_id) != Some(&snap);
            cache.insert(task_id.to_string(), snap.clone());
            changed
        };
        if !changed {
            return;
        }
        self.bump_status_version();
        self.result_notify.notify_waiters();
        self.emit_observation_changed(task_id, &snap).await;
    }

    /// Drop a cached observation when the task leaves logical Running
    /// (neither `running` nor `settling` — true terminal) or on a supervisor
    /// stale clear. Treats clear as an observation transition: bumps version
    /// and wakes waiters. Supervised re-evaluates **requested** ids only, so an
    /// unrelated clear is a harmless wake (re-park).
    pub async fn clear_observation(&self, task_id: &str) {
        let removed = self
            .observation_cache
            .lock()
            .await
            .remove(task_id)
            .is_some();
        if removed {
            self.bump_status_version();
            self.result_notify.notify_waiters();
        }
    }

    /// Read a cached observation for Running-report enrichment.
    pub async fn cached_observation(&self, task_id: &str) -> Option<ObservationSnapshot> {
        self.observation_cache.lock().await.get(task_id).cloned()
    }

    fn bump_status_version(&self) {
        self.status_version.fetch_add(1, Ordering::SeqCst);
    }

    /// Emit observation change on the parent stream (synthetic tool-use ids skip).
    async fn emit_observation_changed(&self, task_id: &str, snap: &ObservationSnapshot) {
        let (parent_connection_id, parent_tool_use_id) = {
            let inner = self.pending.inner.lock().await;
            let Some(task) = inner
                .running
                .get(task_id)
                .or_else(|| inner.settling.get(task_id))
            else {
                return;
            };
            (
                task.parent_connection_id.clone(),
                task.parent_tool_use_id.clone(),
            )
        };
        if is_synthetic_parent_tool_use_id(&parent_tool_use_id) {
            return;
        }
        self.event_emitter
            .emit_observation_changed(
                &parent_connection_id,
                &parent_tool_use_id,
                task_id,
                snap.observation,
                snap.last_agent_activity_at,
                snap.stalled_since,
            )
            .await;
    }

    /// Replace the DB status fallback used by `get_delegation_status` /
    /// `cancel_delegation` for tasks evicted from the in-memory completed-cache.
    /// Builder-style so the production wiring can layer it onto `with_writers`
    /// without growing that constructor's arity, and tests can opt in.
    pub fn with_status_lookup(mut self, status_lookup: Arc<dyn ChildStatusLookup>) -> Self {
        self.status_lookup = status_lookup;
        self
    }

    /// Wire the durable task store (production: `DbDelegationTaskStore`).
    pub fn with_task_store(mut self, task_store: Arc<dyn DelegationTaskStore>) -> Self {
        self.task_store = task_store;
        self
    }

    /// Wire the authoritative run store for gen-1 launch snapshots (production).
    pub fn with_run_store(mut self, run_store: Arc<RunStore>) -> Self {
        self.run_store = Some(run_store);
        self
    }

    /// Shared run store (and its SQLite handle) when production/tests wired one.
    /// Workflow MCP tools use this for publish/settle/get_workflow_state cores.
    pub fn run_store(&self) -> Option<Arc<RunStore>> {
        self.run_store.clone()
    }

    async fn fail_gen1_workflow_binding_load(
        &self,
        runs: &RunStore,
        task_id: &str,
        child_conversation_id: i32,
        agent_type: AgentType,
        inflight_id: u64,
        error: &WorkflowLaunchLoadError,
    ) -> DelegationTaskReport {
        let error_code = error.durable_error_code("spawn_failed");
        let error_message = error.to_string();
        if error.workflow_admission_code().is_some() {
            let settlement = runs
                .settle_pre_admission_failure_if_owned(
                    task_id,
                    "",
                    failed_terminal(
                        error_code,
                        DelegationRunStatus::Reserving,
                        false,
                        AcpTerminationSource::Admission,
                        AcpTerminationReason::AdmissionFailed,
                        AcpTerminationClassification::Unexpected,
                    ),
                )
                .await;
            self.drop_inflight(inflight_id).await;
            return match settlement {
                Ok(Some(Settlement::Won(report) | Settlement::Existing(report))) => {
                    normalize_gen1_pre_spawn_report(
                        report,
                        task_id,
                        child_conversation_id,
                        agent_type,
                    )
                }
                Ok(None) => match runs.load_by_task_id(task_id).await {
                    Ok(Some(run)) => normalize_gen1_pre_spawn_report(
                        run.to_persisted_task().to_report(None),
                        task_id,
                        child_conversation_id,
                        agent_type,
                    ),
                    Ok(None) => report_err(
                        agent_type,
                        DelegationError::WorkflowAdmission {
                            code: error_code.to_string(),
                            message: error_message,
                        },
                        Some(child_conversation_id),
                    ),
                    Err(error) => report_err(
                        agent_type,
                        store_err_to_delegation_error(error),
                        Some(child_conversation_id),
                    ),
                },
                Err(error) => report_err(
                    agent_type,
                    store_err_to_delegation_error(error),
                    Some(child_conversation_id),
                ),
            };
        }
        match runs.abandon_unbound_reserving_claim(task_id).await {
            Ok(true) => {
                let cleanup = self
                    .compensate_provisional_orphan(
                        &runs.db().conn,
                        child_conversation_id,
                        "workflow binding load failure",
                    )
                    .await;
                self.drop_inflight(inflight_id).await;
                if let Err(error) = cleanup {
                    return report_err(agent_type, error, Some(child_conversation_id));
                }
                report_err(
                    agent_type,
                    DelegationError::WorkflowAdmission {
                        code: error_code.to_string(),
                        message: error_message.clone(),
                    },
                    Some(child_conversation_id),
                )
            }
            Ok(false) => {
                let settlement = runs
                    .settle_pre_admission_failure_if_owned(
                        task_id,
                        "",
                        failed_terminal(
                            error_code,
                            DelegationRunStatus::Reserving,
                            false,
                            AcpTerminationSource::Admission,
                            AcpTerminationReason::AdmissionFailed,
                            AcpTerminationClassification::Unexpected,
                        ),
                    )
                    .await;
                self.drop_inflight(inflight_id).await;
                match settlement {
                    Ok(Some(Settlement::Won(report) | Settlement::Existing(report))) => {
                        normalize_gen1_pre_spawn_report(
                            report,
                            task_id,
                            child_conversation_id,
                            agent_type,
                        )
                    }
                    Ok(None) => match runs.load_by_task_id(task_id).await {
                        Ok(Some(run)) => normalize_gen1_pre_spawn_report(
                            run.to_persisted_task().to_report(None),
                            task_id,
                            child_conversation_id,
                            agent_type,
                        ),
                        Ok(None) => report_err(
                            agent_type,
                            DelegationError::WorkflowAdmission {
                                code: error_code.to_string(),
                                message: error_message.clone(),
                            },
                            Some(child_conversation_id),
                        ),
                        Err(error) => report_err(
                            agent_type,
                            store_err_to_delegation_error(error),
                            Some(child_conversation_id),
                        ),
                    },
                    Err(error) => report_err(
                        agent_type,
                        store_err_to_delegation_error(error),
                        Some(child_conversation_id),
                    ),
                }
            }
            Err(error) => {
                self.drop_inflight(inflight_id).await;
                report_err(
                    agent_type,
                    store_err_to_delegation_error(error),
                    Some(child_conversation_id),
                )
            }
        }
    }

    /// Parent cancel after gen-1 admit commit but before spawn: prefer
    /// abandon (+ reclaim of just-settled pure provisional claims) then
    /// compensate the unused child shell. Never report a successful canceled
    /// setup when abandon errors — that would leave a durable canceled run
    /// without the provisional compensation path.
    ///
    /// When abandon cannot match (claim advanced past pure pre-spawn, or is a
    /// non-provisional terminal), fall back to durable settle. When no run row
    /// remains, compensate the child shell only.
    #[allow(clippy::too_many_arguments)]
    async fn cancel_admitted_gen1_pre_spawn(
        &self,
        runs: &RunStore,
        task_id: &str,
        child_conversation_id: i32,
        context: ParentEndContext,
        agent_type: AgentType,
        inflight_id: u64,
        abandon_context: &'static str,
    ) -> DelegationTaskReport {
        self.cancel_admitted_gen1_pre_spawn_with(
            runs,
            task_id,
            child_conversation_id,
            agent_type,
            inflight_id,
            abandon_context,
            context.durable_error_code(),
            context.audit(
                DelegationRunStatus::Reserving,
                AdmissionClass::NormalRevision,
                None,
                None,
            ),
            |agent, child| parent_end_setup_report(agent, &context, child),
        )
        .await
    }

    /// External MCP cancel after gen-1 admit / before spawn (same abandon +
    /// compensate path as parent-end; wire code is generic `canceled`).
    async fn cancel_admitted_gen1_pre_spawn_external(
        &self,
        runs: &RunStore,
        task_id: &str,
        child_conversation_id: i32,
        agent_type: AgentType,
        inflight_id: u64,
        abandon_context: &'static str,
    ) -> DelegationTaskReport {
        let observed_at = Utc::now();
        self.cancel_admitted_gen1_pre_spawn_with(
            runs,
            task_id,
            child_conversation_id,
            agent_type,
            inflight_id,
            abandon_context,
            "canceled",
            explicit_cancellation_audit(DelegationRunStatus::Reserving, false, observed_at),
            |agent, child| {
                report_err(
                    agent,
                    DelegationError::Canceled {
                        reason: "canceled before spawn".into(),
                    },
                    child,
                )
            },
        )
        .await
    }

    #[allow(clippy::too_many_arguments)]
    async fn cancel_admitted_gen1_pre_spawn_with(
        &self,
        runs: &RunStore,
        task_id: &str,
        child_conversation_id: i32,
        agent_type: AgentType,
        inflight_id: u64,
        abandon_context: &'static str,
        settle_error_code: &str,
        termination_audit: DelegationTerminationAuditV1,
        success_report: impl FnOnce(AgentType, Option<i32>) -> DelegationTaskReport,
    ) -> DelegationTaskReport {
        let finished_at = termination_audit.termination.observed_at;
        match runs.abandon_reserving_claim(task_id).await {
            Ok(true) => {
                if let Err(cleanup_err) = self
                    .compensate_provisional_orphan(
                        &runs.db().conn,
                        child_conversation_id,
                        abandon_context,
                    )
                    .await
                {
                    self.drop_inflight(inflight_id).await;
                    return report_err(agent_type, cleanup_err, Some(child_conversation_id));
                }
                self.drop_inflight(inflight_id).await;
                success_report(agent_type, Some(child_conversation_id))
            }
            Ok(false) => match runs.load_by_task_id(task_id).await {
                Ok(None) => {
                    // Run already gone (prior abandon) — still hide the shell.
                    if let Err(cleanup_err) = self
                        .compensate_provisional_orphan(
                            &runs.db().conn,
                            child_conversation_id,
                            abandon_context,
                        )
                        .await
                    {
                        self.drop_inflight(inflight_id).await;
                        return report_err(agent_type, cleanup_err, Some(child_conversation_id));
                    }
                    self.drop_inflight(inflight_id).await;
                    success_report(agent_type, Some(child_conversation_id))
                }
                Ok(Some(_)) => {
                    // Claim advanced past pure pre-spawn provisional shape
                    // (bind / running / non-reclaimable terminal) — settle.
                    match runs
                        .settle_terminal(
                            task_id,
                            TerminalTaskWrite::canceled(
                                settle_error_code,
                                finished_at,
                                termination_audit,
                            ),
                        )
                        .await
                    {
                        Ok(_) => {
                            self.drop_inflight(inflight_id).await;
                            success_report(agent_type, Some(child_conversation_id))
                        }
                        Err(e) => {
                            self.drop_inflight(inflight_id).await;
                            report_err(
                                agent_type,
                                store_err_to_delegation_error(e),
                                Some(child_conversation_id),
                            )
                        }
                    }
                }
                Err(e) => {
                    self.drop_inflight(inflight_id).await;
                    report_err(
                        agent_type,
                        store_err_to_delegation_error(e),
                        Some(child_conversation_id),
                    )
                }
            },
            Err(e) => {
                // Do not collapse abandon store errors into a successful
                // canceled report — fallback settlement may leave the wrong
                // durable shape for provisional ownership.
                self.drop_inflight(inflight_id).await;
                report_err(
                    agent_type,
                    store_err_to_delegation_error(e),
                    Some(child_conversation_id),
                )
            }
        }
    }

    /// Full provisional compensation: Step-1 atomic terminalization, then
    /// Step-2 guarded soft-delete (with one retry). Both steps retain the
    /// no-run fence so admission interleaved between them never hides a valid
    /// child. Fail-closed: terminalize errors map to
    /// [`DelegationError::ProvisionalTerminalizationFailed`]; soft-delete
    /// exhaustion maps to [`DelegationError::ProvisionalCleanupFailed`].
    async fn compensate_provisional_orphan(
        &self,
        conn: &sea_orm::DatabaseConnection,
        child_id: i32,
        context: &'static str,
    ) -> Result<(), DelegationError> {
        use crate::db::service::conversation_service;

        if let Err(e) = conversation_service::terminalize_provisional_child(conn, child_id).await {
            tracing::error!(
                provisional_child_id = child_id,
                error = %e,
                context,
                "[delegation] provisional terminalization failed; skipping soft-delete"
            );
            return Err(map_terminalize_err(child_id, context, e.to_string()));
        }

        soft_delete_provisional_orphan_with(child_id, context, |id| {
            let this = self;
            async move {
                #[cfg(any(test, feature = "test-utils"))]
                {
                    let left = this
                        .force_provisional_soft_delete_failures
                        .load(Ordering::SeqCst);
                    if left > 0 {
                        this.force_provisional_soft_delete_failures
                            .fetch_sub(1, Ordering::SeqCst);
                        return Err("forced soft_delete failure (test)".to_string());
                    }
                }
                // Silence unused-self warning in non-test builds where the
                // force-fail path above is compiled out.
                let _ = this;
                conversation_service::soft_delete_provisional_child(conn, id)
                    .await
                    .map(|_| ())
                    .map_err(|e| e.to_string())
            }
        })
        .await
    }

    /// Override the persistence retry policy (tests use near-zero delays).
    pub fn with_persistence_retry(mut self, policy: PersistenceRetryPolicy) -> Self {
        self.persistence_retry = policy;
        self
    }

    /// Override the background persistence-retry worker sleep (tests use a few ms).
    pub fn with_persistence_retry_worker_interval(mut self, interval: Duration) -> Self {
        self.persistence_retry_worker_interval = interval;
        self
    }

    /// Fail-closed gate: the delegation listener must not start when
    /// `reconcile_running` fails. Desktop and server startup call this with
    /// [`Self::reconcile_running_on_startup`]'s result.
    pub fn require_reconcile_ok(result: Result<u64, String>) -> Result<u64, String> {
        result.map_err(|e| format!("delegation startup blocked: reconcile_running failed: {e}"))
    }

    /// Replace the live-reply lookup used to enrich `get_delegation_status`'s
    /// running report with the child's latest one-line progress. Builder-style,
    /// layered onto `with_writers` by the production wiring; tests opt in with a
    /// `MockChildLiveReplyLookup`.
    pub fn with_live_reply_lookup(
        mut self,
        live_reply_lookup: Arc<dyn ChildLiveReplyLookup>,
    ) -> Self {
        self.live_reply_lookup = live_reply_lookup;
        self
    }

    /// Reconcile open attention, then orphaned running delegate rows, after
    /// host restart. Call after migrations/settings load and before the
    /// delegation listener accepts requests. Attention is reconciled first so
    /// Task 11 can record host_restarted/task_terminal reasons from the
    /// winning attention records without re-querying by timestamp.
    pub async fn reconcile_running_on_startup(&self) -> Result<u64, String> {
        let at = Utc::now();
        let reconciled_attention = self
            .attention_store
            .reconcile_open(at)
            .await
            .map_err(|error| format!("reconcile attention failed: {error}"))?;
        let attention_count = reconciled_attention.len();
        let task_count = self
            .task_store
            .reconcile_running(at)
            .await
            .map_err(|error| format!("reconcile running tasks failed: {error}"))?;
        // Keep `reconciled_attention` alive through task reconciliation so
        // future metrics (Task 11) can consume these exact winning records.
        let _ = reconciled_attention;
        tracing::info!(
            attention_count,
            task_count,
            "[delegation] startup reconciliation complete"
        );
        self.attention_notify.notify_waiters();
        self.result_notify.notify_waiters();
        Ok(task_count)
    }

    /// Record a parent ACP `tool_call_id` whose title indicates the LLM is
    /// invoking `delegate_to_agent`. The next broker round-trip from the
    /// same `parent_connection_id` will claim this id as its
    /// `parent_tool_use_id`. Bounded FIFO per connection.
    ///
    /// Two-tier dedupe against host re-emits of `sessionUpdate(tool_call)`
    /// (some hosts use the non-update variant to ship status flips and
    /// late-arriving `raw_input` chunks):
    ///
    /// 1. **In-queue**: if the id is still waiting to be claimed, drop
    ///    the re-emit — the first push will be consumed by the matching
    ///    MCP round-trip.
    /// 2. **Recently consumed**: if the id was already claimed for an
    ///    earlier delegation on the same parent, drop the re-emit —
    ///    otherwise it would sit in the queue as a stale id and mis-
    ///    bind the **next** delegation's MCP round-trip. The consumed
    ///    memory persists for the parent connection's lifetime (no
    ///    TTL, no cap) so a host re-emit at terminal status flip is
    ///    still rejected even if the delegation ran for hours.
    pub async fn register_pending_tool_call(
        &self,
        parent_connection_id: &str,
        tool_call_id: String,
    ) {
        self.register_pending_tool_call_with_key_at(
            parent_connection_id,
            tool_call_id,
            None,
            false,
            Instant::now(),
        )
        .await;
    }

    /// Register an id announced with NO identity at all — Cursor's
    /// `"MCP: tool"` + empty-input shape, where the wire never reveals which
    /// MCP tool the call is. The entry is unkeyed and marked `identityless` so
    /// status/cancel call-time rename
    /// ([`Self::rewrite_identityless_tool_call`]) can bind it. It is **not**
    /// claimable by `delegate_to_agent` / `continue_delegation` (those tools
    /// use exact-key correlation only; no unkeyed FIFO).
    pub async fn register_identityless_tool_call(
        &self,
        parent_connection_id: &str,
        tool_call_id: String,
    ) {
        self.register_pending_tool_call_with_key_at(
            parent_connection_id,
            tool_call_id,
            None,
            true,
            Instant::now(),
        )
        .await;
    }

    /// `register_pending_tool_call` that also records the
    /// `(agent_type, task, working_dir)` correlation key parsed from the
    /// tool_call's `raw_input`. The key lets
    /// the broker bind this id to its matching MCP round-trip deterministically
    /// for parallel `delegate_to_agent` calls that pure arrival-order FIFO can
    /// mis-assign. Production registration (from the ACP lifecycle dispatcher)
    /// goes through here.
    pub async fn register_pending_tool_call_with_key(
        &self,
        parent_connection_id: &str,
        tool_call_id: String,
        match_key: Option<DelegationMatchKey>,
    ) {
        self.register_pending_tool_call_with_key_at(
            parent_connection_id,
            tool_call_id,
            match_key,
            false,
            Instant::now(),
        )
        .await;
    }

    /// Core registration. Holds the [`ToolCallTracker`] mutex across both
    /// dedupe tiers AND the push so no concurrent `take` can split the
    /// "queue empty + not yet recorded as consumed" window where a host
    /// re-emit could otherwise inject a stale duplicate.
    ///
    /// Two-tier dedupe against host re-emits of `sessionUpdate(tool_call)`
    /// (some hosts use the non-update variant to ship status flips and
    /// late-arriving `raw_input` chunks):
    ///
    /// 1. **Recently consumed**: if the id was already claimed for an
    ///    earlier delegation on the same parent, drop the re-emit —
    ///    otherwise it would sit in the queue as a stale id and mis-bind
    ///    the **next** delegation's MCP round-trip. The consumed memory
    ///    persists for the parent connection's lifetime (no TTL, no cap)
    ///    so a host re-emit at terminal status flip is still rejected
    ///    even if the delegation ran for hours.
    /// 2. **In-queue**: if the id is still waiting to be claimed, apply the
    ///    pending-key mutation rules (first complete key freezes):
    ///    - `None → Some(K)`: backfill (arg-less first event, later complete).
    ///    - `Some(K) → Some(K)`: idempotent re-emit; no change.
    ///    - `Some(K1) → Some(K2)` where `K1 ≠ K2`: **conflict tombstone** —
    ///      freeze K1, mark permanently unclaimable by key; do **not** replace
    ///      with K2 (supersedes the prior "replace with latest parseable key"
    ///      behavior).
    ///
    ///    Hosts that emit an arg-less initial `ToolCall` and ship full args on
    ///    a following `ToolCallUpdate` still backfill via `None → Some(K)`.
    ///    Keying the entry this way is what lets it survive past the unkeyed
    ///    GC TTL (see `take_matching_tool_call_at`'s retain block).
    async fn register_pending_tool_call_with_key_at(
        &self,
        parent_connection_id: &str,
        tool_call_id: String,
        match_key: Option<DelegationMatchKey>,
        identityless: bool,
        now: Instant,
    ) {
        let mut map = self.tool_calls.inner.lock().await;
        let bucket = map.entry(parent_connection_id.to_string()).or_default();
        if identityless {
            bucket.identityless_seen = true;
        }
        // Tier 1: recently consumed. No TTL — the consumed memory must
        // outlast the entire parent-side tool call lifetime (minutes
        // to hours) so a host re-emit at terminal status flip is
        // still rejected. See `ToolCallTrackerBucket` docs.
        if bucket.consumed.iter().any(|(id, _)| id == &tool_call_id) {
            tracing::info!(
                "[delegation] dropping ACP tool_call_id={tool_call_id} on conn={parent_connection_id} (already consumed by an earlier delegation)"
            );
            return;
        }
        // Tier 2: in-queue re-emit — pending-key immutability rules.
        if let Some(existing) = bucket
            .pending
            .iter_mut()
            .find(|p| p.tool_call_id == tool_call_id)
        {
            if identityless {
                existing.identityless = true;
            }
            match (&existing.match_key, match_key) {
                // None → Some(K): allowed backfill of the first complete key.
                (None, Some(key)) => {
                    existing.match_key = Some(key);
                }
                // Some(K) → Some(K): idempotent re-emit.
                (Some(k1), Some(k2)) if k1 == &k2 => {
                    tracing::info!(
                        "[delegation] dropping duplicate ACP tool_call_id={tool_call_id} on conn={parent_connection_id} (identical key)"
                    );
                }
                // Some(K1) → Some(K2), K1 ≠ K2: conflict tombstone; freeze K1.
                (Some(_), Some(_k2)) => {
                    if !existing.key_conflicted {
                        existing.key_conflicted = true;
                        tracing::info!(
                            "[delegation] key-conflict tombstone for ACP tool_call_id={tool_call_id} on conn={parent_connection_id} (first complete key frozen; later key discarded)"
                        );
                    } else {
                        tracing::info!(
                            "[delegation] dropping re-emit on already conflict-tombstoned ACP tool_call_id={tool_call_id} on conn={parent_connection_id}"
                        );
                    }
                }
                // Re-emit without a key, or both still None: no mutation.
                (_, None) => {
                    tracing::info!(
                        "[delegation] dropping duplicate ACP tool_call_id={tool_call_id} on conn={parent_connection_id}"
                    );
                }
            }
            return;
        }
        bucket.pending.push_back(PendingToolCall {
            tool_call_id,
            match_key,
            key_conflicted: false,
            identityless,
            registered_at: now,
        });
    }

    /// Pop the oldest pending `tool_call_id` for the given parent, if any.
    /// Skips entries older than [`PENDING_TOOL_CALL_TTL`] so an ACP id whose
    /// matching MCP round-trip never arrived cannot mis-bind a later
    /// delegation. Mutates the queue in-place; the bucket is removed once
    /// drained.
    pub async fn take_pending_tool_call(&self, parent_connection_id: &str) -> Option<String> {
        self.take_pending_tool_call_at(parent_connection_id, Instant::now())
            .await
            .map(|(id, _)| id)
    }

    /// `take_pending_tool_call` with an injected "as of" instant. The
    /// public entry point pins it to `Instant::now()`; tests can supply
    /// a future instant to exercise TTL eviction without sleeping past
    /// [`PENDING_TOOL_CALL_TTL`].
    ///
    /// Anonymous claim: returns the oldest *unkeyed* pending id (plus its
    /// `identityless` mark for status/cancel rename bookkeeping), GC'ing stale
    /// unkeyed entries along the way. KEYED entries are stepped over and left
    /// in place — reserved for exact-key-match only. **Not** used by
    /// `delegate_to_agent` / `continue_delegation` (those go through
    /// [`Self::resolve_exact_claim`]). Returns `None` when no unkeyed entry is
    /// claimable, even if keyed entries remain.
    async fn take_pending_tool_call_at(
        &self,
        parent_connection_id: &str,
        now: Instant,
    ) -> Option<(String, bool)> {
        self.take_unkeyed_tool_call_at(parent_connection_id, now, false)
            .await
    }

    /// Claim the oldest pending entry that was registered as IDENTITY-LESS
    /// (Cursor's `"MCP: tool"` announcements) — used by the status/cancel
    /// call-time rename. Unlike `take_pending_tool_call_at` this NEVER hands
    /// out a plain unkeyed entry: that one is a delegation invocation whose
    /// args merely didn't parse, and renaming it to a status tool would
    /// mislabel a real delegate card.
    async fn take_identityless_tool_call(&self, parent_connection_id: &str) -> Option<String> {
        self.take_unkeyed_tool_call_at(parent_connection_id, Instant::now(), true)
            .await
            .map(|(id, _)| id)
    }

    /// Shared FIFO claim over unkeyed entries for **status/cancel rename and
    /// tests only**. `identityless_only` restricts eligibility to entries
    /// carrying the identity-less mark; keyed entries are always stepped over
    /// (reserved for exact-key-match). Stale unkeyed entries are GC'd along
    /// the way. `delegate_to_agent` / `continue_delegation` never call this.
    async fn take_unkeyed_tool_call_at(
        &self,
        parent_connection_id: &str,
        now: Instant,
        identityless_only: bool,
    ) -> Option<(String, bool)> {
        let mut map = self.tool_calls.inner.lock().await;
        let bucket = map.get_mut(parent_connection_id)?;
        // Status/cancel identity-less rename + tests. Never used by
        // `delegate_to_agent` / `continue_delegation` (exact claim only).
        // Walk oldest→newest, GC'ing stale unkeyed entries and stepping over
        // keyed ones. When only keyed siblings remain, return `None`.
        let mut claimed: Option<(String, bool)> = None;
        let mut idx = 0;
        while idx < bucket.pending.len() {
            if bucket.pending[idx].match_key.is_some() {
                idx += 1; // keyed: leave it for its exact-match round-trip
                continue;
            }
            if now.duration_since(bucket.pending[idx].registered_at) > PENDING_TOOL_CALL_TTL {
                if let Some(stale) = bucket.pending.remove(idx) {
                    let age_secs = now.duration_since(stale.registered_at).as_secs();
                    tracing::info!(
                        "[delegation] evicting stale UNKEYED ACP tool_call_id={} (age={age_secs}s) on conn={parent_connection_id}",
                        stale.tool_call_id
                    );
                }
                // `remove` shifted later entries left into `idx`; re-check it.
                continue;
            }
            if identityless_only && !bucket.pending[idx].identityless {
                idx += 1; // plain unkeyed: not eligible for identity-less rename
                continue;
            }
            claimed = bucket
                .pending
                .remove(idx)
                .map(|p| (p.tool_call_id, p.identityless));
            break;
        }
        // Same mutex span: record the claim into the consumed memory so
        // a concurrent re-register cannot observe "pending empty AND
        // consumed missing" and inject a stale duplicate. Consumed
        // entries persist for the whole parent connection lifetime
        // (no TTL, no cap — see `ToolCallTrackerBucket`) and are only
        // released when the parent disconnects.
        if let Some((id, _)) = &claimed {
            bucket.consumed.push_back((id.clone(), now));
        }
        if bucket.pending.is_empty() && bucket.consumed.is_empty() && !bucket.identityless_seen {
            map.remove(parent_connection_id);
        }
        claimed
    }

    /// Whether this parent has EVER registered an identity-less candidate —
    /// the zero-cost gate for [`Self::rewrite_identityless_tool_call`]'s poll.
    async fn has_seen_identityless_tool_calls(&self, parent_connection_id: &str) -> bool {
        self.tool_calls
            .inner
            .lock()
            .await
            .get(parent_connection_id)
            .is_some_and(|b| b.identityless_seen)
    }

    /// Restore the identity of a pending identity-less MCP tool call at
    /// companion round-trip time: claim the oldest such candidate for this
    /// parent and rewrite its live `title` + `raw_input` to the actual
    /// codeg-mcp tool (`get_delegation_status` / `cancel_delegation`) with
    /// its real arguments — flipping the card from the generic "MCP: tool"
    /// WHILE the call runs, instead of only at the completion-time result
    /// sniff (which, for a `wait_ms`-blocked status long-poll, can be minutes
    /// away).
    ///
    /// Best-effort by design: on hosts that ship real identities the sticky
    /// `identityless_seen` gate skips everything at zero cost; on an
    /// identity-less host whose announcement hasn't registered yet, a short
    /// bounded poll (well under the ACP-vs-companion race in practice)
    /// absorbs the ordering, and a miss simply leaves the rename to the
    /// completion sniff. Mis-pairing under PARALLEL identity-less calls in
    /// one burst is the same accepted arrival-order residual as the delegate
    /// FIFO fallback — Cursor executes tool calls sequentially, so announce
    /// order matches round-trip order in practice.
    pub async fn rewrite_identityless_tool_call(
        &self,
        parent_connection_id: &str,
        title: &str,
        raw_input: serde_json::Value,
    ) -> Option<String> {
        if !self
            .has_seen_identityless_tool_calls(parent_connection_id)
            .await
        {
            return None;
        }
        for attempt in 0..IDENTITYLESS_RENAME_POLL_ATTEMPTS {
            if attempt > 0 {
                tokio::time::sleep(CLAIM_POLL_INTERVAL).await;
            }
            if let Some(id) = self.take_identityless_tool_call(parent_connection_id).await {
                tracing::info!(
                    "[delegation] renaming identity-less tool_call_id={id} on conn={parent_connection_id} to {title}"
                );
                self.meta_writer
                    .write_tool_call_identity(parent_connection_id, &id, title, raw_input)
                    .await;
                return Some(id);
            }
        }
        None
    }

    /// Claim the pending `tool_call_id` for `parent_connection_id` whose
    /// recorded key matches `key` (exact `(agent_type, task, working_dir)`
    /// match). This is the ONLY claim this method makes — it never hands out an
    /// unkeyed entry, because an unkeyed entry may belong to a *different*
    /// parallel delegation whose round-trip simply hasn't registered (or keyed)
    /// its `tool_call` yet, and claiming it by arrival order would steal that
    /// sibling's id. Returns `None` (so the caller keeps polling) whenever no
    /// entry's key matches — whether keyed siblings or only unkeyed entries are
    /// present.
    ///
    /// Evicts stale *unkeyed* entries along the way; keyed entries are retained
    /// regardless of age (their round-trip may be serialized far behind earlier
    /// delegations — see the retain block) and an exact key match claims them
    /// at any age. Delegate/continue entry points must prefer
    /// [`Self::resolve_exact_claim`] (wait-out-budget, no FIFO) rather than
    /// calling this eagerly.
    pub async fn take_matching_tool_call(
        &self,
        parent_connection_id: &str,
        key: &DelegationMatchKey,
    ) -> Option<String> {
        self.take_matching_tool_call_at(parent_connection_id, key, Instant::now())
            .await
    }

    /// `take_matching_tool_call` with an injected "as of"
    /// instant for TTL tests.
    async fn take_matching_tool_call_at(
        &self,
        parent_connection_id: &str,
        key: &DelegationMatchKey,
        now: Instant,
    ) -> Option<String> {
        let mut map = self.tool_calls.inner.lock().await;
        let bucket = map.get_mut(parent_connection_id)?;

        // Evict every stale UNKEYED entry up front. The key-match scan below
        // ignores unkeyed entries anyway (they carry no key to match), but
        // GC'ing here keeps the queue bounded during the poll loop and
        // consistent with `take_pending_tool_call_at`'s view, so the
        // post-budget last resort never hands out an aged-out id. Mirrors that
        // TTL skip but covers entries at any position (not just the front).
        bucket.pending.retain(|p| {
            // Keyed entries are NEVER aged out. Each identifies one specific
            // `delegate_to_agent` invocation and is claimable ONLY by an exact
            // key match (never by FIFO — see below), so it cannot mis-bind a
            // different delegation no matter how old it gets. And it MUST
            // survive until its MCP round-trip arrives, which the host may
            // serialize arbitrarily far behind earlier long-running
            // delegations: Claude Code runs parallel `delegate_to_agent` calls
            // SEQUENTIALLY, so the 2nd call's round-trip only fires after the
            // 1st child finishes. Observed in the wild — a 2nd delegation whose
            // tool_call registered, then waited 77s (past the old 60s TTL) for
            // its round-trip while the 1st ran; age-evicting it here orphaned
            // it to a synthetic id and left the parent card stuck on
            // "sub-agent running…". Only UNKEYED (anonymous, arrival-order
            // correlated) entries keep the age-based GC, since a stale one
            // could be mis-claimed via the FIFO path. Keyed memory stays bounded
            // by exact-match claim, terminal tombstoning, and
            // `drop_pending_tool_calls_for_parent` on connection teardown — not
            // by this TTL.
            if p.match_key.is_some() {
                return true;
            }
            let fresh = now.duration_since(p.registered_at) <= PENDING_TOOL_CALL_TTL;
            if !fresh {
                let age_secs = now.duration_since(p.registered_at).as_secs();
                tracing::info!(
                    "[delegation] evicting stale UNKEYED ACP tool_call_id={} (age={age_secs}s) on conn={parent_connection_id}",
                    p.tool_call_id
                );
            }
            fresh
        });

        let claimed = if let Some(pos) = bucket.pending.iter().position(|p| {
            // Conflict-tombstoned entries never count as claimable matches.
            !p.key_conflicted && p.match_key.as_ref() == Some(key)
        }) {
            // Exact typed-key match: deterministic correlation regardless of
            // ACP-vs-MCP arrival order or how many delegations are in flight.
            bucket.pending.remove(pos).map(|p| p.tool_call_id)
        } else {
            // No exact key match. We deliberately do NOT claim an unkeyed entry
            // here — not even the oldest, not even the only one. An unkeyed
            // pending entry may belong to a DIFFERENT parallel delegation whose
            // own round-trip hasn't yet registered (or keyed) its `tool_call`,
            // and claiming it by arrival order would steal that sibling's id —
            // the mis-bind this machinery exists to prevent.
            //
            // Crucially, the ENTRY's age is the wrong clock for "no key is
            // coming": a host can serialize a round-trip arbitrarily far behind
            // its `tool_call` registration (see the retain block / the
            // `keyed_entry_survives_past_ttl` case), so even an old lone unkeyed
            // entry can still be a sibling's. The CALLER's own wait is the right
            // clock — see `resolve_exact_claim` (wait-out-budget exact match
            // only; no unkeyed FIFO for delegate/continue).
            None
        };

        if let Some(id) = &claimed {
            bucket.consumed.push_back((id.clone(), now));
        }
        if bucket.pending.is_empty() && bucket.consumed.is_empty() {
            map.remove(parent_connection_id);
        }
        claimed
    }

    /// Cancel-only cleanup: remove a pending entry only when the typed key has
    /// **exactly one** non-conflicted match. When zero or two+ candidates share
    /// the key, leave the bucket unchanged so a later claim still observes
    /// Missing / sticky Ambiguous. First-match removal would defeat fail-closed
    /// ambiguity (a cancel of one request must not steal a sibling card).
    async fn take_unique_matching_tool_call(
        &self,
        parent_connection_id: &str,
        key: &DelegationMatchKey,
    ) -> Option<String> {
        let mut map = self.tool_calls.inner.lock().await;
        let bucket = map.get_mut(parent_connection_id)?;
        let now = Instant::now();
        bucket.pending.retain(|p| {
            if p.match_key.is_some() {
                return true;
            }
            now.duration_since(p.registered_at) <= PENDING_TOOL_CALL_TTL
        });
        let mut non_conflicted_pos: Vec<usize> = Vec::new();
        for (i, p) in bucket.pending.iter().enumerate() {
            if !p.key_conflicted && p.match_key.as_ref() == Some(key) {
                non_conflicted_pos.push(i);
            }
        }
        if non_conflicted_pos.len() != 1 {
            // Ambiguous or empty: retain / leave for precise identity later.
            return None;
        }
        let pos = non_conflicted_pos[0];
        let claimed = bucket
            .pending
            .remove(pos)
            .map(|p| p.tool_call_id)
            .expect("position validated");
        bucket.consumed.push_back((claimed.clone(), now));
        if bucket.pending.is_empty() && bucket.consumed.is_empty() && !bucket.identityless_seen {
            map.remove(parent_connection_id);
        }
        Some(claimed)
    }

    /// Consume an explicit `parent_tool_use_id` that the MCP client supplied
    /// directly via `_meta.tool_use_id` (the precise-binding path; most clients
    /// omit it). In that case `handle_request` does NOT run the claim path, so
    /// the matching pending entry the lifecycle dispatcher registered off the
    /// parent's ACP stream would otherwise never be consumed — and because
    /// keyed entries are now retained indefinitely, it would linger and could
    /// be mis-claimed by a *later* delegation sharing the same
    /// `(agent_type, task, working_dir)` key, retargeting that delegation's
    /// writes/events at the wrong (already-handled) card.
    ///
    /// Remove the entry from the pending queue AND record the id as consumed.
    /// Recording consumed also covers the MCP-before-ACP race: a later ACP
    /// registration for the same id is dropped by the Tier-1 consumed check in
    /// `register_pending_tool_call_with_key_at`, so the entry can't reappear
    /// regardless of arrival order.
    async fn consume_explicit_tool_call(&self, parent_connection_id: &str, tool_call_id: &str) {
        let mut map = self.tool_calls.inner.lock().await;
        let bucket = map.entry(parent_connection_id.to_string()).or_default();
        bucket.pending.retain(|p| p.tool_call_id != tool_call_id);
        if !bucket.consumed.iter().any(|(id, _)| id == tool_call_id) {
            bucket
                .consumed
                .push_back((tool_call_id.to_string(), Instant::now()));
        }
    }

    /// Tombstone a parent `tool_call_id` whose `delegate_to_agent` reached a
    /// TERMINAL ACP status (`completed`/`failed`) so a stale keyed pending entry
    /// can't mis-bind a later delegation. The lifecycle dispatcher calls this
    /// from its terminal-`ToolCallUpdate` branch, keyed on `tool_call_id`
    /// (a bare terminal update carries no parseable key).
    ///
    /// The hazard: keyed pending entries are retained regardless of age (see the
    /// retain block in `take_matching_tool_call_at`), so if a `delegate_to_agent`
    /// tool call goes terminal without its MCP round-trip ever reaching the
    /// broker (the call failed, the turn was interrupted, the companion never
    /// dispatched), its entry would linger forever and a LATER delegation sharing
    /// the same `(agent_type, task, working_dir)` key would claim this dead id,
    /// retargeting its writes/events at the wrong card. Same hazard
    /// `consume_explicit_tool_call` guards on the explicit-id path; this is its
    /// terminal-status sibling.
    ///
    /// Safe synchronously, no grace window: a terminal `completed` can only
    /// arrive AFTER the round-trip's claim already removed the entry (the ack
    /// that claim produces is what lets the parent's tool call return), and a
    /// serialized sibling still awaiting its (observed 77s-late) round-trip is
    /// NON-terminal while it waits — so this never evicts a live entry.
    ///
    /// Records `consumed` ONLY when an entry was actually removed: this runs for
    /// EVERY terminal tool-call update (the vast majority are non-delegations),
    /// and `consumed` has no TTL/cap, so recording unconditionally would grow it
    /// with every completed tool call. Recording on a real removal still drops an
    /// out-of-order re-registration of the same id via the Tier-1 consumed check
    /// in `register_pending_tool_call_with_key_at`. Returns whether an entry was
    /// removed (for the dispatcher's gated log).
    pub async fn tombstone_pending_tool_call(
        &self,
        parent_connection_id: &str,
        tool_call_id: &str,
    ) -> bool {
        let mut map = self.tool_calls.inner.lock().await;
        // No bucket → nothing registered for this parent; nothing to tombstone
        // and nothing to record (unlike `consume_explicit_tool_call`, no
        // MCP-before-ACP race can land a terminal status before registration on
        // the single ordered ACP stream, so we never pre-create a bucket here).
        let Some(bucket) = map.get_mut(parent_connection_id) else {
            return false;
        };
        let before = bucket.pending.len();
        bucket.pending.retain(|p| p.tool_call_id != tool_call_id);
        let removed = bucket.pending.len() != before;
        if removed && !bucket.consumed.iter().any(|(id, _)| id == tool_call_id) {
            bucket
                .consumed
                .push_back((tool_call_id.to_string(), Instant::now()));
        }
        removed
    }

    /// Whether this in-flight setup has been parent-end flagged (non-consuming).
    async fn inflight_is_canceled(&self, inflight_id: u64) -> bool {
        let inner = self.pending.inner.lock().await;
        inner.inflight_parent_end(inflight_id).is_some()
    }

    /// Non-consuming scan of pending entries matching `key`. GC's stale unkeyed
    /// entries so the view stays consistent with claim helpers.
    async fn scan_exact_matches(
        &self,
        parent_connection_id: &str,
        key: &DelegationMatchKey,
        now: Instant,
    ) -> (Vec<String>, usize) {
        let mut map = self.tool_calls.inner.lock().await;
        let Some(bucket) = map.get_mut(parent_connection_id) else {
            return (Vec::new(), 0);
        };
        bucket.pending.retain(|p| {
            if p.match_key.is_some() {
                return true;
            }
            let fresh = now.duration_since(p.registered_at) <= PENDING_TOOL_CALL_TTL;
            if !fresh {
                tracing::info!(
                    "[delegation] evicting stale UNKEYED ACP tool_call_id={} (age={}s) on conn={parent_connection_id}",
                    p.tool_call_id,
                    now.duration_since(p.registered_at).as_secs()
                );
            }
            fresh
        });
        let mut non_conflicted = Vec::new();
        let mut conflicted = 0usize;
        for p in &bucket.pending {
            if p.match_key.as_ref() == Some(key) {
                if p.key_conflicted {
                    conflicted += 1;
                } else {
                    non_conflicted.push(p.tool_call_id.clone());
                }
            }
        }
        if bucket.pending.is_empty() && bucket.consumed.is_empty() && !bucket.identityless_seen {
            map.remove(parent_connection_id);
        }
        (non_conflicted, conflicted)
    }

    /// End-of-budget unique claim under one lock: re-scan, claim only if exactly
    /// one non-conflicted equal key remains.
    async fn claim_unique_exact_at_budget_end(
        &self,
        parent_connection_id: &str,
        key: &DelegationMatchKey,
    ) -> ExactClaimResult {
        let mut map = self.tool_calls.inner.lock().await;
        let now = Instant::now();
        let Some(bucket) = map.get_mut(parent_connection_id) else {
            return ExactClaimResult::Missing;
        };
        bucket.pending.retain(|p| {
            p.match_key.is_some() || now.duration_since(p.registered_at) <= PENDING_TOOL_CALL_TTL
        });
        let mut non_conflicted_pos: Vec<usize> = Vec::new();
        let mut conflicted = 0usize;
        for (i, p) in bucket.pending.iter().enumerate() {
            if p.match_key.as_ref() == Some(key) {
                if p.key_conflicted {
                    conflicted += 1;
                } else {
                    non_conflicted_pos.push(i);
                }
            }
        }
        if non_conflicted_pos.len() >= 2 {
            return ExactClaimResult::Ambiguous;
        }
        if non_conflicted_pos.len() == 1 {
            let pos = non_conflicted_pos[0];
            let id = bucket
                .pending
                .remove(pos)
                .map(|p| p.tool_call_id)
                .expect("position validated");
            bucket.consumed.push_back((id.clone(), now));
            if bucket.pending.is_empty() && bucket.consumed.is_empty() && !bucket.identityless_seen
            {
                map.remove(parent_connection_id);
            }
            return ExactClaimResult::Matched(id);
        }
        if conflicted > 0 {
            return ExactClaimResult::Conflict;
        }
        ExactClaimResult::Missing
    }

    /// Shared exact resolver for `delegate_to_agent` and `continue_delegation`.
    ///
    /// Precedence while polling / at budget end:
    /// 1. Cancelled (in-flight parent end)
    /// 2. Sticky Ambiguous (two+ non-conflicted equal keys on any tick)
    /// 3. End-of-budget unique non-conflicted claim → Matched
    /// 4. Only conflict-tombstoned candidates → Conflict
    /// 5. Zero claimable candidates → Missing
    ///
    /// Never calls unkeyed `take_pending_tool_call`. Never invents a parent id.
    /// Does not claim on the first unique sighting — waits the full poll budget
    /// so a late duplicate equal key still yields Ambiguous.
    ///
    /// Cancel observation (each tick + budget end + post-claim): parent-end
    /// inflight flag, sticky external-cancel marker on the setup, **or**
    /// buffered `notifications/cancelled` for `external_handle` (single-shot
    /// take sticky-marks the setup so later checkpoints still observe cancel).
    pub async fn resolve_exact_claim(
        &self,
        parent_connection_id: &str,
        key: &DelegationMatchKey,
        inflight_id: Option<u64>,
        external_handle: Option<&str>,
    ) -> ExactClaimResult {
        // Test-only: observe entry into the poll loop before the first scan so
        // MCP-before-ACP fixtures can register the keyed card only after the
        // resolver is known to be waiting (deterministic; no sleep races).
        #[cfg(any(test, feature = "test-utils"))]
        LiveRuntimeState::honor_gate(&self.exact_claim_poll_gate).await;
        for _ in 0..CLAIM_POLL_ATTEMPTS {
            if self
                .exact_claim_cancel_observed(inflight_id, external_handle)
                .await
            {
                return ExactClaimResult::Cancelled;
            }
            let (non_conflicted, _) = self
                .scan_exact_matches(parent_connection_id, key, Instant::now())
                .await;
            if non_conflicted.len() >= 2 {
                // Sticky Ambiguous: once observed, fail closed without consuming.
                return ExactClaimResult::Ambiguous;
            }
            tokio::time::sleep(CLAIM_POLL_INTERVAL).await;
        }
        if self
            .exact_claim_cancel_observed(inflight_id, external_handle)
            .await
        {
            return ExactClaimResult::Cancelled;
        }
        // Test-only: hold after the final cancel observation and before the
        // unique claim so parent-end can race the claim lock boundary.
        #[cfg(any(test, feature = "test-utils"))]
        LiveRuntimeState::honor_gate(&self.exact_claim_budget_end_gate).await;
        // Re-check cancel after the budget-end gate (and immediately before
        // claim) so a parent end stamped during the gate still fails closed.
        if self
            .exact_claim_cancel_observed(inflight_id, external_handle)
            .await
        {
            return ExactClaimResult::Cancelled;
        }
        let claimed = self
            .claim_unique_exact_at_budget_end(parent_connection_id, key)
            .await;
        // Parent end / external cancel can land between the pre-claim check and
        // claim (different locks). Never return Matched when cancel already won.
        if matches!(claimed, ExactClaimResult::Matched(_))
            && self
                .exact_claim_cancel_observed(inflight_id, external_handle)
                .await
        {
            return ExactClaimResult::Cancelled;
        }
        claimed
    }

    /// Parent-end inflight cancel, sticky external setup cancel, or buffered
    /// external-handle cancel for the exact-claim poll / setup checkpoints.
    /// Pre-cancel buffer take is single-shot and sticky-marks the inflight so
    /// subsequent checkpoints still observe cancel after consumption.
    async fn exact_claim_cancel_observed(
        &self,
        inflight_id: Option<u64>,
        external_handle: Option<&str>,
    ) -> bool {
        if let Some(id) = inflight_id {
            if self.inflight_is_canceled(id).await {
                return true;
            }
            {
                let inner = self.pending.inner.lock().await;
                if inner.inflight_external_canceled(id) {
                    return true;
                }
            }
        }
        if let Some(handle) = external_handle {
            if self.take_pre_canceled_handle(handle).await {
                if let Some(id) = inflight_id {
                    let mut inner = self.pending.inner.lock().await;
                    inner.mark_inflight_external_canceled_by_id(id);
                }
                return true;
            }
        }
        false
    }

    /// Setup-window **external** cancel for durable admission / launch
    /// checkpoints. Observes the sticky inflight marker and the pre-cancel
    /// buffer only (parent-end is handled separately via `take_inflight_cancel`
    /// so stable root codes are preserved).
    async fn setup_external_cancel_observed(
        &self,
        inflight_id: u64,
        external_handle: Option<&str>,
    ) -> bool {
        {
            let inner = self.pending.inner.lock().await;
            if inner.inflight_external_canceled(inflight_id) {
                return true;
            }
        }
        let Some(handle) = external_handle else {
            return false;
        };
        if self.take_pre_canceled_handle(handle).await {
            let mut inner = self.pending.inner.lock().await;
            inner.mark_inflight_external_canceled_by_id(inflight_id);
            true
        } else {
            // cancel_by_external_handle may sticky-mark during the take race.
            let inner = self.pending.inner.lock().await;
            inner.inflight_external_canceled(inflight_id)
        }
    }

    /// Remove `handle` from the pre-cancel set, returning whether it was
    /// present. Used by `handle_request` at two checkpoints (entry + just
    /// after pending registration) so a cancel that lost the race with the
    /// MCP round-trip still wins. The set is single-shot per handle —
    /// taking it here means a subsequent `cancel_by_external_handle` will
    /// have to find the pending entry on its own.
    async fn take_pre_canceled_handle(&self, handle: &str) -> bool {
        let mut state = self.pre_canceled_handles.inner.lock().await;
        if state.set.remove(handle) {
            // Best-effort companion-side cleanup of `order` so a later
            // FIFO eviction doesn't burn a slot. Linear scan is fine —
            // PRE_CANCELED_CAP is small.
            if let Some(pos) = state.order.iter().position(|h| h == handle) {
                state.order.remove(pos);
            }
            true
        } else {
            false
        }
    }

    /// Insert `handle` into the pre-cancel set with FIFO eviction at
    /// [`PRE_CANCELED_CAP`]. Idempotent — re-inserting an existing handle
    /// is a no-op.
    async fn buffer_pre_canceled_handle(&self, handle: String) {
        let mut state = self.pre_canceled_handles.inner.lock().await;
        if !state.set.insert(handle.clone()) {
            return;
        }
        state.order.push_back(handle);
        while state.order.len() > PRE_CANCELED_CAP {
            if let Some(evicted) = state.order.pop_front() {
                state.set.remove(&evicted);
            }
        }
    }

    /// Forget every pending and recently-consumed tool_call id for the
    /// given parent. Called when the parent connection tears down so
    /// stale ids don't bind to a future reuse of the same connection_id
    /// (UUIDs make that unlikely but cheap to defend against), and so a
    /// fresh connection on the reused id is not blocked by the
    /// consumed memory of the previous one.
    pub async fn drop_pending_tool_calls_for_parent(&self, parent_connection_id: &str) {
        self.drop_tool_calls_for_parent(parent_connection_id, false)
            .await;
    }

    /// Core of the tool_call-tracker drop, shared by the two cancel scopes.
    ///
    /// * `keep_consumed == false` — genuine connection teardown: remove the
    ///   whole bucket (`pending` + `consumed`). The connection is going away,
    ///   so nothing it remembered can mis-bind a future delegation, and a
    ///   reused connection_id must start clean.
    /// * `keep_consumed == true` — turn/prompt cancel with the parent
    ///   connection STILL ALIVE: TOMBSTONE the cancelled turn's unclaimed
    ///   `pending` ids into `consumed` and RETAIN the existing `consumed`. Both
    ///   the already-claimed ids AND the just-cancelled turn's unclaimed ids
    ///   must keep rejecting a host re-emit (e.g. a terminal status-flip): the
    ///   Tier-1 consumed check in `register_pending_tool_call_with_key_at` drops
    ///   the re-emit, so a stale id can't re-register as fresh `pending` and
    ///   mis-bind the next same-key delegation on this live connection. Merely
    ///   CLEARING the unclaimed ids would leave them re-registerable, reopening
    ///   that hole for the unclaimed half (the claimed half was already safe via
    ///   `consumed`). Retention is connection-scoped and released on teardown —
    ///   the same unbounded-but-bounded-by-delegation-count envelope `consumed`
    ///   already lives in for normal end_turn delegations (see
    ///   [`ToolCallTrackerBucket`]).
    ///
    /// Tombstoning ALL of `pending` here is safe (no turn/generation tag
    /// needed): `run_conversation_loop` drives at most ONE `session/prompt`
    /// future per connection at a time (see `acp/connection.rs`), and a
    /// parent-side `tool_call` only streams while its prompt future is in
    /// flight, so every `pending` id belongs to the single active turn — the one
    /// being cancelled — or is a stale leftover from an earlier turn that should
    /// be tombstoned regardless. (The per-connection `prompt_lock` only
    /// serializes the prompt-SEND handshake, not the turn, so it is NOT the
    /// source of this invariant.) The cancelled turn's serialized MCP round-trip
    /// won't arrive after cancel, so nothing legitimate is lost.
    async fn drop_tool_calls_for_parent(&self, parent_connection_id: &str, keep_consumed: bool) {
        let mut map = self.tool_calls.inner.lock().await;
        if !keep_consumed {
            map.remove(parent_connection_id);
            return;
        }
        if let Some(bucket) = map.get_mut(parent_connection_id) {
            // Tombstone the cancelled turn's unclaimed pending ids into
            // `consumed` rather than just dropping them, so a later host re-emit
            // of one is rejected by the Tier-1 consumed check instead of
            // re-registering as a claimable stale entry. `drain` empties
            // `pending` first so the subsequent `consumed` borrow is disjoint.
            let now = Instant::now();
            let cleared: Vec<String> = bucket.pending.drain(..).map(|p| p.tool_call_id).collect();
            for id in cleared {
                if !bucket.consumed.iter().any(|(c, _)| c == &id) {
                    bucket.consumed.push_back((id, now));
                }
            }
            // Drop the now-empty bucket only when nothing consumed remains —
            // otherwise keep it so the retained `consumed` ids keep rejecting
            // re-emits for the rest of this connection's lifetime.
            if bucket.consumed.is_empty() {
                map.remove(parent_connection_id);
            }
        }
    }

    pub async fn set_config(&self, cfg: DelegationConfig) {
        let cap_bytes = cfg.completed_cache_cap_bytes;
        *self.config.lock().await = cfg;
        // Seed the byte cap into the pending-calls bucket so `insert_completed`
        // reads it lock-free (it already holds the pending lock). Acquired AFTER
        // the config guard above is dropped — sequential, never nested — so no
        // path locks `config` under `pending` or vice-versa (deadlock-free).
        // Then prune existing per-parent caches: a LOWERED cap must free memory
        // now, not lazily on each parent's next completion (which may never
        // arrive for an idle parent).
        let mut inner = self.pending.inner.lock().await;
        inner.completed_cap_bytes = cap_bytes;
        inner.enforce_completed_cap_all_parents();
    }

    pub async fn set_profiles(&self, profiles: BTreeMap<String, DelegationProfile>) {
        self.config.lock().await.profiles = profiles;
    }

    pub async fn config_snapshot(&self) -> DelegationConfig {
        self.config.lock().await.clone()
    }

    /// Record profile UUIDs mentioned in the parent user prompt for this
    /// connection. Empty `profile_ids` clears the mandatory set (normal send
    /// without profile mentions). Synchronous so callers can install routes
    /// between prompt admission and enqueue without introducing an await.
    pub fn set_mandatory_profile_routes(
        &self,
        parent_connection_id: &str,
        profile_ids: impl IntoIterator<Item = String>,
    ) {
        let mut map = self
            .mandatory_profile_routes
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let set: BTreeSet<String> = profile_ids.into_iter().collect();
        if set.is_empty() {
            map.remove(parent_connection_id);
        } else {
            map.insert(parent_connection_id.to_string(), set);
        }
    }

    pub fn clear_mandatory_profile_routes(&self, parent_connection_id: &str) {
        self.mandatory_profile_routes
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .remove(parent_connection_id);
    }

    fn mandatory_profile_routes_for(&self, parent_connection_id: &str) -> BTreeSet<String> {
        self.mandatory_profile_routes
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .get(parent_connection_id)
            .cloned()
            .unwrap_or_default()
    }

    /// If this in-flight setup has been flagged by a parent end, deregister it
    /// and return the stable root reason. One lock acquisition; used at the
    /// pre-spawn / post-spawn checkpoints in `handle_request`.
    async fn take_inflight_cancel(&self, inflight_id: u64) -> Option<ParentEndContext> {
        let mut inner = self.pending.inner.lock().await;
        let context = inner
            .inflight_parent_end(inflight_id)
            .map(|end| end.context);
        if context.is_some() {
            inner.deregister_inflight(inflight_id);
        }
        context
    }

    /// Drop this setup's in-flight record. Called on each `handle_request`
    /// early-return that isn't a park hand-off (the park region deregisters
    /// inline, atomically with `calls.insert`).
    async fn drop_inflight(&self, inflight_id: u64) {
        self.pending
            .inner
            .lock()
            .await
            .deregister_inflight(inflight_id);
    }

    /// Async entry point for `delegate_to_agent`. Does the bounded setup
    /// (claim/depth checks → spawn → send first prompt), registers the task in
    /// `running`, and returns a `Running` ack [`DelegationTaskReport`] WITHOUT
    /// waiting for the child to finish. The child resolves later via the
    /// lifecycle → [`complete_call`] (or a cancel path), which migrates the task
    /// into `completed` and wakes any `get_delegation_status` long-poll.
    ///
    /// Returns a terminal report instead of a `Running` ack in three cases: the
    /// child finished during setup (fast/empty turn), a parent cancel reached it
    /// mid-setup, or setup itself failed (disabled / depth / spawn / send).
    ///
    /// All the setup-window race machinery (`setups` / `early_*` / `inflight`)
    /// is unchanged — it governs terminals that beat registration, which is
    /// orthogonal to whether the caller then blocks. The only change vs. the old
    /// `handle_request` is that "park a `oneshot` and await it" becomes "insert a
    /// [`RunningTask`] and return the ack."
    #[tracing::instrument(
        name = "delegation_task",
        skip_all,
        fields(
            parent_connection_id = %req.parent_connection_id,
            parent_tool_use_id = %req.parent_tool_use_id,
            agent_type = ?req.agent_type,
            working_dir = ?req.working_dir,
            child_connection_id = tracing::field::Empty,
            task_id = tracing::field::Empty,
        )
    )]
    pub async fn start_delegation(&self, mut req: DelegationRequest) -> DelegationTaskReport {
        // Whitespace-only host tool ids are treated as absent so exact
        // correlation (argument `correlation_id`) is used rather than the
        // explicit-id path. Nonblank host ids are opaque and must not be
        // trimmed. Listener also applies this rule for MCP callers.
        if req.parent_tool_use_id.trim().is_empty() {
            req.parent_tool_use_id.clear();
        }
        // Register this setup as the VERY FIRST thing — before the pre-cancel
        // check's `.await` and the (possibly multi-second) claim poll — so a
        // parent cancel landing ANYWHERE from here to park reaches it, not just
        // after park (which is all the `cancel_by_parent*` parked-call drain
        // covers on its own). The only residual gap is a cancel firing before
        // the broker is even invoked for this request, which no
        // in-`handle_request` mechanism can observe. Deregistered on every exit
        // path below: each early-return via `drop_inflight` /
        // `take_inflight_cancel`, or inline at park (atomically with
        // `calls.insert`).
        let inflight_id = self
            .pending
            .inner
            .lock()
            .await
            .register_inflight(&req.parent_connection_id, req.external_handle.clone());
        // Pre-cancel short-circuit. If the MCP companion already received
        // `notifications/cancelled` for this `tools/call` before we even
        // started processing (cancel ran ahead of the UDS round-trip), we
        // claim the handle from the pre-cancel set and bail without
        // spawning anything — the caller will not be receiving our
        // response either way (the companion suppresses it per MCP spec).
        if let Some(handle) = req.external_handle.as_deref() {
            if self.take_pre_canceled_handle(handle).await {
                self.drop_inflight(inflight_id).await;
                // Bailing here BEFORE the claim path means this delegation never
                // consumes the ACP `tool_call_id` the lifecycle keyed for it. As
                // keyed entries are retained indefinitely, a leftover would let a
                // *later* same-`(agent_type, task, working_dir)` delegation claim
                // this canceled call's id and bind its writes/events to the wrong
                // card. Drain only a *unique* key match — first-match would steal
                // a sibling card under an ambiguous key (fail-closed retain).
                if req.parent_tool_use_id.is_empty() {
                    let key = DelegationMatchKey::Delegate {
                        correlation_id: req.correlation_id.clone().unwrap_or_default(),
                        agent_type: req.agent_type,
                        task: req.task.clone(),
                        working_dir: req.requested_working_dir.clone(),
                    };
                    let _ = self
                        .take_unique_matching_tool_call(&req.parent_connection_id, &key)
                        .await;
                } else {
                    self.consume_explicit_tool_call(
                        &req.parent_connection_id,
                        &req.parent_tool_use_id,
                    )
                    .await;
                }
                return report_err(
                    req.agent_type,
                    DelegationError::Canceled {
                        reason: "canceled before spawn".into(),
                    },
                    None,
                );
            }
        }
        // MCP clients often omit `_meta.tool_use_id`. Correlate by typed exact
        // key (wait-out-budget) — never FIFO and never mint a synthetic parent
        // id. Explicit host id remains authoritative and does not require
        // `correlation_id`.
        if req.parent_tool_use_id.is_empty() {
            let corr = req.correlation_id.as_deref().unwrap_or("");
            if validate_correlation_id(corr).is_err() {
                self.drop_inflight(inflight_id).await;
                return report_err(
                    req.agent_type,
                    DelegationError::CorrelationMissing(correlation_error_message(
                        CorrelationFailureKind::Missing,
                        CorrelationEntryPoint::DelegateToAgent,
                    )),
                    None,
                );
            }
            let match_key = DelegationMatchKey::Delegate {
                correlation_id: corr.to_string(),
                agent_type: req.agent_type,
                task: req.task.clone(),
                working_dir: req.requested_working_dir.clone(),
            };
            let claim = self
                .resolve_exact_claim(
                    &req.parent_connection_id,
                    &match_key,
                    Some(inflight_id),
                    req.external_handle.as_deref(),
                )
                .await;
            match claim {
                ExactClaimResult::Matched(id) => {
                    req.parent_tool_use_id = id;
                }
                ExactClaimResult::Cancelled => {
                    // Preserve stable parent-end codes when inflight was marked;
                    // external-handle cancel falls through to generic canceled.
                    if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
                        return parent_end_setup_report(req.agent_type, reason, None);
                    }
                    self.drop_inflight(inflight_id).await;
                    // Unique-only drain: never first-match under an ambiguous key.
                    let _ = self
                        .take_unique_matching_tool_call(&req.parent_connection_id, &match_key)
                        .await;
                    return report_err(
                        req.agent_type,
                        DelegationError::Canceled {
                            reason: "canceled during parent-tool correlation".into(),
                        },
                        None,
                    );
                }
                ExactClaimResult::Ambiguous => {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        req.agent_type,
                        DelegationError::CorrelationAmbiguous(correlation_error_message(
                            CorrelationFailureKind::Ambiguous,
                            CorrelationEntryPoint::DelegateToAgent,
                        )),
                        None,
                    );
                }
                ExactClaimResult::Conflict => {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        req.agent_type,
                        DelegationError::CorrelationConflict(correlation_error_message(
                            CorrelationFailureKind::Conflict,
                            CorrelationEntryPoint::DelegateToAgent,
                        )),
                        None,
                    );
                }
                ExactClaimResult::Missing => {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        req.agent_type,
                        DelegationError::CorrelationTimeout(correlation_error_message(
                            CorrelationFailureKind::Timeout,
                            CorrelationEntryPoint::DelegateToAgent,
                        )),
                        None,
                    );
                }
            }
        } else {
            // The client gave us the real ACP tool_call_id directly
            // (`_meta.tool_use_id`), so we skip the key claim path — but the
            // lifecycle dispatcher may already have registered that same id as
            // a (now indefinitely-retained) keyed pending entry. Consume it so
            // it can't linger and be mis-claimed by a later same-key
            // delegation. Idempotent and order-independent (see the method).
            // Explicit id does not require correlation_id.
            self.consume_explicit_tool_call(&req.parent_connection_id, &req.parent_tool_use_id)
                .await;
        }
        // Claim-to-spawn transition: parent end or notifications/cancelled may
        // have won during (or after) exact claim without a `running` task yet.
        // Bail before depth/reserve/create so cancel during correlation never
        // creates a child reservation.
        if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
            return parent_end_setup_report(req.agent_type, reason, None);
        }
        if self
            .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
            .await
        {
            self.drop_inflight(inflight_id).await;
            return report_err(
                req.agent_type,
                DelegationError::Canceled {
                    reason: "canceled before spawn".into(),
                },
                None,
            );
        }

        // Resolve archived ownership before completion-format repair, depth,
        // child allocation, budget, authorization, or task-run reservation.
        // The transaction fence in RunStore remains the race backstop.
        if let Some(runs) = self.run_store.as_ref() {
            if let Err(error) = require_writable_conversation_workflow(
                &runs.db().conn,
                req.parent_conversation_id,
            )
            .await
            {
                self.drop_inflight(inflight_id).await;
                return report_err(
                    req.agent_type,
                    workflow_store_error_to_delegation_error(error),
                    None,
                );
            }
        }

        if let (Some(source_task_id), Some(runs)) =
            (req.replaces_task_id.as_deref(), self.run_store.as_ref())
        {
            if is_completion_format_repair_prompt(&req.task) {
                match runs.terminal_completion_protocol(source_task_id).await {
                    Ok(TerminalCompletionProtocol::V2) => {
                        let mode = crate::db::entities::delegation_workflow::CompletionProtocolMode::V2Enforce;
                        self.metrics.record_format_repair_child_run(mode.clone());
                        self.metrics.record_card_reemit_prompt(mode);
                        self.drop_inflight(inflight_id).await;
                        return report_err(
                            req.agent_type,
                            DelegationError::WorkflowAdmission {
                                code: "completion_format_repair_forbidden".into(),
                                message: "protocol v2 completion is platform-generated".into(),
                            },
                            None,
                        );
                    }
                    Ok(TerminalCompletionProtocol::Standalone) => {}
                    Err(error) => {
                        self.drop_inflight(inflight_id).await;
                        return report_err(
                            req.agent_type,
                            store_err_to_delegation_error(error),
                            None,
                        );
                    }
                }
            }
        }
        let cfg = self.config_snapshot().await;
        if !cfg.enabled {
            self.drop_inflight(inflight_id).await;
            return report_err(
                req.agent_type,
                DelegationError::Canceled {
                    reason: "delegation disabled".into(),
                },
                None,
            );
        }

        // --- Depth pre-check ----------------------------------------------------
        // We walk up to `limit + 1` so we know whether the *new* child would
        // sit at >= limit. Cycles/dead chains saturate at the cap.
        let lookup = self.depth_lookup.clone();
        let parent_depth = match crate::acp::delegation::depth::compute_depth(
            req.parent_conversation_id,
            |id| {
                let lookup = lookup.clone();
                async move { lookup.parent_of(id).await }
            },
            cfg.depth_limit + 1,
        )
        .await
        {
            Ok(d) => d,
            Err(e) => {
                self.drop_inflight(inflight_id).await;
                return report_err(req.agent_type, e, None);
            }
        };
        // The child the broker is about to create would sit at `parent_depth + 1`.
        // Reject only when the *child* depth would strictly exceed the limit;
        // a child sitting exactly at `depth_limit` is allowed.
        if parent_depth + 1 > cfg.depth_limit {
            self.drop_inflight(inflight_id).await;
            return report_err(
                req.agent_type,
                DelegationError::DepthLimitExceeded {
                    current_depth: parent_depth,
                    limit: cfg.depth_limit,
                },
                None,
            );
        }

        // --- Spawn child connection --------------------------------------------
        // Pull per-agent overrides from the broker config (defaults to empty).
        // Cloning is cheap — `AgentDelegationDefaults` is at most one Option<String>
        // and a small BTreeMap, and the spawner consumes both fields by value.
        //
        // When the parent user prompt mentioned profiles, soft prompt routing is
        // hardened here **per agent_type** (type-scoped set `M_T`):
        // - build M_T = mandatory UUIDs whose config profile matches req.agent_type
        //   (disabled profiles still count for gate presence; missing config
        //   ids are skipped — fail-open for that id)
        // - if M_T is empty, this agent_type is unconstrained by the mention set
        //   (base defaults / optional non-mentioned profiles allowed)
        // - if M_T is non-empty:
        //   - omitted profile_id → auto-fill only when a unique *enabled* match
        //     exists in M_T; otherwise fail closed (incl. all-disabled)
        //   - explicit profile_id must be in M_T (no substitute profile for
        //     this agent_type)
        let mandatory = self.mandatory_profile_routes_for(&req.parent_connection_id);
        if !mandatory.is_empty() {
            let mut unresolved: Vec<&String> = Vec::new();
            let mandatory_for_type: BTreeSet<String> = mandatory
                .iter()
                .filter_map(|id| match cfg.profiles.get(id) {
                    Some(p) if p.agent_type == req.agent_type => Some(id.clone()),
                    Some(_) => None,
                    None => {
                        unresolved.push(id);
                        None
                    }
                })
                .collect();
            if !unresolved.is_empty() {
                tracing::warn!(
                    parent_connection_id = %req.parent_connection_id,
                    agent_type = %agent_type_wire(req.agent_type),
                    unresolved_count = unresolved.len(),
                    unresolved = ?unresolved,
                    "[delegation] skipping mandatory profile ids missing from config (fail-open for those ids)"
                );
            }
            if mandatory_for_type.is_empty() {
                tracing::debug!(
                    parent_connection_id = %req.parent_connection_id,
                    agent_type = %agent_type_wire(req.agent_type),
                    mandatory_count = mandatory.len(),
                    "[delegation] mandatory routes active but none for this agent_type; allowing unscoped path"
                );
            } else {
                let t = agent_type_wire(req.agent_type);
                let list_m_t = mandatory_for_type
                    .iter()
                    .cloned()
                    .collect::<Vec<_>>()
                    .join(", ");
                if let Some(profile_id) = req.profile_id.as_deref() {
                    if !mandatory_for_type.contains(profile_id) {
                        self.drop_inflight(inflight_id).await;
                        return report_err(
                            req.agent_type,
                            DelegationError::MandatoryProfileRequired(format!(
                                "profile_id {profile_id} is not among mandatory routes for agent_type={t}: {list_m_t}"
                            )),
                            None,
                        );
                    }
                } else {
                    let matches: Vec<&DelegationProfile> = mandatory_for_type
                        .iter()
                        .filter_map(|id| cfg.profiles.get(id))
                        .filter(|p| p.enabled)
                        .collect();
                    if matches.len() == 1 {
                        req.profile_id = Some(matches[0].id.clone());
                    } else {
                        self.drop_inflight(inflight_id).await;
                        return report_err(
                            req.agent_type,
                            DelegationError::MandatoryProfileRequired(format!(
                                "for agent_type={t} (ambiguous or missing): {list_m_t}"
                            )),
                            None,
                        );
                    }
                }
            }
        }
        let (preferred_mode_id, preferred_config_values) =
            if let Some(profile_id) = req.profile_id.as_deref() {
                let Some(profile) = cfg.profiles.get(profile_id) else {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        req.agent_type,
                        DelegationError::InvalidDelegationProfile(profile_id.into()),
                        None,
                    );
                };
                if !profile.enabled {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        req.agent_type,
                        DelegationError::DelegationProfileDisabled(profile_id.into()),
                        None,
                    );
                }
                if profile.agent_type != req.agent_type {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        req.agent_type,
                        DelegationError::DelegationProfileAgentMismatch(profile_id.into()),
                        None,
                    );
                }
                (profile.mode_id.clone(), profile.config_values.clone())
            } else {
                cfg.agent_defaults
                    .get(&req.agent_type)
                    .map(|d: &AgentDelegationDefaults| (d.mode_id.clone(), d.config_values.clone()))
                    .unwrap_or((None, BTreeMap::new()))
            };
        // Live secret re-resolution: preferred_config_values may include
        // credentials. build_live_launch_config keeps them for spawn while
        // the durable snapshot stores allowlisted non-secret keys only.
        let workspace_path = match resolve_workspace_path(req.working_dir.as_deref()) {
            Ok(path) => path,
            Err(message) => {
                self.drop_inflight(inflight_id).await;
                return report_err(
                    req.agent_type,
                    DelegationError::InvalidWorkingDir(message),
                    None,
                );
            }
        };
        // Use the one canonical value for fingerprinting, durable persistence,
        // runtime statistics, and the actual child process cwd.
        req.working_dir = Some(workspace_path.clone());
        let live_launch = build_live_launch_config(
            req.agent_type,
            req.profile_id.as_deref(),
            &workspace_path,
            preferred_mode_id,
            preferred_config_values,
        );
        let route_fp = live_launch.snapshot.route_fingerprint.clone();
        let request_fp = request_fingerprint(
            DELEGATE_TO_AGENT_TOOL,
            &req.task,
            req.work_unit_key.as_deref(),
            req.replaces_task_id.as_deref(),
            req.replacement_reason.as_deref(),
            None,
            &route_fp,
        );

        // Parent-tool exact-duplicate handling BEFORE reserve/spawn (design
        // precedence). Matching fingerprint → idempotent running ack without
        // creating a new child; mismatch → reject.
        if let Some(runs) = self.run_store.as_ref() {
            if !req.parent_tool_use_id.is_empty() {
                match runs
                    .load_by_parent_tool_use(req.parent_conversation_id, &req.parent_tool_use_id)
                    .await
                {
                    Ok(Some(existing)) => match existing.request_fingerprint.as_deref() {
                        Some(prev) if prev == request_fp => {
                            self.drop_inflight(inflight_id).await;
                            return gen1_idempotent_ack(&existing);
                        }
                        _ => {
                            self.drop_inflight(inflight_id).await;
                            return report_err(
                                req.agent_type,
                                DelegationError::DuplicateParentTool(
                                    req.parent_tool_use_id.clone(),
                                ),
                                Some(existing.child_conversation_id),
                            );
                        }
                    },
                    Ok(None) => {}
                    Err(e) => {
                        tracing::warn!(
                            error = %e,
                            "[delegation] parent_tool lookup failed; continuing to reserve"
                        );
                    }
                }
            }
        }

        #[cfg(any(test, feature = "test-utils"))]
        {
            LiveRuntimeState::honor_gate(&self.gen1_post_precheck_gate).await;
        }

        // Pre-create cancel fence: parent end / external cancel after claim
        // (and after the post-precheck gate) must not allocate a provisional
        // child. Binding invariant: cancel during setup ⇒ no child creation.
        if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
            return parent_end_setup_report(req.agent_type, reason, None);
        }
        if self
            .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
            .await
        {
            self.drop_inflight(inflight_id).await;
            return report_err(
                req.agent_type,
                DelegationError::Canceled {
                    reason: "canceled before spawn".into(),
                },
                None,
            );
        }

        // Bounded task label used by the started event and every meta write —
        // the frontend card's fallback when the parent tool call's `raw_input`
        // never carried the arguments (Cursor's identity-less announcements).
        let task_preview = truncate_on_char_boundary(&req.task, TASK_PREVIEW_CAP);
        // call_id / task_id is allocated before durable reserve so the gen-1
        // fence and child conversation share one identity.
        let call_id = uuid::Uuid::new_v4().to_string();
        tracing::Span::current().record("task_id", call_id.as_str());

        // Durable gen-1 fingerprint / work-unit fence BEFORE spawn/dispatch
        // so concurrent losers never execute child work (Codex I1).
        // Pre-create the child conversation so the reserving row can satisfy
        // the NOT NULL child_conversation_id FK; send adopts that row.
        let mut prebound_child: Option<(i32, i32)> = None;
        if let Some(runs) = self.run_store.as_ref() {
            let agent_type_str = serde_json::to_value(req.agent_type)
                .ok()
                .and_then(|v| v.as_str().map(String::from))
                .unwrap_or_else(|| format!("{:?}", req.agent_type).to_ascii_lowercase());
            let durable_preview = derive_task_preview(&req.task);
            let folder_path = if workspace_path.trim().is_empty() {
                format!("codeg-delegation-reserve-{call_id}")
            } else {
                workspace_path.clone()
            };
            // RegistrationOnly: durable reserve only needs a folder_id FK for
            // the hidden child conversation. Never ForceOpen just because a
            // hidden child row is being created (product surfaces folders via
            // explicit user open / other paths).
            let folder = match crate::db::service::folder_service::ensure_folder(
                &runs.db().conn,
                &folder_path,
                crate::db::service::folder_service::EnsureFolderMode::RegistrationOnly,
            )
            .await
            {
                Ok(f) => f,
                Err(e) => {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        req.agent_type,
                        DelegationError::SpawnFailed(format!("reserve folder: {e}")),
                        None,
                    );
                }
            };
            let child_row = match crate::db::service::conversation_service::create_with_delegation(
                &runs.db().conn,
                folder.id,
                req.agent_type,
                Some(task_preview.clone()),
                None,
                Some(DelegationLink {
                    parent_conversation_id: req.parent_conversation_id,
                    parent_tool_use_id: req.parent_tool_use_id.clone(),
                    delegation_call_id: call_id.clone(),
                }),
            )
            .await
            {
                Ok(row) => row,
                Err(e) => {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        req.agent_type,
                        DelegationError::SpawnFailed(format!("reserve child conversation: {e}")),
                        None,
                    );
                }
            };
            // Cancel after create / before admission: compensate the unused shell
            // rather than admitting a run we will immediately cancel.
            if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
                if let Err(cleanup_err) = self
                    .compensate_provisional_orphan(
                        &runs.db().conn,
                        child_row.id,
                        "cancel after create",
                    )
                    .await
                {
                    self.drop_inflight(inflight_id).await;
                    return report_err(req.agent_type, cleanup_err, Some(child_row.id));
                }
                self.drop_inflight(inflight_id).await;
                return parent_end_setup_report(req.agent_type, reason, Some(child_row.id));
            }
            if self
                .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
                .await
            {
                if let Err(cleanup_err) = self
                    .compensate_provisional_orphan(
                        &runs.db().conn,
                        child_row.id,
                        "external cancel after create",
                    )
                    .await
                {
                    self.drop_inflight(inflight_id).await;
                    return report_err(req.agent_type, cleanup_err, Some(child_row.id));
                }
                self.drop_inflight(inflight_id).await;
                return report_err(
                    req.agent_type,
                    DelegationError::Canceled {
                        reason: "canceled before spawn".into(),
                    },
                    Some(child_row.id),
                );
            }
            // Replacement: inherit lineage root from replaced run; admission_class
            // is Replacement. Otherwise normal gen-1 root.
            let (admission_class, lineage_root_task_id, root_task_id) = if let Some(replaces) =
                req.replaces_task_id.as_deref()
            {
                match runs.load_by_task_id(replaces).await {
                    Ok(Some(src)) => (
                        AdmissionClass::Replacement,
                        src.lineage_root_task_id.clone(),
                        // Replacement is a fresh generation-1 child
                        // thread; only the lineage root is inherited.
                        call_id.clone(),
                    ),
                    Ok(None) => {
                        // Post-create / pre-admission: compensate the unused shell.
                        if let Err(cleanup_err) = self
                            .compensate_provisional_orphan(
                                &runs.db().conn,
                                child_row.id,
                                "replacement source missing",
                            )
                            .await
                        {
                            self.drop_inflight(inflight_id).await;
                            return report_err(req.agent_type, cleanup_err, Some(child_row.id));
                        }
                        self.drop_inflight(inflight_id).await;
                        return report_err(
                            req.agent_type,
                            DelegationError::NotFound(replaces.to_string()),
                            None,
                        );
                    }
                    Err(e) => {
                        // Store error after create: still compensate the orphan
                        // child so it never remains a visible running shell.
                        if let Err(cleanup_err) = self
                            .compensate_provisional_orphan(
                                &runs.db().conn,
                                child_row.id,
                                "replacement source load error",
                            )
                            .await
                        {
                            self.drop_inflight(inflight_id).await;
                            return report_err(req.agent_type, cleanup_err, Some(child_row.id));
                        }
                        self.drop_inflight(inflight_id).await;
                        return report_err(req.agent_type, store_err_to_delegation_error(e), None);
                    }
                }
            } else {
                (
                    AdmissionClass::NormalRevision,
                    call_id.clone(),
                    call_id.clone(),
                )
            };
            let insert = ReservingRunInsert {
                task_id: call_id.clone(),
                root_task_id,
                previous_task_id: None,
                generation: 1,
                parent_conversation_id: req.parent_conversation_id,
                parent_tool_use_id: if req.parent_tool_use_id.is_empty() {
                    None
                } else {
                    Some(req.parent_tool_use_id.clone())
                },
                child_conversation_id: child_row.id,
                agent_type: agent_type_str,
                profile_id: live_launch.snapshot.profile_id.clone(),
                workspace_path: Some(live_launch.snapshot.workspace_path.clone()),
                route_fingerprint: Some(live_launch.snapshot.route_fingerprint.clone()),
                launch_snapshot_version: Some(live_launch.snapshot.launch_snapshot_version.clone()),
                mode_id: live_launch.snapshot.mode_id.clone(),
                config_values_json: Some(live_launch.snapshot.config_values_json.clone()),
                task_preview: Some(durable_preview),
                request_fingerprint: Some(request_fp.clone()),
                admission_class,
                lineage_root_task_id,
                work_unit_key: req.work_unit_key.clone(),
                history_only: false,
                replaced_task_id: req.replaces_task_id.clone(),
                replacement_reason: req.replacement_reason.clone(),
                started_at: Some(Utc::now()),
            };
            // Pre-admit cancel gate: parent end or external cancel during
            // replacement load (or any post-create await above) must compensate
            // without inserting a run. Test-only hold pins this window.
            #[cfg(any(test, feature = "test-utils"))]
            {
                LiveRuntimeState::honor_gate(&self.gen1_pre_admit_gate).await;
            }
            if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
                if let Err(cleanup_err) = self
                    .compensate_provisional_orphan(
                        &runs.db().conn,
                        child_row.id,
                        "cancel before admit",
                    )
                    .await
                {
                    self.drop_inflight(inflight_id).await;
                    return report_err(req.agent_type, cleanup_err, Some(child_row.id));
                }
                self.drop_inflight(inflight_id).await;
                return parent_end_setup_report(req.agent_type, reason, Some(child_row.id));
            }
            if self
                .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
                .await
            {
                if let Err(cleanup_err) = self
                    .compensate_provisional_orphan(
                        &runs.db().conn,
                        child_row.id,
                        "external cancel before admit",
                    )
                    .await
                {
                    self.drop_inflight(inflight_id).await;
                    return report_err(req.agent_type, cleanup_err, Some(child_row.id));
                }
                self.drop_inflight(inflight_id).await;
                return report_err(
                    req.agent_type,
                    DelegationError::Canceled {
                        reason: "canceled before spawn".into(),
                    },
                    Some(child_row.id),
                );
            }
            let authorization = RecoveryAdmissionAuthorization {
                authorization_id: req.recovery_authorization_id.clone(),
                correlation_id: req
                    .correlation_id
                    .clone()
                    .or_else(|| {
                        (!req.parent_tool_use_id.is_empty()).then(|| req.parent_tool_use_id.clone())
                    })
                    .unwrap_or_else(|| call_id.clone()),
            };
            let admitted = match runs
                .admit_gen1_reserving_authorized(insert, authorization)
                .await
            {
                Ok(Gen1AdmitOutcome::AuthorizedCreated {
                    run,
                    recovery_decision,
                }) => {
                    let projection = DelegationRecoveryProjection::from(&recovery_decision);
                    if let Some(authorization_id) = run.recovery_authorization_id.as_deref() {
                        self.record_recovery_event(
                            RecoveryMetricEventKind::Decision,
                            Some(&run.task_id),
                            Some(authorization_id),
                            Some(run.parent_conversation_id),
                            Some(run.child_conversation_id),
                            projection.proposed_action.as_deref(),
                            Some(&projection.cause_code),
                            Some(&projection.risk_class),
                            None,
                        );
                    }
                    Ok(Gen1AdmitOutcome::Created(run))
                }
                other => other,
            };
            match admitted {
                Ok(Gen1AdmitOutcome::Created(run)) => {
                    if let Some(authorization_id) = run.recovery_authorization_id.as_deref() {
                        for kind in [
                            RecoveryMetricEventKind::ConfirmationApproved,
                            RecoveryMetricEventKind::AuthorizationConsumed,
                        ] {
                            self.record_recovery_event(
                                kind,
                                Some(&run.task_id),
                                Some(authorization_id),
                                Some(run.parent_conversation_id),
                                Some(run.child_conversation_id),
                                Some("replace"),
                                None,
                                None,
                                None,
                            );
                        }
                    }
                    if run.replaced_task_id.is_some() {
                        self.record_recovery_event(
                            RecoveryMetricEventKind::ReplacementAdmitted,
                            Some(&run.task_id),
                            run.recovery_authorization_id.as_deref(),
                            Some(run.parent_conversation_id),
                            Some(run.child_conversation_id),
                            Some("replace"),
                            None,
                            None,
                            None,
                        );
                    }
                    // Post-commit / pre-spawn window: parent-end durable sweep
                    // may race the pure reserving claim here. Hold for tests.
                    #[cfg(any(test, feature = "test-utils"))]
                    {
                        LiveRuntimeState::honor_gate(&self.gen1_post_admit_gate).await;
                    }
                    // Cancel may have stamped during the admit await (or while
                    // the post-admit gate was held). Prefer abandon+compensate
                    // (including reclaim of just-settled pure provisional
                    // claims) over a durable cancelled run.
                    if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
                        return self
                            .cancel_admitted_gen1_pre_spawn(
                                runs,
                                &run.task_id,
                                child_row.id,
                                reason,
                                req.agent_type,
                                inflight_id,
                                "cancel raced admit commit",
                            )
                            .await;
                    }
                    if self
                        .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
                        .await
                    {
                        return self
                            .cancel_admitted_gen1_pre_spawn_external(
                                runs,
                                &run.task_id,
                                child_row.id,
                                req.agent_type,
                                inflight_id,
                                "external cancel raced admit commit",
                            )
                            .await;
                    }
                    prebound_child = Some((child_row.id, folder.id));
                }
                Ok(Gen1AdmitOutcome::AuthorizedCreated { .. }) => {
                    unreachable!("authorized created outcome normalized above")
                }
                Ok(Gen1AdmitOutcome::Idempotent(existing)) => {
                    // Race after pre-check: matching fingerprint already reserved.
                    // Terminalize + guarded soft-delete the unused provisional
                    // child so it never appears as a visible running sub-session
                    // under the parent.
                    // Fail-closed: never return a successful idempotent running
                    // ack while cleanup failed and the orphan may remain visible.
                    if let Err(cleanup_err) = self
                        .compensate_provisional_orphan(
                            &runs.db().conn,
                            child_row.id,
                            "idempotent admit",
                        )
                        .await
                    {
                        self.drop_inflight(inflight_id).await;
                        return report_err(req.agent_type, cleanup_err, Some(child_row.id));
                    }
                    self.drop_inflight(inflight_id).await;
                    return gen1_idempotent_ack(&existing);
                }
                Err(e) => {
                    self.record_recovery_admission_error(
                        &e,
                        req.replaces_task_id.as_deref().unwrap_or(&call_id),
                        req.parent_conversation_id,
                        Some(child_row.id),
                        "replace",
                    );
                    // Loser of work-unit / unique fence — never dispatch, and
                    // terminalize + hide the provisional InProgress/Running
                    // child so the sidebar and list_children do not show an
                    // orphan. Fail-closed: cleanup failure after retry surfaces
                    // a typed cleanup/terminalize error instead of busy/duplicate
                    // that hides the visible no-run orphan.
                    if let Err(cleanup_err) = self
                        .compensate_provisional_orphan(&runs.db().conn, child_row.id, "fence loss")
                        .await
                    {
                        self.drop_inflight(inflight_id).await;
                        return report_err(req.agent_type, cleanup_err, Some(child_row.id));
                    }
                    self.drop_inflight(inflight_id).await;
                    return report_err(req.agent_type, store_err_to_delegation_error(e), None);
                }
            }
        }

        #[cfg(any(test, feature = "test-utils"))]
        {
            LiveRuntimeState::honor_gate(&self.gen1_before_spawn_checkpoint_gate).await;
        }

        // Checkpoint #1 (opportunistic): if a parent end already landed
        // during the claim/depth/reserve phase, bail before spawning a child
        // the parent has abandoned. For admitted gen-1 pure reserving claims,
        // abandon+compensate (not bare settle) so cancel cannot leave a durable
        // canceled run without the provisional compensation path.
        if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
            if let (Some(runs), Some((child_id, _))) =
                (self.run_store.as_ref(), prebound_child.as_ref())
            {
                return self
                    .cancel_admitted_gen1_pre_spawn(
                        runs,
                        &call_id,
                        *child_id,
                        reason,
                        req.agent_type,
                        inflight_id,
                        "cancel checkpoint before spawn",
                    )
                    .await;
            }
            if let Some(runs) = self.run_store.as_ref() {
                let _ = runs
                    .settle_terminal(
                        &call_id,
                        TerminalTaskWrite::canceled(
                            reason.durable_error_code(),
                            reason.termination.observed_at,
                            reason.audit(
                                DelegationRunStatus::Reserving,
                                AdmissionClass::NormalRevision,
                                Some(req.parent_tool_use_id.clone()),
                                None,
                            ),
                        ),
                    )
                    .await;
            }
            return parent_end_setup_report(
                req.agent_type,
                reason,
                prebound_child.map(|(cid, _)| cid),
            );
        }
        // External cancel immediately before child launch (sticky marker or
        // buffered handle after post-claim).
        if self
            .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
            .await
        {
            if let (Some(runs), Some((child_id, _))) =
                (self.run_store.as_ref(), prebound_child.as_ref())
            {
                return self
                    .cancel_admitted_gen1_pre_spawn_external(
                        runs,
                        &call_id,
                        *child_id,
                        req.agent_type,
                        inflight_id,
                        "external cancel checkpoint before spawn",
                    )
                    .await;
            }
            self.drop_inflight(inflight_id).await;
            return report_err(
                req.agent_type,
                DelegationError::Canceled {
                    reason: "canceled before spawn".into(),
                },
                prebound_child.map(|(cid, _)| cid),
            );
        }
        let (workflow_binding, dispatch_prompt) = match self.run_store.as_ref() {
            Some(runs) => match async {
                let workflow_binding = runs
                    .workflow_child_mcp_binding(&call_id)
                    .await
                    .map_err(WorkflowLaunchLoadError::WorkflowBinding)?;
                let prompt =
                    append_admitted_completion_instruction(&runs.db().conn, &call_id, &req.task)
                        .await
                        .map_err(WorkflowLaunchLoadError::CompletionInstruction)?;
                Ok::<_, WorkflowLaunchLoadError>((workflow_binding, prompt))
            }
            .await
            {
                Ok(workflow_launch) => workflow_launch,
                Err(error) => {
                    tracing::error!(
                        task_id = %call_id,
                        error = %error,
                        "[delegation] workflow instruction binding load failed before gen-1 spawn"
                    );
                    return self
                        .fail_gen1_workflow_binding_load(
                            runs,
                            &call_id,
                            prebound_child
                                .expect("run-backed launch has a prebound child")
                                .0,
                            req.agent_type,
                            inflight_id,
                            &error,
                        )
                        .await;
                }
            },
            None => (None, req.task.clone()),
        };
        let spawn_result = self
            .spawner
            .spawn_with_workflow_binding(
                &req.parent_connection_id,
                req.agent_type,
                req.working_dir.clone(),
                live_launch.preferred_mode_id.clone(),
                live_launch.preferred_config_values.clone(),
                workflow_binding,
            )
            .await;
        let child_connection_id = match spawn_result {
            Ok(id) => id,
            Err(e) => {
                self.drop_inflight(inflight_id).await;
                if let Some(runs) = self.run_store.as_ref() {
                    let _ = runs
                        .settle_terminal(
                            &call_id,
                            failed_terminal(
                                "spawn_failed",
                                DelegationRunStatus::Reserving,
                                false,
                                AcpTerminationSource::Admission,
                                AcpTerminationReason::AdmissionFailed,
                                AcpTerminationClassification::Unexpected,
                            ),
                        )
                        .await;
                }
                return report_err(
                    req.agent_type,
                    DelegationError::SpawnFailed(e.to_string()),
                    prebound_child.map(|(cid, _)| cid),
                );
            }
        };

        // Checkpoint #2: a parent end that landed during spawn() — the child
        // now exists but no prompt has been sent, so disconnect it (mirroring
        // the send-failure path's disconnect-only teardown) and bail. This is
        // the primary guard for the spawn window, which can block while the
        // agent process starts up.
        if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
            let _ = self.spawner.disconnect(&child_connection_id).await;
            if let Some(runs) = self.run_store.as_ref() {
                let _ = runs
                    .settle_terminal(
                        &call_id,
                        TerminalTaskWrite::canceled(
                            reason.durable_error_code(),
                            reason.termination.observed_at,
                            reason.audit(
                                DelegationRunStatus::Reserving,
                                AdmissionClass::NormalRevision,
                                Some(req.parent_tool_use_id.clone()),
                                Some(child_connection_id.clone()),
                            ),
                        ),
                    )
                    .await;
            }
            return parent_end_setup_report(
                req.agent_type,
                reason,
                prebound_child.map(|(cid, _)| cid),
            );
        }
        // External cancel during spawn() sticky-marks inflight and deliberately
        // does not buffer the handle. Re-check here (before prompt) so sticky
        // cannot be lost when setup-to-running handoff later deregisters
        // inflight; fail closed with disconnect and no running success.
        if self
            .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
            .await
        {
            let _ = self.spawner.disconnect(&child_connection_id).await;
            if let (Some(runs), Some((child_id, _))) =
                (self.run_store.as_ref(), prebound_child.as_ref())
            {
                return self
                    .cancel_admitted_gen1_pre_spawn_external(
                        runs,
                        &call_id,
                        *child_id,
                        req.agent_type,
                        inflight_id,
                        "external cancel checkpoint after spawn before prompt",
                    )
                    .await;
            }
            if let Some(runs) = self.run_store.as_ref() {
                let _ = runs
                    .settle_terminal(
                        &call_id,
                        explicit_cancellation_terminal(
                            "canceled",
                            DelegationRunStatus::Reserving,
                            false,
                        ),
                    )
                    .await;
            }
            self.drop_inflight(inflight_id).await;
            return report_err(
                req.agent_type,
                DelegationError::Canceled {
                    reason: "canceled before prompt".into(),
                },
                prebound_child.map(|(cid, _)| cid),
            );
        }

        // --- Send linked prompt ------------------------------------------------
        // Now that the child connection and task id exist, fill the span's empty
        // fields so every subsequent log line in this delegation carries the
        // parent→child linkage (see the `delegation_task` span on this fn).
        tracing::Span::current().record("child_connection_id", child_connection_id.as_str());
        let link = DelegationLink {
            parent_conversation_id: req.parent_conversation_id,
            parent_tool_use_id: req.parent_tool_use_id.clone(),
            delegation_call_id: call_id.clone(),
        };

        // Reserve this delegation (both ids) BEFORE sending its first prompt.
        // `send_prompt_linked_for_delegation` persists the delegation link onto
        // the child row (arming the lifecycle resolver) AND dispatches the
        // prompt — after which a fast/empty turn's `TurnComplete` OR an
        // immediate child-connection failure can fire before we park the pending
        // entry below. The reservation lets those terminal events buffer their
        // outcome (see `PendingInner`) for the park to drain, rather than
        // no-oping and stranding `rx.await`. There is no `.await` between this
        // reservation and `send_prompt` (so nothing the child does can be
        // observed before the reservation is in place); it's cleared at park or
        // on the send-failure path. Reserving by `call_id` AND
        // `child_connection_id` lets each resolver gate on the id it holds —
        // `complete_call` the `call_id`, `cancel_by_child_connection` the
        // `child_connection_id`.
        // Reserve setup AND register coordination under the same lock before
        // the prompt-enqueue boundary so an immediate child MCP decision call
        // can resolve the parent edge without waiting for `running` insert.
        // Create the shared runtime projector with a provisional wall start;
        // rebase to the accepted durable timestamp after send succeeds.
        let provisional_started = Utc::now();
        let working_dir = PathBuf::from(req.working_dir.clone().unwrap_or_default());
        let runtime = Arc::new(LiveRuntimeState::new(provisional_started, working_dir));
        // Gen-1: generation is always 1. Continued runs (Task 6) pass the new
        // generation into the same registration path.
        let generation = 1i64;
        let run_registration = LiveRunRegistration {
            task_id: call_id.clone(),
            generation,
            child_connection_id: child_connection_id.clone(),
            // Child conversation may be prebound; otherwise filled after accept.
            child_conversation_id: prebound_child.map(|(cid, _)| cid).unwrap_or(0),
        };
        {
            let mut inner = self.pending.inner.lock().await;
            inner.reserve(&call_id, &child_connection_id);
            inner.register_live_run(run_registration.clone());
            inner.coordination_by_child.insert(
                child_connection_id.clone(),
                CoordinationIdentity {
                    task_id: call_id.clone(),
                    generation,
                    task_preview: task_preview.clone(),
                    child_connection_id: child_connection_id.clone(),
                    parent_connection_id: req.parent_connection_id.clone(),
                    parent_conversation_id: req.parent_conversation_id,
                    parent_tool_use_id: req.parent_tool_use_id.clone(),
                    runtime: runtime.clone(),
                    run_registration,
                    admission_buffer: Vec::new(),
                    admitted_running: false,
                    // Gen-1 setup still owns an inflight record; park does FWW.
                    settle_on_parent_end: false,
                    prompt_send_lease: false,
                    prompt_may_have_executed: false,
                    inflight_id: Some(inflight_id),
                },
            );
        }

        // Pre-send durable bind (invariant 9): no prompt may enqueue until the
        // reserving row owns this child_connection_id. Fail closed on conflict.
        if let Some(runs) = self.run_store.as_ref() {
            if let Err(e) = runs
                .bind_child_connection_while_reserving(&call_id, &child_connection_id)
                .await
            {
                tracing::error!(
                    task_id = %call_id,
                    child_connection_id = %child_connection_id,
                    error = %e,
                    "[delegation] gen-1 pre-send bind failed; no prompt enqueue"
                );
                runtime.terminal.store(true, Ordering::Release);
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.unreserve(&call_id, &child_connection_id);
                    inner.unregister_live_run(&child_connection_id);
                    inner.deregister_inflight(inflight_id);
                }
                let _ = self.spawner.disconnect(&child_connection_id).await;
                if matches!(e, TaskStoreError::BindOwnershipConflict(_)) {
                    // Challenger lost: never settle the owner's row. If the
                    // durable winner is already terminal, replay it (FTW);
                    // otherwise report challenger pre-admission spawn_failed.
                    if let Ok(Some(mut winner)) = runs.load_terminal_winner_report(&call_id).await {
                        winner.task_id = Some(call_id);
                        winner.agent_type = Some(req.agent_type);
                        if winner.child_conversation_id.is_none() {
                            winner.child_conversation_id = prebound_child.map(|(cid, _)| cid);
                        }
                        return winner;
                    }
                    return report_err(
                        req.agent_type,
                        store_err_to_delegation_error(e),
                        prebound_child.map(|(cid, _)| cid),
                    );
                }
                // Non-ownership bind failure: ownership-CAS settle only
                // (unbound/same-conn reserving in one txn). Replay terminal
                // Existing; never rewrite running/foreign winners.
                match runs
                    .settle_pre_admission_failure_if_owned(
                        &call_id,
                        &child_connection_id,
                        failed_terminal(
                            "spawn_failed",
                            DelegationRunStatus::Reserving,
                            false,
                            AcpTerminationSource::Admission,
                            AcpTerminationReason::AdmissionFailed,
                            AcpTerminationClassification::Unexpected,
                        ),
                    )
                    .await
                {
                    Ok(Some(Settlement::Existing(winner))) => {
                        let mut report = winner;
                        report.task_id = Some(call_id);
                        report.agent_type = Some(req.agent_type);
                        if report.child_conversation_id.is_none() {
                            report.child_conversation_id = prebound_child.map(|(cid, _)| cid);
                        }
                        return report;
                    }
                    Ok(Some(Settlement::Won(_))) | Ok(None) | Err(_) => {
                        return report_err(
                            req.agent_type,
                            store_err_to_delegation_error(e),
                            prebound_child.map(|(cid, _)| cid),
                        );
                    }
                }
            }
        }

        // Bind awaits can race parent/external cancel. Drain the external
        // pre-cancel buffer (may await), then apply **one** final pending-lock
        // fence for parent-end + sticky external cancel + prompt-send lease
        // before enqueue (no gap between parent and external checks).
        #[cfg(any(test, feature = "test-utils"))]
        {
            LiveRuntimeState::honor_gate(&self.gen1_post_bind_gate).await;
        }
        // Absorb companion pre-cancel into sticky inflight (outside the fence
        // lock). Parent-end is not observed here — only under the final fence.
        if let Some(handle) = req.external_handle.as_deref() {
            if self.take_pre_canceled_handle(handle).await {
                let mut inner = self.pending.inner.lock().await;
                inner.mark_inflight_external_canceled_by_id(inflight_id);
            }
        }
        // Test-only: hold after buffer drain and before the atomic fence so a
        // parent cancel can stamp the inter-check window deterministically.
        #[cfg(any(test, feature = "test-utils"))]
        {
            LiveRuntimeState::honor_gate(&self.gen1_pre_send_fence_gate).await;
        }
        enum PreSendCancel {
            Parent(ParentEndContext),
            External,
        }
        let pre_send_cancel = {
            let mut inner = self.pending.inner.lock().await;
            if let Some(end) = inner.inflight_parent_end(inflight_id) {
                Some(PreSendCancel::Parent(end.context))
            } else if inner.inflight_external_canceled(inflight_id) {
                Some(PreSendCancel::External)
            } else {
                // Claim send lease under the same lock as the cancel observe so
                // parent-end drain can see in-flight send ownership.
                let inflight_prompt_owner = if let Some(coord) =
                    inner.coordination_by_child.get_mut(&child_connection_id)
                {
                    coord.prompt_send_lease = true;
                    coord.prompt_may_have_executed = true;
                    coord.inflight_id
                } else {
                    None
                };
                if let Some(id) = inflight_prompt_owner {
                    inner.mark_inflight_prompt_may_have_executed(id);
                }
                None
            }
        };
        if let Some(cancel) = pre_send_cancel {
            runtime.terminal.store(true, Ordering::Release);
            {
                let mut inner = self.pending.inner.lock().await;
                inner.unreserve(&call_id, &child_connection_id);
                inner.unregister_live_run(&child_connection_id);
            }
            let _ = self.spawner.disconnect(&child_connection_id).await;
            match cancel {
                PreSendCancel::Parent(context) => {
                    if let (Some(runs), Some((child_id, _))) =
                        (self.run_store.as_ref(), prebound_child.as_ref())
                    {
                        return self
                            .cancel_admitted_gen1_pre_spawn(
                                runs,
                                &call_id,
                                *child_id,
                                context.clone(),
                                req.agent_type,
                                inflight_id,
                                "parent cancel at pre-send fence before prompt",
                            )
                            .await;
                    }
                    if let Some(runs) = self.run_store.as_ref() {
                        let _ = runs
                            .settle_terminal(
                                &call_id,
                                TerminalTaskWrite::canceled(
                                    context.durable_error_code(),
                                    context.termination.observed_at,
                                    context.audit(
                                        DelegationRunStatus::Reserving,
                                        AdmissionClass::NormalRevision,
                                        Some(req.parent_tool_use_id.clone()),
                                        Some(child_connection_id.clone()),
                                    ),
                                ),
                            )
                            .await;
                    }
                    self.drop_inflight(inflight_id).await;
                    return parent_end_setup_report(
                        req.agent_type,
                        &context,
                        prebound_child.map(|(cid, _)| cid),
                    );
                }
                PreSendCancel::External => {
                    if let (Some(runs), Some((child_id, _))) =
                        (self.run_store.as_ref(), prebound_child.as_ref())
                    {
                        return self
                            .cancel_admitted_gen1_pre_spawn_external(
                                runs,
                                &call_id,
                                *child_id,
                                req.agent_type,
                                inflight_id,
                                "external cancel at pre-send fence before prompt",
                            )
                            .await;
                    }
                    if let Some(runs) = self.run_store.as_ref() {
                        let _ = runs
                            .settle_terminal(
                                &call_id,
                                explicit_cancellation_terminal(
                                    "canceled",
                                    DelegationRunStatus::Reserving,
                                    false,
                                ),
                            )
                            .await;
                    }
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        req.agent_type,
                        DelegationError::Canceled {
                            reason: "canceled before prompt".into(),
                        },
                        prebound_child.map(|(cid, _)| cid),
                    );
                }
            }
        }

        let accepted = match self
            .spawner
            .send_prompt_linked_for_delegation(
                &child_connection_id,
                dispatch_prompt,
                link,
                prebound_child,
            )
            .await
        {
            Ok(accepted) => accepted,
            Err(e) => {
                // Prefer child id from the structured Send error; otherwise
                // decide row existence by the known task/delegation call id.
                // A durable row must settle failed/spawn_failed even when the
                // error's child id is None (connection-map loss after create).
                let (message, err_child_id) = match &e {
                    crate::acp::delegation::spawner::SpawnerError::Send {
                        message,
                        child_conversation_id,
                    } => (message.clone(), *child_conversation_id),
                    other => (other.to_string(), None),
                };
                let persisted_child = match self.task_store.load(&call_id).await {
                    Ok(Some(row)) => Some(row.child_conversation_id),
                    Ok(None) => None,
                    Err(store_err) => {
                        tracing::error!(
                            task_id = %call_id,
                            error = %store_err,
                            "[delegation] send failure: could not load row by call id"
                        );
                        None
                    }
                };
                let child_for_settle = err_child_id
                    .or(persisted_child)
                    .or(prebound_child.map(|(cid, _)| cid));
                if let Some(cid) = child_for_settle {
                    // Row-backed: clear reservation/inflight but keep the same
                    // runtime Arc for terminal flush; coordination is released
                    // inside settle_task after the winning CAS.
                    {
                        let mut inner = self.pending.inner.lock().await;
                        inner.unreserve(&call_id, &child_connection_id);
                        inner.deregister_inflight(inflight_id);
                    }
                    let terminal = failed_terminal(
                        "spawn_failed",
                        DelegationRunStatus::Reserving,
                        true,
                        AcpTerminationSource::Transport,
                        AcpTerminationReason::TransportDisconnected,
                        AcpTerminationClassification::Unexpected,
                    );
                    let ctx = SettleContext {
                        parent_connection_id: req.parent_connection_id.clone(),
                        parent_tool_use_id: req.parent_tool_use_id.clone(),
                        child_connection_id: child_connection_id.clone(),
                        child_conversation_id: cid,
                        agent_type: req.agent_type,
                        task_preview: task_preview.clone(),
                        duration_ms: 0,
                        cancel_turn: false,
                        disconnect_on_loss: true,
                        message: Some(message.clone()),
                        attention_resolution: AttentionResolutionCode::TaskTerminal,
                        runtime: Some(runtime),
                        card_summary: None,
                        completion_input: None,
                    };
                    let mut report = self.settle_task(&call_id, terminal, None, ctx).await;
                    if report.error_code.is_none() {
                        report.status = TaskStatus::Failed;
                        report.error_code = Some("spawn_failed".into());
                        report.message = Some(message);
                    }
                    report.task_id = Some(call_id);
                    report.child_conversation_id = Some(cid);
                    report.agent_type = Some(req.agent_type);
                    return report;
                }
                // No durable row — set terminal before removing coordination so
                // a scheduled coalesced worker stops without a missing-row write.
                runtime.terminal.store(true, Ordering::Release);
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.unreserve(&call_id, &child_connection_id);
                    inner.coordination_by_child.remove(&child_connection_id);
                    inner.deregister_inflight(inflight_id);
                }
                let _ = self.spawner.disconnect(&child_connection_id).await;
                return report_err(req.agent_type, DelegationError::SpawnFailed(message), None);
            }
        };
        let child_conversation_id = accepted.child_conversation_id;

        // Promote durable reserving → running only after prompt admit (Codex I3:
        // never return a running ack while the row remains reserving).
        // Task 4: typed promote outcomes + shared post-accept failure helper
        // (never collapse post-accept to spawn_failed).
        if let Some(runs) = self.run_store.as_ref() {
            let admission_class = runs
                .load_by_task_id(&call_id)
                .await
                .ok()
                .flatten()
                .map(|r| r.admission_class)
                .unwrap_or(AdmissionClass::NormalRevision);
            let generation = runs
                .load_by_task_id(&call_id)
                .await
                .ok()
                .flatten()
                .map(|r| r.generation)
                .unwrap_or(1);
            match runs
                .promote_running_detailed(
                    &call_id,
                    &child_connection_id,
                    accepted.prompt_accepted_at,
                )
                .await
            {
                Ok(outcome) => {
                    match self
                        .handle_post_accept_promote(
                            PostAcceptPromoteCtx {
                                task_id: call_id.clone(),
                                child_connection_id: child_connection_id.clone(),
                                child_conversation_id,
                                agent_type: req.agent_type,
                                parent_connection_id: req.parent_connection_id.clone(),
                                parent_tool_use_id: req.parent_tool_use_id.clone(),
                                continued_from_task_id: None,
                                generation,
                                admission_class,
                                inflight_id: Some(inflight_id),
                                runtime: Some(runtime.clone()),
                            },
                            outcome,
                        )
                        .await
                    {
                        PostAcceptPromoteResult::Proceed { already_running } => {
                            // Exactly-once accepted metric for this generation.
                            // - Promoted (including commit-ambiguity reread): count
                            //   if not yet emitted for this task_id
                            // - AlreadyRunning: only count if prior emission never
                            //   happened (dedupe set empty); otherwise skip
                            let _ = already_running;
                            self.metrics
                                .record_accepted_for_task(&call_id, req.agent_type);
                        }
                        PostAcceptPromoteResult::Failed(report) => return report,
                    }
                }
                Err(e) => {
                    // Defensive: promote_running_detailed is Ok-classified; if
                    // a store Err escapes, treat as permanent admission_failed.
                    tracing::error!(
                        task_id = %call_id,
                        error = %e,
                        "[delegation] gen-1 promote_running_detailed store error after accept"
                    );
                    match self
                        .handle_post_accept_promote(
                            PostAcceptPromoteCtx {
                                task_id: call_id.clone(),
                                child_connection_id: child_connection_id.clone(),
                                child_conversation_id,
                                agent_type: req.agent_type,
                                parent_connection_id: req.parent_connection_id.clone(),
                                parent_tool_use_id: req.parent_tool_use_id.clone(),
                                continued_from_task_id: None,
                                generation,
                                admission_class,
                                inflight_id: Some(inflight_id),
                                runtime: Some(runtime.clone()),
                            },
                            PromoteRunningOutcome {
                                kind: PromoteRunningKind::Permanent {
                                    message: e.to_string(),
                                },
                                meta: PromoteAttemptMeta::default(),
                            },
                        )
                        .await
                    {
                        PostAcceptPromoteResult::Proceed { .. } => {
                            self.metrics
                                .record_accepted_for_task(&call_id, req.agent_type);
                        }
                        PostAcceptPromoteResult::Failed(report) => return report,
                    }
                }
            }
        } else {
            // No RunStore: no durable promote boundary. Count once when the
            // running path is reached (legacy / unit-test brokers only).
            self.metrics
                .record_accepted_for_task(&call_id, req.agent_type);
        }

        // Rebase provisional wall start to the durable accepted timestamp
        // before any running meta / DelegationStarted publication.
        runtime
            .projector
            .lock()
            .await
            .rebase_started_at(accepted.prompt_accepted_at);

        // The child is now running. Stamp the start so terminal paths can
        // report a real `duration_ms`.
        let started_at = Instant::now();

        // --- Register pending, or resolve a terminal that beat us -------------
        // Under a single lock, decide this delegation's fate atomically against
        // everything a concurrent resolver may have recorded while we were
        // setting up:
        //   * a child terminal buffered against the reservation — a
        //     `TurnComplete` via `complete_call` (keyed by `call_id`) OR a child
        //     failure via `cancel_by_child_connection` (keyed by
        //     `child_connection_id`); either can race ahead of this park; or
        //   * a parent cancel that flagged this in-flight setup
        //     (`mark_inflight_canceled_for_parent`, which runs in the SAME lock
        //     acquisition that drains the parked `calls`).
        // Precedence: strict first-terminal-wins by arrival stamp. Both a child
        // terminal and a parent cancel carry the `seq` clock value they were
        // recorded at, so whichever landed FIRST wins — a child that completed
        // before the cancel keeps its result; a cancel that beat the completion
        // discards it (the parent had already abandoned the turn). Ties are
        // impossible: every event draws a distinct stamp under this one lock.
        // Sticky external MCP cancel (no stamp) is observed under the same lock
        // before `running` insert so handoff cannot drop the marker and still
        // return a running ack. Only when NOTHING beat us do we park for a
        // future resolver, deregistering the in-flight record adjacent to
        // `calls.insert` with no `.await` between — so a parent cancel
        // serialized AFTER us finds the entry in `calls` and drains it, while
        // one serialized BEFORE us is seen here via its stamp. When a
        // terminal/cancel DID beat us we deliberately DON'T park: resolving
        // inline (never leaving an entry for a second resolver to grab) rules
        // out a double-finalize.
        #[allow(clippy::large_enum_variant)] // Local race resolution keeps its terminal evidence by value.
        enum Disposition {
            ChildTerminal(ObservedTerminal),
            ParentEnded(ParentEndContext),
            /// Sticky external cancel observed under the park lock (setup-to-
            /// running handoff). Must not insert `running` or publish start.
            ExternalCanceled,
            Running,
        }
        // Near-zero elapsed for these setup-window races, but measured for
        // consistency with the normal terminal paths.
        let setup_duration_ms = started_at.elapsed().as_millis() as u64;
        let disposition = {
            let mut inner = self.pending.inner.lock().await;
            // First-terminal-wins among: early complete (call_id), early cancel
            // (child connection), and admission-window buffer (connection-scoped
            // TurnComplete / disconnect / error / cancel while reserving).
            let mut child_terminal: Option<(u64, ObservedTerminal)> = None;
            let mut consider = |stamp: u64, terminal: ObservedTerminal| match &child_terminal {
                Some((s, _)) if *s <= stamp => {}
                _ => child_terminal = Some((stamp, terminal)),
            };
            if let Some((stamp, terminal)) = inner.take_early_complete(&call_id) {
                consider(stamp, terminal);
            }
            if let Some((stamp, terminal)) = inner.take_early_cancel(&child_connection_id) {
                consider(
                    stamp,
                    terminal.with_child_identity(child_conversation_id, req.agent_type),
                );
            }
            if let Some((stamp, terminal)) =
                inner.take_first_admission_terminal(&child_connection_id)
            {
                consider(
                    stamp,
                    terminal.with_child_identity(child_conversation_id, req.agent_type),
                );
            }
            let parent_end = inner.inflight_parent_end(inflight_id);
            let external_canceled = inner.inflight_external_canceled(inflight_id);
            inner.unreserve(&call_id, &child_connection_id);
            // Terminal dispositions settle via the durable store AFTER this lock
            // is released (settle_task owns cache/meta/event/teardown). The
            // `Running` arm inserts the live task instead of parking a oneshot.
            match (child_terminal, parent_end) {
                // Both raced in the setup window: the earlier arrival stamp wins.
                (Some((child_stamp, outcome)), Some(end)) => {
                    inner.deregister_inflight(inflight_id);
                    if child_stamp < end.stamp {
                        Disposition::ChildTerminal(outcome)
                    } else {
                        Disposition::ParentEnded(end.context)
                    }
                }
                // Only a child terminal fired.
                (Some((_, outcome)), None) => {
                    inner.deregister_inflight(inflight_id);
                    Disposition::ChildTerminal(outcome)
                }
                // Only a parent end fired.
                (None, Some(end)) => {
                    inner.deregister_inflight(inflight_id);
                    Disposition::ParentEnded(end.context)
                }
                // Nothing beat us — mark admission, then re-drain any terminal
                // that landed in the admission buffer under this same lock
                // (first-terminal-wins after promote_running). Sticky external
                // cancel fails closed before `running` insert so handoff cannot
                // drop the marker. Only when empty do we park as running.
                (None, None) => {
                    // Sticky external cancel during send/promote: fail closed
                    // without advertising Running (marker would otherwise be
                    // discarded by deregister_inflight below).
                    if external_canceled {
                        inner.deregister_inflight(inflight_id);
                        Disposition::ExternalCanceled
                    } else {
                        // Mark admission complete: promote_running already succeeded
                        // above; drain any terminals buffered while reserving.
                        if let Some(coord) =
                            inner.coordination_by_child.get_mut(&child_connection_id)
                        {
                            coord.admitted_running = true;
                            coord.run_registration.child_conversation_id = child_conversation_id;
                            // Refresh conversation→connection index with real child id.
                            inner
                                .live_connection_by_conversation
                                .insert(child_conversation_id, child_connection_id.clone());
                            if let Some(reg) =
                                inner.live_runs_by_connection.get_mut(&child_connection_id)
                            {
                                reg.child_conversation_id = child_conversation_id;
                            }
                        }
                        // Post-promote drain: first buffered terminal settles instead
                        // of stranding the durable run as `running` forever.
                        if let Some((_stamp, terminal)) =
                            inner.take_first_admission_terminal(&child_connection_id)
                        {
                            inner.deregister_inflight(inflight_id);
                            Disposition::ChildTerminal(
                                terminal.with_child_identity(child_conversation_id, req.agent_type),
                            )
                        } else {
                            inner.running.insert(
                                call_id.clone(),
                                RunningTask {
                                    child_connection_id: child_connection_id.clone(),
                                    child_conversation_id,
                                    parent_connection_id: req.parent_connection_id.clone(),
                                    parent_tool_use_id: req.parent_tool_use_id.clone(),
                                    agent_type: req.agent_type,
                                    generation: 1,
                                    task_preview: task_preview.clone(),
                                    external_handle: req.external_handle.clone(),
                                    started_at,
                                    runtime: runtime.clone(),
                                },
                            );
                            inner.deregister_inflight(inflight_id);
                            Disposition::Running
                        }
                    }
                }
            }
        };
        // Accepted → running: soft supervisor should re-scan.
        if matches!(disposition, Disposition::Running) {
            self.notify_supervisor();
        }

        match disposition {
            // A child terminal beat registration — durable settle then return.
            Disposition::ChildTerminal(observed) => {
                let outcome = observed.outcome;
                let terminal = observed.terminal;
                let result_text = observed.result_text;
                let (extra_paths, workspace) = report_harvest_context_from_runtime(Some(&runtime));
                let (terminal, result_text, card_summary, completion_input) = self
                    .prepare_terminal_for_workflow(
                        &call_id,
                        terminal,
                        result_text,
                        &extra_paths,
                        workspace.as_deref(),
                    )
                    .await;
                let mut ctx = SettleContext {
                    parent_connection_id: req.parent_connection_id.clone(),
                    parent_tool_use_id: req.parent_tool_use_id.clone(),
                    child_connection_id: child_connection_id.clone(),
                    child_conversation_id,
                    agent_type: req.agent_type,
                    task_preview: task_preview.clone(),
                    duration_ms: setup_duration_ms,
                    cancel_turn: false,
                    disconnect_on_loss: true,
                    message: None,
                    attention_resolution: AttentionResolutionCode::TaskTerminal,
                    runtime: Some(runtime),
                    card_summary,
                    completion_input,
                };
                let (_, _, _, message) = terminal_fields(&outcome);
                ctx.message = message;
                return self.settle_task(&call_id, terminal, result_text, ctx).await;
            }
            // A parent end reached this delegation mid-setup — after the
            // prompt was sent, before we registered. Preserve the stable root
            // code (do not collapse via DelegationError::Canceled).
            Disposition::ParentEnded(parent_end) => {
                let terminal = TerminalTaskWrite::canceled(
                    parent_end.durable_error_code(),
                    parent_end.termination.observed_at,
                    parent_end.audit(
                        DelegationRunStatus::Running,
                        AdmissionClass::NormalRevision,
                        Some(req.parent_tool_use_id.clone()),
                        Some(child_connection_id.clone()),
                    ),
                );
                let ctx = SettleContext {
                    parent_connection_id: req.parent_connection_id.clone(),
                    parent_tool_use_id: req.parent_tool_use_id.clone(),
                    child_connection_id: child_connection_id.clone(),
                    child_conversation_id,
                    agent_type: req.agent_type,
                    task_preview: task_preview.clone(),
                    duration_ms: setup_duration_ms,
                    cancel_turn: true,
                    disconnect_on_loss: true,
                    message: Some(parent_end.reason.message().to_string()),
                    attention_resolution: parent_end.reason.attention_code(),
                    runtime: Some(runtime),
                    card_summary: None,
                    completion_input: None,
                };
                return self.settle_task(&call_id, terminal, None, ctx).await;
            }
            // Sticky external cancel observed under the park lock (e.g. during
            // send_prompt). Fail closed: cancel the accepted prompt, disconnect,
            // and never return a running acknowledgement.
            Disposition::ExternalCanceled => {
                let outcome = canceled_outcome(child_conversation_id, "canceled before await");
                let terminal =
                    explicit_cancellation_terminal("canceled", DelegationRunStatus::Running, true);
                let result_text = None;
                let mut ctx = SettleContext {
                    parent_connection_id: req.parent_connection_id.clone(),
                    parent_tool_use_id: req.parent_tool_use_id.clone(),
                    child_connection_id: child_connection_id.clone(),
                    child_conversation_id,
                    agent_type: req.agent_type,
                    task_preview: task_preview.clone(),
                    duration_ms: setup_duration_ms,
                    cancel_turn: true,
                    disconnect_on_loss: true,
                    message: None,
                    attention_resolution: AttentionResolutionCode::TaskTerminal,
                    runtime: Some(runtime),
                    card_summary: None,
                    completion_input: None,
                };
                let (_, _, _, message) = terminal_fields(&outcome);
                ctx.message = message;
                return self.settle_task(&call_id, terminal, result_text, ctx).await;
            }
            // Registered in `running` — publish start under the same
            // publication_lock / terminal protocol as terminal settlement, then
            // fall through to the second pre-cancel check and return the ack.
            Disposition::Running => {
                // Dual-lock protocol: hold publication_lock for running meta +
                // enriched DelegationStarted; if a child terminal already won
                // and set `terminal=true`, suppress start publication so it
                // cannot land after terminal state. Snapshot current runtime +
                // open attention under the lock so the start card closes both
                // pre-start races without leaking a provisional timestamp.
                let _publication = runtime.publication_lock.lock().await;
                LiveRuntimeState::honor_gate(&runtime.publication_gate).await;
                if !runtime.terminal.load(Ordering::Acquire) {
                    let runtime_stats = runtime.projector.lock().await.snapshot();
                    let attention_request = self
                        .latest_open_attention(req.parent_conversation_id, &call_id)
                        .await;
                    let started_at = runtime_stats.started_at;
                    self.write_meta_if_real(
                        &req.parent_connection_id,
                        &req.parent_tool_use_id,
                        build_delegation_meta(&DelegationMetaSnapshot {
                            status: "running".into(),
                            task_preview: Some(task_preview.clone()),
                            task_id: call_id.clone(),
                            child_connection_id: Some(child_connection_id.clone()),
                            child_conversation_id,
                            error_code: None,
                            text_preview: None,
                            started_at,
                            finished_at: None,
                            runtime_stats: Some(runtime_stats.clone()),
                            attention_request: attention_request.clone(),
                        }),
                    )
                    .await;
                    self.emit_started_if_real(
                        &req.parent_connection_id,
                        &req.parent_tool_use_id,
                        &child_connection_id,
                        child_conversation_id,
                        req.agent_type,
                        &task_preview,
                        &call_id,
                        started_at,
                        runtime_stats,
                        attention_request,
                    )
                    .await;
                    runtime.started_published.store(true, Ordering::Release);
                }
            }
        }

        // Second pre-cancel check: a `notifications/cancelled` may have landed
        // between the entry-side check and the `running` registration above. If
        // so, drain the task ourselves (so a racing `cancel_by_external_handle`
        // doesn't double-finalize), record the canceled result, and return a
        // canceled report instead of the Running ack.
        if let Some(handle) = req.external_handle.as_deref() {
            if self.take_pre_canceled_handle(handle).await {
                let removed = {
                    let mut inner = self.pending.inner.lock().await;
                    match inner.running.remove(&call_id) {
                        Some(task) => {
                            inner.settling.insert(call_id.clone(), task);
                            true
                        }
                        // Already mid-settle: do not start a second producer.
                        None => false,
                    }
                };
                if removed {
                    let duration_ms = started_at.elapsed().as_millis() as u64;
                    let outcome = canceled_outcome(child_conversation_id, "canceled before await");
                    let terminal = explicit_cancellation_terminal(
                        "canceled",
                        DelegationRunStatus::Running,
                        true,
                    );
                    let result_text = None;
                    let mut ctx = SettleContext {
                        parent_connection_id: req.parent_connection_id.clone(),
                        parent_tool_use_id: req.parent_tool_use_id.clone(),
                        child_connection_id: child_connection_id.clone(),
                        child_conversation_id,
                        agent_type: req.agent_type,
                        task_preview: task_preview.clone(),
                        duration_ms,
                        cancel_turn: true,
                        disconnect_on_loss: true,
                        message: None,
                        attention_resolution: AttentionResolutionCode::TaskTerminal,
                        runtime: Some(runtime),
                        card_summary: None,
                        completion_input: None,
                    };
                    let (_, _, _, message) = terminal_fields(&outcome);
                    ctx.message = message;
                    return self.settle_task(&call_id, terminal, result_text, ctx).await;
                }
            }
        }

        // Registered and running in the background — return the ack. The child
        // resolves later via the lifecycle → `complete_call` (or a cancel path).
        // Accepted metrics were emitted at the durable promote winner boundary
        // (above) so idempotent AlreadyRunning re-entry cannot double-count.
        let accepted = crate::acp::delegation::metrics::DelegationAuditRecord::task_transition(
            &req.parent_connection_id,
            Some(req.parent_conversation_id),
            req.agent_type,
            &call_id,
            Some(child_conversation_id),
            TaskStatus::Running,
            None,
            None,
            None,
        );
        accepted.emit_task_transition();
        decorate_admission_unknown_replacement_ack(
            running_ack(call_id, child_conversation_id, req.agent_type),
            req.replacement_reason.as_deref(),
        )
    }

    async fn prepare_terminal_for_workflow(
        &self,
        task_id: &str,
        terminal: TerminalTaskWrite,
        result_text: Option<String>,
        extra_report_paths: &[std::path::PathBuf],
        workspace_path: Option<&std::path::Path>,
    ) -> (
        TerminalTaskWrite,
        Option<String>,
        Option<CardSummary>,
        Option<TerminalCompletionInput>,
    ) {
        let Some(runs) = self.run_store.as_ref() else {
            let (terminal, result_text, card_summary) = prepare_terminal_with_card_summary(
                terminal,
                result_text,
                extra_report_paths,
                workspace_path,
            );
            return (terminal, result_text, card_summary, None);
        };
        let protocol = match self
            .terminal_completion_protocol_with_retry(runs, task_id)
            .await
        {
            Ok(protocol) => protocol,
            Err(error) => {
                if let Some(code) = error.workflow_admission_code() {
                    tracing::warn!(
                        task_id = %task_id,
                        error_code = %code,
                        error = %error,
                        "[delegation] completion protocol rejected terminal output"
                    );
                    return prepare_typed_terminal_failure(code, terminal.finished_at);
                }
                tracing::warn!(
                    task_id = %task_id,
                    error = %error,
                    "[delegation] completion protocol lookup unavailable after retries"
                );
                return prepare_typed_terminal_failure("persistence_error", terminal.finished_at);
            }
        };
        if protocol == TerminalCompletionProtocol::V2 {
            let reports = pre_read_completion_reports(
                result_text.as_deref().unwrap_or_default(),
                extra_report_paths,
                workspace_path,
            )
            .await;
            let (terminal, result_text, input) =
                prepare_terminal_for_v2(task_id, terminal, result_text, reports);
            (terminal, result_text, None, Some(input))
        } else {
            let (terminal, result_text, card_summary) = prepare_terminal_with_card_summary(
                terminal,
                result_text,
                extra_report_paths,
                workspace_path,
            );
            (terminal, result_text, card_summary, None)
        }
    }

    async fn terminal_completion_protocol_with_retry(
        &self,
        runs: &RunStore,
        task_id: &str,
    ) -> Result<TerminalCompletionProtocol, TaskStoreError> {
        let mut attempt = 0u32;
        loop {
            match runs.terminal_completion_protocol(task_id).await {
                Err(error)
                    if error.is_transient()
                        && attempt + 1 < self.persistence_retry.max_attempts =>
                {
                    let delay = self.persistence_retry.delay_for_attempt(attempt);
                    attempt += 1;
                    tokio::time::sleep(delay).await;
                }
                result => return result,
            }
        }
    }

    /// Durable terminal settlement — every terminal producer calls this before
    /// cache / notify / meta / event / teardown. Exactly one `running → terminal`
    /// store CAS wins; losers replay persisted truth and do not emit another
    /// terminal event. While CAS is in flight the task remains in `settling`
    /// (classified Running); after CAS/persistence fallback it moves atomically
    /// to `completed` and waiters are notified.
    async fn settle_task(
        &self,
        task_id: &str,
        terminal: TerminalTaskWrite,
        result_text: Option<String>,
        ctx: SettleContext,
    ) -> DelegationTaskReport {
        let mut ctx = ctx;
        // Capture finished_at before moving the write into settle_with_retry so
        // the terminal runtime snapshot uses the exact same timestamp.
        let finished_at = terminal.finished_at;
        let conversation_status = terminal.conversation_status.clone();
        let producer_phase = terminal.termination_evidence().map(|audit| {
            (
                audit.prior_status.clone(),
                audit.termination.prompt_may_have_executed,
            )
        });
        // Seal projector first so runtime stats writers no-op, then snapshot,
        // then settle with those stats. Do **not** set `runtime.terminal` yet —
        // mid-settle attention/reply races still need a nonterminal window
        // (see reply×settle publication tests). Post-terminal
        // `write_runtime_stats` remains a no-op for run-backed and legacy rows.
        let mut terminal = terminal;
        let final_runtime_stats = if let Some(runtime) = ctx.runtime.as_ref() {
            // Seal under the same projector lock as the final snapshot:
            // 1) an in-flight apply that already holds the lock finishes first
            //    and is included;
            // 2) after we release the lock, further applies no-op on seal even
            //    while `terminal` is still false (mid-settle attention window).
            let stats = {
                let mut projector = runtime.projector.lock().await;
                runtime.stats_sealed.store(true, Ordering::Release);
                projector.finish(finished_at);
                projector.snapshot()
            };
            terminal = terminal.with_runtime_stats(stats.clone());
            Some(stats)
        } else {
            None
        };
        let settlement = self
            .settle_with_retry(task_id, terminal, ctx.completion_input.clone())
            .await;
        match settlement {
            Ok((settlement, completion)) => {
                if completion.is_some() {
                    ctx.card_summary = None;
                }
                if let Some(completion) = completion.as_ref() {
                    for state in completion.final_metric_states.iter().copied() {
                        self.metrics.record_completion_final_state(state);
                    }
                    let projection =
                        crate::acp::delegation::workflow::project_terminal_completion(completion);
                    let metric_context = match self.run_store.as_ref() {
                        Some(runs) => runs
                            .terminal_completion_resolver_context(task_id)
                            .await
                            .ok()
                            .flatten(),
                        None => None,
                    };
                    let role = metric_context
                        .as_ref()
                        .map(|context| context.role)
                        .or_else(|| {
                            completion
                                .evidence
                                .as_ref()
                                .map(|evidence| evidence.binding.role)
                        });
                    if let Some(context) = metric_context.as_ref() {
                        if context.tool_intents.len() > 1 {
                            self.metrics
                                .record_completion_tool_supersession(context.role);
                        }
                    }
                    if let (Some(source), Some(role)) = (projection.card.source, role) {
                        self.metrics.record_completion_resolution(source, role);
                    } else if let (Some(runs), Some(context), Some(attention)) = (
                        self.run_store.as_ref(),
                        metric_context.as_ref(),
                        projection.card.attention.as_ref(),
                    ) {
                        if let Ok(Some(metric)) = runs
                            .terminal_completion_attention_metric(task_id, &attention.attention_id)
                            .await
                        {
                            match metric {
                                TerminalCompletionAttentionMetric::Decision(reason) => {
                                    self.metrics.record_completion_decision(reason);
                                    self.metrics.record_completion_decision_opened();
                                }
                                TerminalCompletionAttentionMetric::ArtifactFailure(reason) => {
                                    self.metrics.record_completion_artifact_failure(
                                        completion_metric_phase(&context.phase_id),
                                        reason,
                                    );
                                }
                            }
                        }
                    }
                }
                let won = settlement.won();
                let mut report = settlement.into_report();
                // Enrich with producer-local fields the store may not carry.
                report.agent_type = Some(ctx.agent_type);
                report.child_conversation_id = Some(ctx.child_conversation_id);
                report.duration_ms = Some(ctx.duration_ms);
                if report.status == TaskStatus::Completed {
                    if let Some(text) = result_text {
                        report.text = Some(cap_completed_text(&text));
                    }
                    // Live completion is not a cold-load "open child session" hint.
                    report.message = None;
                } else if let Some(msg) = ctx.message.clone() {
                    report.message = Some(msg);
                }
                let conversation_status = match report.status {
                    TaskStatus::Failed | TaskStatus::Canceled => ConversationStatus::Cancelled,
                    TaskStatus::Unknown | TaskStatus::Running | TaskStatus::Completed => {
                        conversation_status
                    }
                };
                // Attention closure + coordination release before completed
                // cache / Join notify / meta / event / disconnect. Attention
                // write errors are logged inside the helper and never undo the
                // winning task CAS.
                //
                // On win: set terminal=true then hold publication_lock for
                // attention → finalize runtime flush state → terminal meta →
                // event so a later runtime publisher cannot overwrite terminal
                // state. Durable final stats already landed in settle.
                if won {
                    if let Some(runtime) = ctx.runtime.as_ref() {
                        runtime.terminal.store(true, Ordering::Release);
                        let _publication = runtime.publication_lock.lock().await;
                        LiveRuntimeState::honor_gate(&runtime.publication_gate).await;
                        // Durable-only attention close under the same lock; no
                        // redundant clear event (terminal removes the card).
                        let _ = self
                            .close_task_attention(task_id, ctx.attention_resolution)
                            .await;
                        // Mark flush state; durable write already done in settle.
                        // Keep a no-op write attempt for mock/test observability
                        // of the terminal snapshot path without unfreezing runs.
                        let runtime_stats = self
                            .finalize_terminal_runtime_after_settle(
                                task_id,
                                runtime,
                                final_runtime_stats
                                    .clone()
                                    .unwrap_or_else(|| DelegationRuntimeStats::empty(finished_at)),
                            )
                            .await;
                        {
                            let mut inner = self.pending.inner.lock().await;
                            // Clear live registration + coordination so setup-
                            // window settles do not leave stale live_runs.
                            inner.unregister_live_run(&ctx.child_connection_id);
                        }
                        // Terminal meta + event while still holding publication_lock.
                        self.publish_terminal_meta_and_event(
                            task_id,
                            &report,
                            &ctx,
                            conversation_status,
                            runtime_stats,
                        )
                        .await;
                    } else {
                        let _ = self
                            .close_task_attention(task_id, ctx.attention_resolution)
                            .await;
                        {
                            let mut inner = self.pending.inner.lock().await;
                            inner.unregister_live_run(&ctx.child_connection_id);
                        }
                        let runtime_stats = DelegationRuntimeStats::empty(finished_at);
                        self.publish_terminal_meta_and_event(
                            task_id,
                            &report,
                            &ctx,
                            conversation_status,
                            runtime_stats,
                        )
                        .await;
                    }
                }
                // Atomic settling → completed (or first completed insert for
                // setup-window settles that never entered `running`).
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.settling.remove(task_id);
                    let outcome = report_to_outcome_for_meta(&report, &ctx);
                    inner.insert_completed(
                        task_id,
                        build_completed(
                            &ctx.parent_connection_id,
                            ctx.child_conversation_id,
                            ctx.agent_type,
                            ctx.duration_ms,
                            &outcome,
                        ),
                    );
                }
                self.result_notify.notify_waiters();
                // Terminal: drop observation cache entry and wake supervisor.
                self.clear_observation(task_id).await;
                self.notify_supervisor();
                if won {
                    // Reliability metrics: terminal only for the CAS winner.
                    self.metrics.record_terminal(
                        report.status,
                        std::time::Duration::from_millis(ctx.duration_ms),
                    );
                    let terminal_audit =
                        crate::acp::delegation::metrics::DelegationAuditRecord::task_transition(
                            &ctx.parent_connection_id,
                            None,
                            ctx.agent_type,
                            task_id,
                            Some(ctx.child_conversation_id),
                            report.status,
                            report.error_code.as_deref().and_then(
                                crate::acp::delegation::metrics::intern_terminal_error_code,
                            ),
                            Some(ctx.duration_ms),
                            Some(true),
                        );
                    terminal_audit.emit_task_transition();
                    if ctx.cancel_turn {
                        let _ = self.spawner.cancel(&ctx.child_connection_id).await;
                    }
                    let _ = self.spawner.disconnect(&ctx.child_connection_id).await;
                    self.task_store.remove_retry(task_id).await;
                } else if ctx.disconnect_on_loss {
                    // Best-effort: winner should already have torn down; disconnect
                    // is idempotent. No second ConversationStatusChanged /
                    // DelegationCompleted / terminal meta.
                    let _ = self.spawner.disconnect(&ctx.child_connection_id).await;
                }
                report
            }
            Err(err) => {
                // Exhausted / permanent: visible persistence_error, disconnect,
                // retain one deduplicated process-local retry record.
                tracing::error!(
                    task_id = %task_id,
                    error = %err,
                    "[delegation] terminal persist failed; publishing persistence_error"
                );
                // Same terminal flag + publication lock as the win path so a
                // later runtime publisher cannot race the in-memory failure.
                // Best-effort write of the final snapshot while the row may
                // still be running (settle did not land).
                if let Some(runtime) = ctx.runtime.as_ref() {
                    // Seal already set before the failed settle attempt; keep
                    // terminal=true so publishers treat the failure as closed.
                    runtime.stats_sealed.store(true, Ordering::Release);
                    runtime.terminal.store(true, Ordering::Release);
                    let _publication = runtime.publication_lock.lock().await;
                    LiveRuntimeState::honor_gate(&runtime.publication_gate).await;
                    let _ = self
                        .flush_terminal_runtime(task_id, runtime, finished_at)
                        .await;
                    {
                        let mut inner = self.pending.inner.lock().await;
                        inner.unregister_live_run(&ctx.child_connection_id);
                    }
                } else {
                    let mut inner = self.pending.inner.lock().await;
                    inner.unregister_live_run(&ctx.child_connection_id);
                }
                // Parent-facing message: stable phrase only (raw err in logs).
                let report = DelegationTaskReport {
                    task_id: Some(task_id.to_string()),
                    continued_from_task_id: None,
                    reused_session: None,
                    status: TaskStatus::Failed,
                    child_conversation_id: Some(ctx.child_conversation_id),
                    agent_type: Some(ctx.agent_type),
                    text: None,
                    error_code: Some("persistence_error".into()),
                    message: Some(bootstrap_refuse_message(
                        BootstrapRefuseKind::PersistenceError,
                    )),
                    duration_ms: Some(ctx.duration_ms),
                    observation: None,
                    last_agent_activity_at: None,
                    stalled_since: None,
                    recovery: None,
                };
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.settling.remove(task_id);
                    inner.insert_completed(
                        task_id,
                        CompletedTask {
                            parent_connection_id: ctx.parent_connection_id.clone(),
                            child_conversation_id: ctx.child_conversation_id,
                            agent_type: ctx.agent_type,
                            status: TaskStatus::Failed,
                            text: None,
                            error_code: Some("persistence_error".into()),
                            message: report.message.clone(),
                            duration_ms: ctx.duration_ms,
                        },
                    );
                }
                self.result_notify.notify_waiters();
                self.clear_observation(task_id).await;
                self.notify_supervisor();
                let _ = self.spawner.disconnect(&ctx.child_connection_id).await;
                // Preserve captured final stats for the eventual successful settle.
                // Failed/canceled producers always carry typed evidence. Reuse
                // their actual phase and sticky prompt fact; only successful
                // completion lacks termination evidence and therefore uses the
                // post-prompt running completion invariant.
                let (prior_status, prompt_may_have_executed) =
                    producer_phase.unwrap_or((DelegationRunStatus::Running, true));
                let mut retry_terminal = persistence_error_observation(
                    prior_status,
                    prompt_may_have_executed,
                    Utc::now(),
                    Some(ctx.child_conversation_id),
                )
                .terminal;
                if let Some(stats) = final_runtime_stats {
                    retry_terminal = retry_terminal.with_runtime_stats(stats);
                }
                let _ = self
                    .task_store
                    .put_retry(PendingTerminalRetry {
                        task_id: task_id.to_string(),
                        terminal: retry_terminal,
                        child_conversation_id: ctx.child_conversation_id,
                        frozen: false,
                    })
                    .await;
                // Single-flight worker ownership per task id (no re-emit).
                // Terminal metrics/audit deferred until durable CAS winner.
                self.spawn_persistence_retry_worker(
                    task_id.to_string(),
                    PersistenceRetryAccounting {
                        parent_connection_id: ctx.parent_connection_id.clone(),
                        agent_type: ctx.agent_type,
                        child_conversation_id: ctx.child_conversation_id,
                        // Defensible duration: producer wall time at first
                        // terminal attempt (saturating path in record_terminal).
                        duration_ms: ctx.duration_ms,
                    },
                )
                .await;
                report
            }
        }
    }

    /// Publish terminal conversation status, meta, and DelegationCompleted.
    /// Caller holds `runtime.publication_lock` when a runtime Arc is present.
    async fn publish_terminal_meta_and_event(
        &self,
        task_id: &str,
        report: &DelegationTaskReport,
        ctx: &SettleContext,
        conversation_status: ConversationStatus,
        runtime_stats: DelegationRuntimeStats,
    ) {
        self.emit_conversation_status_if_real(
            &ctx.parent_connection_id,
            ctx.child_conversation_id,
            conversation_status,
        )
        .await;
        let outcome_for_meta = report_to_outcome_for_meta(report, ctx);
        let finished_at = runtime_stats.finished_at;
        let started_at = runtime_stats.started_at;
        let snapshot = match &outcome_for_meta {
            DelegationOutcome::Ok(ok) => DelegationMetaSnapshot {
                status: "completed".into(),
                task_preview: Some(ctx.task_preview.clone()),
                task_id: task_id.to_string(),
                child_connection_id: Some(ctx.child_connection_id.clone()),
                child_conversation_id: ctx.child_conversation_id,
                error_code: None,
                text_preview: build_text_preview(&ok.text),
                started_at,
                finished_at,
                runtime_stats: Some(runtime_stats.clone()),
                attention_request: None,
            },
            DelegationOutcome::Err { code, .. } => DelegationMetaSnapshot {
                status: "failed".into(),
                task_preview: Some(ctx.task_preview.clone()),
                task_id: task_id.to_string(),
                child_connection_id: Some(ctx.child_connection_id.clone()),
                child_conversation_id: ctx.child_conversation_id,
                error_code: Some(code.clone()),
                text_preview: None,
                started_at,
                finished_at,
                runtime_stats: Some(runtime_stats.clone()),
                attention_request: None,
            },
        };
        self.write_meta_if_real(
            &ctx.parent_connection_id,
            &ctx.parent_tool_use_id,
            build_delegation_meta(&snapshot),
        )
        .await;
        self.emit_completed_if_real(
            &ctx.parent_connection_id,
            &ctx.parent_tool_use_id,
            &ctx.child_connection_id,
            ctx.child_conversation_id,
            ctx.agent_type,
            task_id,
            runtime_stats,
            outcome_to_summary(&outcome_for_meta, ctx.duration_ms),
            ctx.card_summary.clone(),
        )
        .await;
    }

    /// Project a structured child ToolCall / ToolCallUpdate into the live
    /// runtime stats for the coordinating task (if any).
    pub async fn project_child_tool_event(&self, child_connection_id: &str, event: &AcpEvent) {
        if !matches!(
            event,
            AcpEvent::ToolCall { .. } | AcpEvent::ToolCallUpdate { .. }
        ) {
            return;
        }
        let identity = {
            self.pending
                .inner
                .lock()
                .await
                .coordination_by_child
                .get(child_connection_id)
                .cloned()
        };
        let Some(identity) = identity else {
            return;
        };
        if identity.runtime.terminal.load(Ordering::Acquire)
            || identity.runtime.stats_sealed.load(Ordering::Acquire)
        {
            return;
        }
        // Capture the exact post-apply snapshot under the same projector lock
        // when apply=true — do not unlock/re-lock merely to snapshot.
        let event_snapshot = {
            let mut projector = identity.runtime.projector.lock().await;
            // Settle seals stats (and later sets terminal) before taking the
            // projector lock for the final snapshot. If this event got the lock
            // first, the settle snapshot includes it; if seal/terminal won first,
            // the event is ignored.
            if identity.runtime.terminal.load(Ordering::Acquire)
                || identity.runtime.stats_sealed.load(Ordering::Acquire)
            {
                return;
            }
            // Test gate: hold projector after the seal/terminal re-check so a
            // concurrent settle snapshot waits on this lock while the event still
            // owns the right to apply.
            LiveRuntimeState::honor_gate(&identity.runtime.projector_gate).await;
            // Seal is set under the projector lock during settle snapshot, so
            // while this event holds the lock settle cannot seal yet. Re-check
            // terminal only for any flag that may flip without the projector lock.
            if identity.runtime.terminal.load(Ordering::Acquire)
                || identity.runtime.stats_sealed.load(Ordering::Acquire)
            {
                return;
            }
            if projector.apply(event) {
                Some(projector.snapshot())
            } else {
                None
            }
        };
        let Some(stats) = event_snapshot else {
            return;
        };
        identity
            .runtime
            .dirty_version
            .fetch_add(1, Ordering::AcqRel);
        // Publish live replacement only after start and while non-terminal.
        // Do not wait 500 ms for SQLite — the coalesced worker owns persistence
        // and running-meta refresh from the exact written snapshot.
        {
            let _publication = identity.runtime.publication_lock.lock().await;
            LiveRuntimeState::honor_gate(&identity.runtime.publication_gate).await;
            if identity.runtime.started_published.load(Ordering::Acquire)
                && !identity.runtime.terminal.load(Ordering::Acquire)
            {
                self.emit_runtime_stats_changed_if_real(
                    &identity.parent_connection_id,
                    &identity.parent_tool_use_id,
                    &identity.task_id,
                    stats,
                )
                .await;
            }
        }
        self.schedule_runtime_flush(identity.task_id.clone(), identity.runtime);
    }

    fn record_runtime_projection_error(&self, kind: RuntimeProjectionErrorKind, task_id: &str) {
        tracing::error!(
            %task_id,
            kind = kind.as_str(),
            "[delegation] runtime projection failed"
        );
    }

    fn schedule_runtime_flush(&self, task_id: String, state: Arc<LiveRuntimeState>) {
        if state.coalesced_persistence_disabled.load(Ordering::Acquire) {
            return;
        }
        if state
            .flush_scheduled
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
        {
            return;
        }
        let broker = self.clone();
        tokio::spawn(async move {
            loop {
                tokio::time::sleep(RUNTIME_STATS_FLUSH_INTERVAL).await;
                let written_version;
                let write_ok;
                let written_stats;
                {
                    let _persist = state.persist_lock.lock().await;
                    // Sealed or terminal: stop coalesced running writes. Final
                    // stats are owned by settle (or the exhaustion flush path).
                    if state.terminal.load(Ordering::Acquire)
                        || state.stats_sealed.load(Ordering::Acquire)
                    {
                        state.flush_scheduled.store(false, Ordering::Release);
                        return;
                    }
                    written_version = state.dirty_version.load(Ordering::Acquire);
                    let stats = state.projector.lock().await.snapshot();
                    written_stats = stats.clone();
                    write_ok = match tokio::time::timeout(
                        RUNTIME_STATS_WRITE_TIMEOUT,
                        broker.task_store.write_runtime_stats(&task_id, &stats),
                    )
                    .await
                    {
                        Ok(Ok(())) => true,
                        Ok(Err(error)) => {
                            if !error.is_transient() {
                                state
                                    .coalesced_persistence_disabled
                                    .store(true, Ordering::Release);
                            }
                            broker.record_runtime_projection_error(
                                RuntimeProjectionErrorKind::Persistence,
                                &task_id,
                            );
                            false
                        }
                        Err(_error) => {
                            state
                                .coalesced_persistence_disabled
                                .store(true, Ordering::Release);
                            broker.record_runtime_projection_error(
                                RuntimeProjectionErrorKind::Persistence,
                                &task_id,
                            );
                            false
                        }
                    };
                    // Release persist_lock before publication_lock — never hold
                    // persist while waiting on publication.
                }
                if write_ok {
                    // Refresh running meta from the exact snapshot just written
                    // (not a newer projector view that has not hit SQLite).
                    let _publication = state.publication_lock.lock().await;
                    LiveRuntimeState::honor_gate(&state.publication_gate).await;
                    if state.started_published.load(Ordering::Acquire)
                        && !state.terminal.load(Ordering::Acquire)
                    {
                        let identity = {
                            let inner = broker.pending.inner.lock().await;
                            inner
                                .coordination_by_child
                                .values()
                                .find(|identity| identity.task_id == task_id)
                                .cloned()
                        };
                        if let Some(identity) = identity {
                            let attention = broker
                                .latest_open_attention(identity.parent_conversation_id, &task_id)
                                .await;
                            let child_conversation_id = {
                                let inner = broker.pending.inner.lock().await;
                                inner
                                    .running
                                    .get(&task_id)
                                    .map(|task| task.child_conversation_id)
                            };
                            if let Some(child_conversation_id) = child_conversation_id {
                                broker
                                    .write_meta_if_real(
                                        &identity.parent_connection_id,
                                        &identity.parent_tool_use_id,
                                        build_delegation_meta(&DelegationMetaSnapshot {
                                            status: "running".into(),
                                            task_preview: Some(identity.task_preview.clone()),
                                            task_id: task_id.clone(),
                                            child_connection_id: Some(
                                                identity.child_connection_id.clone(),
                                            ),
                                            child_conversation_id,
                                            error_code: None,
                                            text_preview: None,
                                            started_at: written_stats.started_at,
                                            finished_at: None,
                                            runtime_stats: Some(written_stats),
                                            attention_request: attention,
                                        }),
                                    )
                                    .await;
                            }
                        }
                    }
                }
                if state.coalesced_persistence_disabled.load(Ordering::Acquire) {
                    state.flush_scheduled.store(false, Ordering::Release);
                    return;
                }
                if state.dirty_version.load(Ordering::Acquire) != written_version {
                    continue;
                }
                state.flush_scheduled.store(false, Ordering::Release);
                if state.dirty_version.load(Ordering::Acquire) == written_version {
                    return;
                }
                if state
                    .flush_scheduled
                    .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
                    .is_err()
                {
                    return;
                }
            }
        });
    }

    /// Best-effort terminal runtime write used when settle itself failed (row
    /// may still be running) or for mock observability after a successful
    /// settle that already embedded the final snapshot.
    async fn flush_terminal_runtime(
        &self,
        task_id: &str,
        runtime: &Arc<LiveRuntimeState>,
        finished_at: DateTime<Utc>,
    ) -> DelegationRuntimeStats {
        let _persist = runtime.persist_lock.lock().await;
        debug_assert!(runtime.terminal.load(Ordering::Acquire));
        let stats = {
            let mut projector = runtime.projector.lock().await;
            projector.finish(finished_at);
            projector.snapshot()
        };
        runtime.dirty_version.fetch_add(1, Ordering::AcqRel);
        match tokio::time::timeout(
            RUNTIME_STATS_WRITE_TIMEOUT,
            self.task_store.write_runtime_stats(task_id, &stats),
        )
        .await
        {
            Ok(Ok(())) => {}
            Ok(Err(_error)) => self.record_runtime_projection_error(
                RuntimeProjectionErrorKind::TerminalPersistence,
                task_id,
            ),
            Err(_error) => self.record_runtime_projection_error(
                RuntimeProjectionErrorKind::TerminalPersistence,
                task_id,
            ),
        }
        runtime.flush_scheduled.store(false, Ordering::Release);
        stats
    }

    /// After a successful settle that already wrote `stats` in the settlement
    /// transaction: mark flush state and still attempt a write for mock/test
    /// observability. Run-backed stores freeze terminal rows (benign no-op);
    /// in-memory mocks may still accept a matching terminal snapshot.
    async fn finalize_terminal_runtime_after_settle(
        &self,
        task_id: &str,
        runtime: &Arc<LiveRuntimeState>,
        stats: DelegationRuntimeStats,
    ) -> DelegationRuntimeStats {
        let _persist = runtime.persist_lock.lock().await;
        debug_assert!(runtime.terminal.load(Ordering::Acquire));
        runtime.dirty_version.fetch_add(1, Ordering::AcqRel);
        match tokio::time::timeout(
            RUNTIME_STATS_WRITE_TIMEOUT,
            self.task_store.write_runtime_stats(task_id, &stats),
        )
        .await
        {
            Ok(Ok(())) => {}
            Ok(Err(_error)) => {
                // Durable path already committed in settle; post-terminal write
                // failures (including freeze no-ops that return Ok) are non-fatal.
                // Permanent errors from legacy stores are recorded only.
                self.record_runtime_projection_error(
                    RuntimeProjectionErrorKind::TerminalPersistence,
                    task_id,
                );
            }
            Err(_error) => self.record_runtime_projection_error(
                RuntimeProjectionErrorKind::TerminalPersistence,
                task_id,
            ),
        }
        runtime.flush_scheduled.store(false, Ordering::Release);
        stats
    }

    async fn settle_with_retry(
        &self,
        task_id: &str,
        terminal: TerminalTaskWrite,
        completion_input: Option<TerminalCompletionInput>,
    ) -> Result<
        (
            Settlement,
            Option<crate::acp::delegation::workflow::TerminalCompletionResult>,
        ),
        crate::acp::delegation::store::TaskStoreError,
    > {
        if let Some(input) = completion_input.as_ref() {
            self.pending_terminal_completion
                .lock()
                .await
                .insert(task_id.to_string(), input.clone());
        }
        let mut attempt = 0u32;
        loop {
            match self
                .settle_once(task_id, terminal.clone(), completion_input.clone())
                .await
            {
                Ok(result) => {
                    self.pending_terminal_completion
                        .lock()
                        .await
                        .remove(task_id);
                    return Ok(result);
                }
                Err(e) if e.is_transient() && attempt + 1 < self.persistence_retry.max_attempts => {
                    let delay = self.persistence_retry.delay_for_attempt(attempt);
                    attempt += 1;
                    tokio::time::sleep(delay).await;
                }
                Err(e) => return Err(e),
            }
        }
    }

    async fn settle_once(
        &self,
        task_id: &str,
        terminal: TerminalTaskWrite,
        completion_input: Option<TerminalCompletionInput>,
    ) -> Result<
        (
            Settlement,
            Option<crate::acp::delegation::workflow::TerminalCompletionResult>,
        ),
        crate::acp::delegation::store::TaskStoreError,
    > {
        if let (Some(runs), Some(input)) = (self.run_store.as_ref(), completion_input) {
            return runs
                .settle_terminal_with_completion(task_id, terminal, Some(input))
                .await;
        }
        self.task_store
            .settle(task_id, terminal)
            .await
            .map(|settlement| (settlement, None))
    }

    /// Spawn at most one process-local persistence retry worker per task id.
    /// Concurrent exhaustion for the same id is single-flight: only the first
    /// ownership grant starts a worker. Payload-driven: persists the original
    /// `PendingTerminalRetry.terminal` (not a hardcoded rewrite). On `Won` /
    /// `Existing`, calls [`Self::finalize_durable_settlement`] as the single
    /// metric/audit + park cleanup site (`Existing` does not count). Permanent
    /// store failure freezes the retry and upgrades park to sanitized
    /// `persistence_error` without spinning.
    ///
    /// Frozen records refuse inflight ownership and never enter the settle loop.
    async fn spawn_persistence_retry_worker(
        &self,
        task_id: String,
        obs: PersistenceRetryAccounting,
    ) {
        // Refuse before inflight insert when the tombstone is already frozen.
        if self
            .task_store
            .get_retry(&task_id)
            .await
            .map(|r| r.frozen)
            .unwrap_or(false)
        {
            return;
        }
        {
            let mut inflight = self
                .persistence_retry_inflight
                .lock()
                .unwrap_or_else(|e| e.into_inner());
            if !inflight.insert(task_id.clone()) {
                return;
            }
        }
        #[cfg(any(test, feature = "test-utils"))]
        {
            self.persistence_worker_spawn_count
                .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        }
        let store = self.task_store.clone();
        let broker = self.clone();
        let inflight = self.persistence_retry_inflight.clone();
        let interval = self.persistence_retry_worker_interval;
        tokio::spawn(async move {
            let clear_ownership = |task_id: &str| {
                let mut set = inflight.lock().unwrap_or_else(|e| e.into_inner());
                set.remove(task_id);
            };
            loop {
                if !store.has_retry_record(&task_id).await {
                    clear_ownership(&task_id);
                    break;
                }
                tokio::time::sleep(interval).await;
                // Use the captured retry payload (including final runtime stats).
                let Some(retry) = store.get_retry(&task_id).await else {
                    clear_ownership(&task_id);
                    break;
                };
                // Frozen permanent-failure tombstone: do not settle or spin.
                if retry.frozen {
                    clear_ownership(&task_id);
                    break;
                }
                // Payload-driven (§3.5): copy status/code before moving into
                // settle, then align any Won report to those copies so metrics/
                // audit/overlay never follow a store rewrite (e.g. synthetic
                // persistence_error). Existing keeps the durable winner as-is.
                let payload_status = retry.terminal.status;
                let payload_error_code = retry.terminal.error_code.clone();
                let terminal = retry.terminal;
                let completion_input = broker
                    .pending_terminal_completion
                    .lock()
                    .await
                    .get(&task_id)
                    .cloned();
                match broker
                    .settle_once(&task_id, terminal, completion_input)
                    .await
                {
                    Ok((settlement, _completion)) => {
                        broker
                            .pending_terminal_completion
                            .lock()
                            .await
                            .remove(&task_id);
                        let settlement = align_won_settlement_to_payload(
                            settlement,
                            payload_status,
                            payload_error_code,
                            &task_id,
                        );
                        let record_won = settlement.won();
                        broker
                            .finalize_durable_settlement(
                                &task_id,
                                settlement,
                                Some(&obs),
                                record_won,
                            )
                            .await;
                        clear_ownership(&task_id);
                        break;
                    }
                    Err(e) if e.is_transient() => continue,
                    Err(err) => {
                        broker
                            .pending_terminal_completion
                            .lock()
                            .await
                            .remove(&task_id);
                        tracing::error!(
                            task_id = %task_id,
                            error = %err,
                            "[delegation] persistence retry worker: permanent store failure"
                        );
                        let _ = broker
                            .finalize_permanent_persistence_failure(&task_id, Some(&obs), true)
                            .await;
                        clear_ownership(&task_id);
                        break;
                    }
                }
            }
        });
    }

    /// Resolve the active run task id for a child connection incarnation.
    ///
    /// Lifecycle must settle by this task id, never by conversation root
    /// `delegation_call_id` (continued runs share the root call id).
    pub async fn resolve_task_id_for_connection(
        &self,
        child_connection_id: &str,
    ) -> Option<String> {
        let inner = self.pending.inner.lock().await;
        inner
            .live_run_for_connection(child_connection_id)
            .map(|r| r.task_id.clone())
            .or_else(|| {
                // Fall back to a running task keyed by this connection.
                inner
                    .running
                    .iter()
                    .find(|(_, t)| t.child_connection_id == child_connection_id)
                    .map(|(id, _)| id.clone())
            })
    }

    /// Cold terminal resolution: non-terminal run whose persisted
    /// `child_connection_id` matches. Never uses conversation root call id.
    pub async fn cold_resolve_task_id_for_connection(
        &self,
        child_connection_id: &str,
    ) -> Option<String> {
        let runs = self.run_store.as_ref()?;
        match runs
            .load_non_terminal_by_child_connection(child_connection_id)
            .await
        {
            Ok(Some(run)) => {
                match cold_resolve_allows(
                    &run.task_id,
                    run.child_connection_id.as_deref(),
                    matches!(
                        run.run_status,
                        crate::db::entities::delegation_task_run::DelegationRunStatus::Reserving
                            | crate::db::entities::delegation_task_run::DelegationRunStatus::Running
                    ),
                    child_connection_id,
                ) {
                    SettlementFenceDecision::Allow => Some(run.task_id),
                    _ => None,
                }
            }
            _ => None,
        }
    }

    /// Pre-bootstrap run-identity handoff: mint (or accept) a child connection
    /// incarnation id, register it against the reserving run, and durable-bind
    /// `child_connection_id` on the reserving row for cold resolve.
    ///
    /// **Must** run before session resume/load / prompt enqueue so a
    /// `ResumeExistingOnly` identity refuse can settle via
    /// [`Self::settle_bootstrap_unresumable`] (manager returns the connection
    /// id only after bootstrap readiness — too late for refuse settlement).
    ///
    /// Bind failure is fail-closed: live registration / reservation are
    /// unwound, the unused connection is disconnected, and
    /// [`AdmissionFenceReject::BindFailed`] is returned (no prompt enqueue).
    pub async fn begin_run_admission(
        &self,
        handoff: AdmissionHandoff,
    ) -> Result<LiveRunRegistration, AdmissionFenceReject> {
        self.begin_run_admission_transfer(handoff, None).await
    }

    /// Like [`Self::begin_run_admission`], but atomically transfers a continue
    /// setup inflight fence into the handoff under one `pending.inner` lock:
    /// observe parent-end / external cancel on `transfer_inflight_id` (if any)
    /// → register setups/live/coordination → drop inflight. No gap where cancel
    /// can stamp then have that stamp discarded before handoff registration.
    ///
    /// After registration, durable-binds `child_connection_id` fail-closed
    /// (same contract as gen-1 pre-send bind).
    async fn begin_run_admission_transfer(
        &self,
        handoff: AdmissionHandoff,
        transfer_inflight_id: Option<u64>,
    ) -> Result<LiveRunRegistration, AdmissionFenceReject> {
        let child_connection_id = handoff
            .child_connection_id
            .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());
        let registration = LiveRunRegistration {
            task_id: handoff.task_id.clone(),
            generation: handoff.generation,
            child_connection_id: child_connection_id.clone(),
            child_conversation_id: handoff.child_conversation_id,
        };
        let provisional_started = Utc::now();
        let runtime = Arc::new(LiveRuntimeState::new(provisional_started, PathBuf::new()));
        {
            let mut inner = self.pending.inner.lock().await;
            if let Some(inflight_id) = transfer_inflight_id {
                if let Some(end) = inner.inflight_parent_end(inflight_id) {
                    inner.deregister_inflight(inflight_id);
                    return Err(AdmissionFenceReject::ParentEnd(end.context));
                }
                if inner.inflight_external_canceled(inflight_id) {
                    inner.deregister_inflight(inflight_id);
                    return Err(AdmissionFenceReject::ExternalCanceled);
                }
            }
            inner.reserve(&handoff.task_id, &child_connection_id);
            inner.register_live_run(registration.clone());
            inner.coordination_by_child.insert(
                child_connection_id.clone(),
                CoordinationIdentity {
                    task_id: handoff.task_id.clone(),
                    generation: handoff.generation,
                    task_preview: handoff.task_preview.clone(),
                    child_connection_id: child_connection_id.clone(),
                    parent_connection_id: handoff.parent_connection_id.clone(),
                    parent_conversation_id: handoff.parent_conversation_id,
                    parent_tool_use_id: handoff.parent_tool_use_id.clone(),
                    runtime,
                    run_registration: registration.clone(),
                    admission_buffer: Vec::new(),
                    admitted_running: false,
                    // No inflight park after transfer: parent cancel must
                    // durable-settle the handoff directly.
                    settle_on_parent_end: true,
                    prompt_send_lease: false,
                    prompt_may_have_executed: false,
                    inflight_id: None,
                },
            );
            if let Some(inflight_id) = transfer_inflight_id {
                // Re-check cancel under the same lock before dropping the fence.
                // Parent-end after the initial check but before handoff insert is
                // already covered by mark_inflight during drain; external cancel
                // sticky-mark is checked here so we never publish a handoff for a
                // canceled setup.
                if let Some(end) = inner.inflight_parent_end(inflight_id) {
                    inner.unreserve(&handoff.task_id, &child_connection_id);
                    inner.unregister_live_run(&child_connection_id);
                    inner.deregister_inflight(inflight_id);
                    return Err(AdmissionFenceReject::ParentEnd(end.context));
                }
                if inner.inflight_external_canceled(inflight_id) {
                    inner.unreserve(&handoff.task_id, &child_connection_id);
                    inner.unregister_live_run(&child_connection_id);
                    inner.deregister_inflight(inflight_id);
                    return Err(AdmissionFenceReject::ExternalCanceled);
                }
                // Drop only after handoff is parent-visible — no fence gap.
                inner.deregister_inflight(inflight_id);
            }
        }
        if let Some(runs) = self.run_store.as_ref() {
            if let Err(e) = runs
                .bind_child_connection_while_reserving(&handoff.task_id, &child_connection_id)
                .await
            {
                tracing::error!(
                    task_id = %handoff.task_id,
                    child_connection_id = %child_connection_id,
                    error = %e,
                    "[delegation] begin_run_admission: bind child_connection_id failed; \
                     unwinding live registration (fail-closed, no prompt)"
                );
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.unreserve(&handoff.task_id, &child_connection_id);
                    inner.unregister_live_run(&child_connection_id);
                }
                // Disconnect unused incarnation (idempotent if never opened).
                let _ = self.spawner.disconnect(&child_connection_id).await;
                return Err(admission_bind_reject(e, &child_connection_id));
            }
        }
        tracing::info!(
            task_id = %handoff.task_id,
            generation = handoff.generation,
            child_connection_id = %child_connection_id,
            "[delegation] begin_run_admission: registered pre-bootstrap incarnation"
        );
        Ok(registration)
    }

    /// Async entry for `continue_delegation`. Mints a new run, resumes the
    /// existing child session with `ResumeExistingOnly`, and returns a running
    /// ack (or a typed error report).
    pub async fn continue_delegation(
        &self,
        mut req: crate::acp::delegation::types::ContinueDelegationRequest,
    ) -> DelegationTaskReport {
        use crate::acp::delegation::capability::gate_continue_session_reuse;
        use crate::acp::delegation::capability::ContinueCapabilityDecision;
        use crate::acp::delegation::run_store::{
            derive_task_preview, request_fingerprint, ContinueAdmitOutcome, ContinueRunAdmission,
        };
        use crate::acp::delegation::types::CONTINUE_DELEGATION_TOOL;
        use crate::db::entities::conversation;
        use sea_orm::EntityTrait;

        // Whitespace-only host tool ids are treated as absent; preserve every
        // nonblank opaque id exactly (see start_delegation).
        if req.parent_tool_use_id.trim().is_empty() {
            req.parent_tool_use_id.clear();
        }
        // Match gen-1's whole-setup parent-end fence: from the first await of
        // a valid continuation through the durable reservation, parent end
        // must have a per-admission record to mark. Register BEFORE the
        // correlation poll so cancel during exact claim is observed. Every
        // early return below drops it; successful reservation hands off to
        // live coordination.
        let inflight_id = self
            .pending
            .inner
            .lock()
            .await
            .register_inflight(&req.parent_connection_id, req.external_handle.clone());
        // Entry-side pre-cancel (gen-1 parity): a notifications/cancelled that
        // raced ahead of tools/call must not spawn or resume.
        if let Some(handle) = req.external_handle.as_deref() {
            if self.take_pre_canceled_handle(handle).await {
                self.drop_inflight(inflight_id).await;
                // Unique-only drain: never first-match under an ambiguous key.
                if req.parent_tool_use_id.is_empty() {
                    let corr = req.correlation_id.as_deref().unwrap_or("");
                    if validate_correlation_id(corr).is_ok() {
                        let key = DelegationMatchKey::Continue {
                            correlation_id: corr.to_string(),
                            target_task_id: req.target_task_id.clone(),
                            task: req.task.clone(),
                        };
                        let _ = self
                            .take_unique_matching_tool_call(&req.parent_connection_id, &key)
                            .await;
                    }
                } else {
                    self.consume_explicit_tool_call(
                        &req.parent_connection_id,
                        &req.parent_tool_use_id,
                    )
                    .await;
                }
                return report_err(
                    AgentType::ClaudeCode,
                    DelegationError::Canceled {
                        reason: "canceled before spawn".into(),
                    },
                    None,
                );
            }
        }
        // MCP clients often omit `_meta.tool_use_id`. Correlate by typed exact
        // Continue key (wait-out-budget) — never FIFO and never mint a synthetic
        // parent id. Explicit host id remains authoritative and does not require
        // `correlation_id`.
        if req.parent_tool_use_id.is_empty() {
            let corr = req.correlation_id.as_deref().unwrap_or("");
            if validate_correlation_id(corr).is_err() {
                self.drop_inflight(inflight_id).await;
                return report_err(
                    AgentType::ClaudeCode,
                    DelegationError::CorrelationMissing(correlation_error_message(
                        CorrelationFailureKind::Missing,
                        CorrelationEntryPoint::ContinueDelegation,
                    )),
                    None,
                );
            }
            let match_key = DelegationMatchKey::Continue {
                correlation_id: corr.to_string(),
                target_task_id: req.target_task_id.clone(),
                task: req.task.clone(),
            };
            let claim = self
                .resolve_exact_claim(
                    &req.parent_connection_id,
                    &match_key,
                    Some(inflight_id),
                    req.external_handle.as_deref(),
                )
                .await;
            match claim {
                ExactClaimResult::Matched(id) => {
                    req.parent_tool_use_id = id;
                }
                ExactClaimResult::Cancelled => {
                    // Preserve stable parent-end codes when inflight was marked;
                    // external-handle cancel falls through to generic canceled.
                    if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
                        return parent_end_setup_report(AgentType::ClaudeCode, reason, None);
                    }
                    self.drop_inflight(inflight_id).await;
                    // Unique-only drain: never first-match under an ambiguous key.
                    let _ = self
                        .take_unique_matching_tool_call(&req.parent_connection_id, &match_key)
                        .await;
                    return report_err(
                        AgentType::ClaudeCode,
                        DelegationError::Canceled {
                            reason: "canceled during parent-tool correlation".into(),
                        },
                        None,
                    );
                }
                ExactClaimResult::Ambiguous => {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        AgentType::ClaudeCode,
                        DelegationError::CorrelationAmbiguous(correlation_error_message(
                            CorrelationFailureKind::Ambiguous,
                            CorrelationEntryPoint::ContinueDelegation,
                        )),
                        None,
                    );
                }
                ExactClaimResult::Conflict => {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        AgentType::ClaudeCode,
                        DelegationError::CorrelationConflict(correlation_error_message(
                            CorrelationFailureKind::Conflict,
                            CorrelationEntryPoint::ContinueDelegation,
                        )),
                        None,
                    );
                }
                ExactClaimResult::Missing => {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        AgentType::ClaudeCode,
                        DelegationError::CorrelationTimeout(correlation_error_message(
                            CorrelationFailureKind::Timeout,
                            CorrelationEntryPoint::ContinueDelegation,
                        )),
                        None,
                    );
                }
            }
        } else {
            // Explicit `_meta.tool_use_id`: consume matching pending entry so it
            // cannot be mis-claimed later. Does not require correlation_id.
            self.consume_explicit_tool_call(&req.parent_connection_id, &req.parent_tool_use_id)
                .await;
        }
        // Claim-to-resume transition: parent end or external cancel may have
        // won during exact claim — bail before ownership / durable reserve.
        if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
            return parent_end_setup_report(AgentType::ClaudeCode, reason, None);
        }
        if self
            .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
            .await
        {
            self.drop_inflight(inflight_id).await;
            return report_err(
                AgentType::ClaudeCode,
                DelegationError::Canceled {
                    reason: "canceled before spawn".into(),
                },
                None,
            );
        }

        let Some(runs) = self.run_store.as_ref() else {
            self.drop_inflight(inflight_id).await;
            return report_err(
                AgentType::ClaudeCode,
                DelegationError::SpawnFailed("run store unavailable".into()),
                None,
            );
        };

        if let Err(error) = require_writable_conversation_workflow(
            &runs.db().conn,
            req.parent_conversation_id,
        )
        .await
        {
            self.drop_inflight(inflight_id).await;
            return report_err(
                AgentType::ClaudeCode,
                workflow_store_error_to_delegation_error(error),
                None,
            );
        }

        // Load target for ownership / route material only (not_found on miss).
        let target = match runs.load_by_task_id(&req.target_task_id).await {
            Ok(Some(t)) if t.parent_conversation_id == req.parent_conversation_id => t,
            Ok(Some(_)) | Ok(None) => {
                self.drop_inflight(inflight_id).await;
                return report_err(
                    AgentType::ClaudeCode,
                    DelegationError::NotFound(req.target_task_id.clone()),
                    None,
                );
            }
            Err(e) => {
                self.drop_inflight(inflight_id).await;
                return report_err(
                    AgentType::ClaudeCode,
                    store_err_to_delegation_error(e),
                    None,
                );
            }
        };

        if is_completion_format_repair_prompt(&req.task) {
            match runs.terminal_completion_protocol(&target.task_id).await {
                Ok(TerminalCompletionProtocol::V2) => {
                    let mode =
                        crate::db::entities::delegation_workflow::CompletionProtocolMode::V2Enforce;
                    self.metrics.record_card_reemit_prompt(mode);
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        target.agent_type,
                        DelegationError::WorkflowAdmission {
                            code: "completion_card_reemit_forbidden".into(),
                            message: "protocol v2 completion is platform-generated".into(),
                        },
                        None,
                    );
                }
                Ok(TerminalCompletionProtocol::Standalone) => {}
                Err(error) => {
                    self.drop_inflight(inflight_id).await;
                    return report_err(
                        target.agent_type,
                        store_err_to_delegation_error(error),
                        None,
                    );
                }
            }
        }

        let route_fp = target.route_fingerprint.clone().unwrap_or_default();
        let request_fp = request_fingerprint(
            CONTINUE_DELEGATION_TOOL,
            &req.task,
            req.work_unit_key
                .as_deref()
                .or(target.work_unit_key.as_deref()),
            None,
            None,
            Some(&req.target_task_id),
            &route_fp,
        );

        // Exact parent-tool replays are resolved before capability or
        // lifecycle gates. Matching fingerprint is idempotent; terminal rows
        // project durable status (never a false running reuse ack).
        match runs
            .load_by_parent_tool_use(req.parent_conversation_id, &req.parent_tool_use_id)
            .await
        {
            Ok(Some(existing)) => {
                self.drop_inflight(inflight_id).await;
                if existing.request_fingerprint.as_deref() == Some(request_fp.as_str()) {
                    return self
                        .continue_idempotent_with_terminal_intent(&existing, req.target_task_id)
                        .await;
                }
                return report_err(
                    target.agent_type,
                    DelegationError::DuplicateParentTool(req.parent_tool_use_id.clone()),
                    Some(target.child_conversation_id),
                );
            }
            Ok(None) => {}
            Err(e) => {
                self.drop_inflight(inflight_id).await;
                return report_err(
                    target.agent_type,
                    store_err_to_delegation_error(e),
                    Some(target.child_conversation_id),
                );
            }
        }

        // Capability after ownership resolved (before busy/stale/not_continuable).
        match gate_continue_session_reuse(target.agent_type) {
            ContinueCapabilityDecision::Allowed => {}
            ContinueCapabilityDecision::NotSupported => {
                self.drop_inflight(inflight_id).await;
                return report_err(target.agent_type, DelegationError::NotSupported, None);
            }
        }

        // work_unit_key mismatch is evaluated inside admit_continue_reserving
        // after busy/stale so it cannot preempt those codes.

        let new_task_id = uuid::Uuid::new_v4().to_string();
        let admission = ContinueRunAdmission {
            task_id: new_task_id.clone(),
            parent_conversation_id: req.parent_conversation_id,
            parent_tool_use_id: req.parent_tool_use_id.clone(),
            target_task_id: req.target_task_id.clone(),
            task_preview: derive_task_preview(&req.task),
            request_fingerprint: request_fp,
            work_unit_key: req.work_unit_key.clone(),
        };

        // Record durable ownership under the same lock as the already-registered
        // admission fence, so parent end observes either the fence or the
        // later durable row throughout note → reserve → handoff.
        {
            let mut inner = self.pending.inner.lock().await;
            inner.note_parent_conversation(&req.parent_connection_id, req.parent_conversation_id);
        }

        // Test-only hold: parent end after note but before reserve must mark
        // the in-flight admission, so no later reserve can escape it.
        #[cfg(any(test, feature = "test-utils"))]
        {
            LiveRuntimeState::honor_gate(&self.continue_post_note_gate).await;
        }

        if let Some(reason) = self.take_inflight_cancel(inflight_id).await {
            return parent_end_setup_report(
                target.agent_type,
                reason,
                Some(target.child_conversation_id),
            );
        }
        // External cancel immediately before durable continue admission.
        if self
            .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
            .await
        {
            self.drop_inflight(inflight_id).await;
            return report_err(
                target.agent_type,
                DelegationError::Canceled {
                    reason: "canceled before spawn".into(),
                },
                Some(target.child_conversation_id),
            );
        }

        let authorization = RecoveryAdmissionAuthorization {
            authorization_id: req.recovery_authorization_id.clone(),
            correlation_id: req
                .correlation_id
                .clone()
                .or_else(|| {
                    (!req.parent_tool_use_id.is_empty()).then(|| req.parent_tool_use_id.clone())
                })
                .unwrap_or_else(|| new_task_id.clone()),
        };
        let admitted = match runs
            .admit_continue_reserving_authorized(admission, authorization)
            .await
        {
            Ok(ContinueAdmitOutcome::AuthorizedCreated {
                run,
                recovery_decision,
            }) => {
                let projection = DelegationRecoveryProjection::from(&recovery_decision);
                if let Some(authorization_id) = run.recovery_authorization_id.as_deref() {
                    self.record_recovery_event(
                        RecoveryMetricEventKind::Decision,
                        Some(&run.task_id),
                        Some(authorization_id),
                        Some(run.parent_conversation_id),
                        Some(run.child_conversation_id),
                        projection.proposed_action.as_deref(),
                        Some(&projection.cause_code),
                        Some(&projection.risk_class),
                        None,
                    );
                }
                Ok(ContinueAdmitOutcome::Created(run))
            }
            other => other,
        };
        match &admitted {
            Ok(ContinueAdmitOutcome::Created(run)) => {
                if let Some(authorization_id) = run.recovery_authorization_id.as_deref() {
                    for kind in [
                        RecoveryMetricEventKind::ConfirmationApproved,
                        RecoveryMetricEventKind::AuthorizationConsumed,
                    ] {
                        self.record_recovery_event(
                            kind,
                            Some(&run.task_id),
                            Some(authorization_id),
                            Some(run.parent_conversation_id),
                            Some(run.child_conversation_id),
                            Some("continue"),
                            None,
                            None,
                            None,
                        );
                    }
                }
            }
            Ok(ContinueAdmitOutcome::AuthorizedCreated { .. }) => {
                unreachable!("authorized created outcome normalized above")
            }
            Err(error) => self.record_recovery_admission_error(
                error,
                &req.target_task_id,
                req.parent_conversation_id,
                Some(target.child_conversation_id),
                "continue",
            ),
            Ok(ContinueAdmitOutcome::Idempotent(_)) => {}
        }

        // Test-only hold: cancel between durable reserve commit and handoff
        // registration. Production is a no-op when no gate is installed.
        #[cfg(any(test, feature = "test-utils"))]
        {
            LiveRuntimeState::honor_gate(&self.continue_post_reserve_gate).await;
        }

        // Post-reserve cancel check (does not drop the fence on None — the
        // Created path transfers it atomically into the handoff below).
        let reserved = match (admitted, self.take_inflight_cancel(inflight_id).await) {
            (Ok(ContinueAdmitOutcome::AuthorizedCreated { .. }), _) => {
                unreachable!("authorized created outcome normalized above")
            }
            (Ok(ContinueAdmitOutcome::Created(run)), Some(parent_end)) => {
                if let Err(error) = runs
                    .settle_terminal(
                        &run.task_id,
                        TerminalTaskWrite::canceled(
                            parent_end.durable_error_code(),
                            parent_end.termination.observed_at,
                            parent_end.audit(
                                DelegationRunStatus::Reserving,
                                run.admission_class.clone(),
                                Some(req.parent_tool_use_id.clone()),
                                None,
                            ),
                        ),
                    )
                    .await
                {
                    tracing::error!(
                        task_id = %run.task_id,
                        error = %error,
                        "[delegation] continue parent end failed to settle pre-handoff reserve"
                    );
                }
                return with_continuation_run_identity(
                    parent_end_setup_report(
                        run.agent_type,
                        &parent_end,
                        Some(run.child_conversation_id),
                    ),
                    &run.task_id,
                    &req.target_task_id,
                );
            }
            (Ok(ContinueAdmitOutcome::Idempotent(_)), Some(reason)) | (Err(_), Some(reason)) => {
                return parent_end_setup_report(
                    target.agent_type,
                    reason,
                    Some(target.child_conversation_id),
                );
            }
            (Ok(ContinueAdmitOutcome::Created(run)), None) => run,
            (Ok(ContinueAdmitOutcome::Idempotent(existing)), None) => {
                self.drop_inflight(inflight_id).await;
                return self
                    .continue_idempotent_with_terminal_intent(&existing, req.target_task_id)
                    .await;
            }
            (Err(e), None) => {
                self.drop_inflight(inflight_id).await;
                return report_err(
                    target.agent_type,
                    store_err_to_delegation_error(e),
                    Some(target.child_conversation_id),
                );
            }
        };

        // Test-only hold: after post-reserve cancel observed None, before the
        // fence-to-handoff transfer. Parent end can stamp the still-present
        // inflight here; transfer must consume that stamp under one lock.
        #[cfg(any(test, feature = "test-utils"))]
        {
            LiveRuntimeState::honor_gate(&self.continue_post_reserve_pre_handoff_gate).await;
        }

        // Atomic fence-to-handoff: re-check inflight parent-end, register
        // setups/live/coordination, then drop inflight — all under one lock.
        // Never drop_inflight before registration (that reopened a cancel gap).
        let handoff = match self
            .begin_run_admission_transfer(
                AdmissionHandoff {
                    task_id: reserved.task_id.clone(),
                    generation: reserved.generation,
                    child_conversation_id: reserved.child_conversation_id,
                    parent_connection_id: req.parent_connection_id.clone(),
                    parent_conversation_id: req.parent_conversation_id,
                    parent_tool_use_id: req.parent_tool_use_id.clone(),
                    task_preview: reserved.task_preview.clone().unwrap_or_default(),
                    child_connection_id: None,
                },
                Some(inflight_id),
            )
            .await
        {
            Ok(registration) => registration,
            Err(AdmissionFenceReject::ParentEnd(parent_end)) => {
                if let Err(error) = runs
                    .settle_terminal(
                        &reserved.task_id,
                        TerminalTaskWrite::canceled(
                            parent_end.durable_error_code(),
                            parent_end.termination.observed_at,
                            parent_end.audit(
                                DelegationRunStatus::Reserving,
                                reserved.admission_class.clone(),
                                Some(req.parent_tool_use_id.clone()),
                                None,
                            ),
                        ),
                    )
                    .await
                {
                    tracing::error!(
                        task_id = %reserved.task_id,
                        error = %error,
                        "[delegation] continue parent end failed to settle at handoff transfer"
                    );
                }
                return with_continuation_run_identity(
                    parent_end_setup_report(
                        reserved.agent_type,
                        &parent_end,
                        Some(reserved.child_conversation_id),
                    ),
                    &reserved.task_id,
                    &req.target_task_id,
                );
            }
            Err(AdmissionFenceReject::ExternalCanceled) => {
                if let Err(error) = runs
                    .settle_terminal(
                        &reserved.task_id,
                        explicit_cancellation_terminal(
                            "canceled",
                            DelegationRunStatus::Reserving,
                            false,
                        ),
                    )
                    .await
                {
                    tracing::error!(
                        task_id = %reserved.task_id,
                        error = %error,
                        "[delegation] continue external cancel failed to settle at handoff transfer"
                    );
                }
                return with_continuation_run_identity(
                    report_err(
                        reserved.agent_type,
                        DelegationError::Canceled {
                            reason: "canceled before spawn".into(),
                        },
                        Some(reserved.child_conversation_id),
                    ),
                    &reserved.task_id,
                    &req.target_task_id,
                );
            }
            Err(AdmissionFenceReject::BindOwnershipConflict(message)) => {
                // Challenger lost durable ownership: never settle the owner.
                // Replay durable terminal winner when present (FTW).
                if let Ok(Some(mut winner)) =
                    runs.load_terminal_winner_report(&reserved.task_id).await
                {
                    winner.task_id = Some(reserved.task_id.clone());
                    winner.continued_from_task_id = Some(req.target_task_id.clone());
                    winner.agent_type = Some(reserved.agent_type);
                    if winner.child_conversation_id.is_none() {
                        winner.child_conversation_id = Some(reserved.child_conversation_id);
                    }
                    return with_continuation_run_identity(
                        winner,
                        &reserved.task_id,
                        &req.target_task_id,
                    );
                }
                return with_continuation_run_identity(
                    report_err(
                        reserved.agent_type,
                        DelegationError::SpawnFailed(message),
                        Some(reserved.child_conversation_id),
                    ),
                    &reserved.task_id,
                    &req.target_task_id,
                );
            }
            Err(AdmissionFenceReject::BindFailed {
                message,
                child_connection_id: challenger_connection_id,
            }) => {
                // Non-ownership bind failure: ownership-filtered settle only
                // (unbound or same-conn reserving for this challenger id).
                match runs
                    .settle_pre_admission_failure_if_owned(
                        &reserved.task_id,
                        &challenger_connection_id,
                        failed_terminal(
                            "spawn_failed",
                            DelegationRunStatus::Reserving,
                            false,
                            AcpTerminationSource::Admission,
                            AcpTerminationReason::AdmissionFailed,
                            AcpTerminationClassification::Unexpected,
                        ),
                    )
                    .await
                {
                    Ok(Some(Settlement::Existing(winner))) => {
                        return with_continuation_run_identity(
                            {
                                let mut report = winner;
                                report.task_id = Some(reserved.task_id.clone());
                                report.continued_from_task_id = Some(req.target_task_id.clone());
                                report.agent_type = Some(reserved.agent_type);
                                if report.child_conversation_id.is_none() {
                                    report.child_conversation_id =
                                        Some(reserved.child_conversation_id);
                                }
                                report
                            },
                            &reserved.task_id,
                            &req.target_task_id,
                        );
                    }
                    Ok(Some(Settlement::Won(_))) | Ok(None) | Err(_) => {}
                }
                return with_continuation_run_identity(
                    report_err(
                        reserved.agent_type,
                        DelegationError::SpawnFailed(message),
                        Some(reserved.child_conversation_id),
                    ),
                    &reserved.task_id,
                    &req.target_task_id,
                );
            }
        };

        if let Some(report) = self
            .continue_abort_if_handoff_closed(ContinueHandoffGate {
                task_id: &reserved.task_id,
                handoff_connection_id: &handoff.child_connection_id,
                agent_type: reserved.agent_type,
                child_conversation_id: reserved.child_conversation_id,
                continued_from_task_id: &req.target_task_id,
                spawned_connection_id: None,
                claim_prompt_send: false,
            })
            .await
        {
            return report;
        }

        let cfg = self.config_snapshot().await;
        if let Some(report) = self
            .continue_abort_if_handoff_closed(ContinueHandoffGate {
                task_id: &reserved.task_id,
                handoff_connection_id: &handoff.child_connection_id,
                agent_type: reserved.agent_type,
                child_conversation_id: reserved.child_conversation_id,
                continued_from_task_id: &req.target_task_id,
                spawned_connection_id: None,
                claim_prompt_send: false,
            })
            .await
        {
            return report;
        }
        let (preferred_mode, preferred_config) =
            match re_resolve_continue_launch_config(&cfg, &reserved) {
                Ok(config) => config,
                Err(err) => {
                    let _ = runs
                        .settle_terminal(
                            &reserved.task_id,
                            failed_terminal(
                                "unresumable",
                                DelegationRunStatus::Reserving,
                                false,
                                AcpTerminationSource::Session,
                                AcpTerminationReason::SessionLost,
                                AcpTerminationClassification::Unexpected,
                            ),
                        )
                        .await;
                    {
                        let mut inner = self.pending.inner.lock().await;
                        inner.unreserve(&reserved.task_id, &handoff.child_connection_id);
                        inner.unregister_live_run(&handoff.child_connection_id);
                    }
                    return continue_reserved_error_report(
                        &reserved.task_id,
                        &req.target_task_id,
                        reserved.agent_type,
                        err,
                        Some(reserved.child_conversation_id),
                    );
                }
            };

        // External session id required for resume.
        let external_id = match conversation::Entity::find_by_id(reserved.child_conversation_id)
            .one(&runs.db().conn)
            .await
        {
            Ok(Some(c)) => c.external_id.filter(|s| !s.trim().is_empty()),
            Ok(None) => None,
            Err(_) => None,
        };
        if let Some(report) = self
            .continue_abort_if_handoff_closed(ContinueHandoffGate {
                task_id: &reserved.task_id,
                handoff_connection_id: &handoff.child_connection_id,
                agent_type: reserved.agent_type,
                child_conversation_id: reserved.child_conversation_id,
                continued_from_task_id: &req.target_task_id,
                spawned_connection_id: None,
                claim_prompt_send: false,
            })
            .await
        {
            return report;
        }
        let Some(external_id) = external_id else {
            self.record_recovery_event(
                RecoveryMetricEventKind::ResumeFailed,
                Some(&reserved.task_id),
                reserved.recovery_authorization_id.as_deref(),
                Some(reserved.parent_conversation_id),
                Some(reserved.child_conversation_id),
                Some("continue"),
                None,
                None,
                Some("unresumable"),
            );
            let settle = self
                .settle_bootstrap_unresumable(
                    &reserved.task_id,
                    Some(&handoff.child_connection_id),
                    bootstrap_refuse_message(BootstrapRefuseKind::MissingExternalSessionId),
                )
                .await;
            return self
                .continue_report_for_bootstrap_settle(
                    settle,
                    &reserved.task_id,
                    &req.target_task_id,
                    reserved.agent_type,
                    reserved.child_conversation_id,
                    BootstrapRefuseKind::MissingExternalSessionId,
                )
                .await;
        };

        // Parent cancel may settle the handoff before spawn starts.
        if let Some(report) = self
            .continue_abort_if_handoff_closed(ContinueHandoffGate {
                task_id: &reserved.task_id,
                handoff_connection_id: &handoff.child_connection_id,
                agent_type: reserved.agent_type,
                child_conversation_id: reserved.child_conversation_id,
                continued_from_task_id: &req.target_task_id,
                spawned_connection_id: None,
                claim_prompt_send: false,
            })
            .await
        {
            return report;
        }
        // External cancel immediately before resume launch. Continue has already
        // transferred the inflight fence into the handoff, so sticky-mark is
        // observed only via the pre-cancel buffer (still checked here).
        if self
            .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
            .await
        {
            // Inflight may already be deregistered at handoff transfer; still
            // close the handoff and settle the reserved run as canceled.
            if let Some(report) = self
                .continue_abort_if_handoff_closed(ContinueHandoffGate {
                    task_id: &reserved.task_id,
                    handoff_connection_id: &handoff.child_connection_id,
                    agent_type: reserved.agent_type,
                    child_conversation_id: reserved.child_conversation_id,
                    continued_from_task_id: &req.target_task_id,
                    spawned_connection_id: None,
                    claim_prompt_send: false,
                })
                .await
            {
                return report;
            }
            let _ = runs
                .settle_terminal(
                    &reserved.task_id,
                    explicit_cancellation_terminal(
                        "canceled",
                        DelegationRunStatus::Reserving,
                        false,
                    ),
                )
                .await;
            {
                let mut inner = self.pending.inner.lock().await;
                inner.unreserve(&reserved.task_id, &handoff.child_connection_id);
                inner.unregister_live_run(&handoff.child_connection_id);
            }
            self.drop_inflight(inflight_id).await;
            return with_continuation_run_identity(
                report_err(
                    reserved.agent_type,
                    DelegationError::Canceled {
                        reason: "canceled before spawn".into(),
                    },
                    Some(reserved.child_conversation_id),
                ),
                &reserved.task_id,
                &req.target_task_id,
            );
        }

        let workflow_launch = async {
            let workflow_binding = runs
                .workflow_child_mcp_binding(&reserved.task_id)
                .await
                .map_err(WorkflowLaunchLoadError::WorkflowBinding)?;
            let prompt = append_admitted_completion_instruction(
                &runs.db().conn,
                &reserved.task_id,
                &req.task,
            )
            .await
            .map_err(WorkflowLaunchLoadError::CompletionInstruction)?;
            Ok::<_, WorkflowLaunchLoadError>((workflow_binding, prompt))
        }
        .await;
        let (workflow_binding, dispatch_prompt) = match workflow_launch {
            Ok(workflow_launch) => workflow_launch,
            Err(error) => {
                tracing::error!(
                    task_id = %reserved.task_id,
                    error = %error,
                    "[delegation] workflow instruction binding load failed before continuation spawn"
                );
                let error_code = error
                    .durable_error_code(crate::acp::delegation::metrics::ADMISSION_FAILED_CODE)
                    .to_string();
                let error_message = error.to_string();
                if let Some(report) = self
                    .continue_abort_if_handoff_closed(ContinueHandoffGate {
                        task_id: &reserved.task_id,
                        handoff_connection_id: &handoff.child_connection_id,
                        agent_type: reserved.agent_type,
                        child_conversation_id: reserved.child_conversation_id,
                        continued_from_task_id: &req.target_task_id,
                        spawned_connection_id: None,
                        claim_prompt_send: false,
                    })
                    .await
                {
                    return report;
                }
                let settlement = runs
                    .settle_pre_admission_failure_if_owned(
                        &reserved.task_id,
                        &handoff.child_connection_id,
                        failed_terminal(
                            error_code.clone(),
                            DelegationRunStatus::Reserving,
                            false,
                            AcpTerminationSource::Admission,
                            AcpTerminationReason::AdmissionFailed,
                            AcpTerminationClassification::Unexpected,
                        ),
                    )
                    .await;
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.unreserve(&reserved.task_id, &handoff.child_connection_id);
                    inner.unregister_live_run(&handoff.child_connection_id);
                }
                self.drop_inflight(inflight_id).await;
                return match settlement {
                    Ok(Some(Settlement::Won(report) | Settlement::Existing(report))) => {
                        with_continuation_run_identity(
                            report,
                            &reserved.task_id,
                            &req.target_task_id,
                        )
                    }
                    Ok(None) => match runs.load_by_task_id(&reserved.task_id).await {
                        Ok(Some(run)) => with_continuation_run_identity(
                            run.to_persisted_task().to_report(None),
                            &reserved.task_id,
                            &req.target_task_id,
                        ),
                        Ok(None) => continue_reserved_error_report(
                            &reserved.task_id,
                            &req.target_task_id,
                            reserved.agent_type,
                            DelegationError::WorkflowAdmission {
                                code: error_code,
                                message: error_message,
                            },
                            Some(reserved.child_conversation_id),
                        ),
                        Err(error) => continue_reserved_error_report(
                            &reserved.task_id,
                            &req.target_task_id,
                            reserved.agent_type,
                            store_err_to_delegation_error(error),
                            Some(reserved.child_conversation_id),
                        ),
                    },
                    Err(error) => continue_reserved_error_report(
                        &reserved.task_id,
                        &req.target_task_id,
                        reserved.agent_type,
                        store_err_to_delegation_error(error),
                        Some(reserved.child_conversation_id),
                    ),
                };
            }
        };
        let spawn_result = self
            .spawner
            .spawn_resume_existing_with_workflow_binding(
                &req.parent_connection_id,
                reserved.agent_type,
                reserved.workspace_path.clone(),
                preferred_mode,
                preferred_config,
                external_id,
                Some(handoff.child_connection_id.clone()),
                workflow_binding,
            )
            .await;
        let child_connection_id = match spawn_result {
            Ok(id) => id,
            Err(_e) => {
                self.record_recovery_event(
                    RecoveryMetricEventKind::ResumeFailed,
                    Some(&reserved.task_id),
                    reserved.recovery_authorization_id.as_deref(),
                    Some(reserved.parent_conversation_id),
                    Some(reserved.child_conversation_id),
                    Some("continue"),
                    None,
                    None,
                    Some("unresumable"),
                );
                if let Some(report) = self
                    .continue_abort_if_handoff_closed(ContinueHandoffGate {
                        task_id: &reserved.task_id,
                        handoff_connection_id: &handoff.child_connection_id,
                        agent_type: reserved.agent_type,
                        child_conversation_id: reserved.child_conversation_id,
                        continued_from_task_id: &req.target_task_id,
                        spawned_connection_id: None,
                        claim_prompt_send: false,
                    })
                    .await
                {
                    return report;
                }
                let settle = self
                    .settle_bootstrap_unresumable(
                        &reserved.task_id,
                        Some(&handoff.child_connection_id),
                        bootstrap_refuse_message(BootstrapRefuseKind::ResumeLoadFailure),
                    )
                    .await;
                return self
                    .continue_report_for_bootstrap_settle(
                        settle,
                        &reserved.task_id,
                        &req.target_task_id,
                        reserved.agent_type,
                        reserved.child_conversation_id,
                        BootstrapRefuseKind::ResumeLoadFailure,
                    )
                    .await;
            }
        };

        // After bootstrap await: do not prompt if parent-end won the window.
        if let Some(report) = self
            .continue_abort_if_handoff_closed(ContinueHandoffGate {
                task_id: &reserved.task_id,
                handoff_connection_id: &handoff.child_connection_id,
                agent_type: reserved.agent_type,
                child_conversation_id: reserved.child_conversation_id,
                continued_from_task_id: &req.target_task_id,
                spawned_connection_id: Some(&child_connection_id),
                claim_prompt_send: false,
            })
            .await
        {
            return report;
        }
        // External cancel during resume spawn: after handoff transfer, cancel
        // typically buffers the handle (inflight already deregistered). Re-check
        // before prompt so we never enqueue work for a canceled tool call.
        if self
            .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
            .await
        {
            let _ = self.spawner.disconnect(&child_connection_id).await;
            if let Some(report) = self
                .continue_abort_if_handoff_closed(ContinueHandoffGate {
                    task_id: &reserved.task_id,
                    handoff_connection_id: &handoff.child_connection_id,
                    agent_type: reserved.agent_type,
                    child_conversation_id: reserved.child_conversation_id,
                    continued_from_task_id: &req.target_task_id,
                    spawned_connection_id: Some(&child_connection_id),
                    claim_prompt_send: false,
                })
                .await
            {
                return report;
            }
            let _ = runs
                .settle_terminal(
                    &reserved.task_id,
                    explicit_cancellation_terminal(
                        "canceled",
                        DelegationRunStatus::Reserving,
                        false,
                    ),
                )
                .await;
            {
                let mut inner = self.pending.inner.lock().await;
                inner.unreserve(&reserved.task_id, &handoff.child_connection_id);
                inner.unregister_live_run(&handoff.child_connection_id);
            }
            self.drop_inflight(inflight_id).await;
            return with_continuation_run_identity(
                report_err(
                    reserved.agent_type,
                    DelegationError::Canceled {
                        reason: "canceled before prompt".into(),
                    },
                    Some(reserved.child_conversation_id),
                ),
                &reserved.task_id,
                &req.target_task_id,
            );
        }

        // The admission handoff is keyed by this exact incarnation. A spawner
        // returning another id cannot safely receive the continued prompt.
        if child_connection_id != handoff.child_connection_id {
            self.record_recovery_event(
                RecoveryMetricEventKind::ResumeFailed,
                Some(&reserved.task_id),
                reserved.recovery_authorization_id.as_deref(),
                Some(reserved.parent_conversation_id),
                Some(reserved.child_conversation_id),
                Some("continue"),
                None,
                None,
                Some("unresumable"),
            );
            let _ = self.spawner.disconnect(&child_connection_id).await;
            let _ = runs
                .settle_terminal(
                    &reserved.task_id,
                    failed_terminal(
                        "unresumable",
                        DelegationRunStatus::Reserving,
                        false,
                        AcpTerminationSource::Session,
                        AcpTerminationReason::SessionLost,
                        AcpTerminationClassification::Unexpected,
                    ),
                )
                .await;
            let mut inner = self.pending.inner.lock().await;
            inner.unreserve(&reserved.task_id, &handoff.child_connection_id);
            inner.unregister_live_run(&handoff.child_connection_id);
            return continue_reserved_error_report(
                &reserved.task_id,
                &req.target_task_id,
                reserved.agent_type,
                DelegationError::Unresumable(
                    "resume returned an unexpected connection incarnation".into(),
                ),
                Some(reserved.child_conversation_id),
            );
        }

        // folder_id for prebound send: look up child conversation.
        let folder_id = match conversation::Entity::find_by_id(reserved.child_conversation_id)
            .one(&runs.db().conn)
            .await
        {
            Ok(Some(c)) => c.folder_id,
            _ => {
                let _ = self.spawner.disconnect(&child_connection_id).await;
                let _ = runs
                    .settle_terminal(
                        &reserved.task_id,
                        failed_terminal(
                            "spawn_failed",
                            DelegationRunStatus::Reserving,
                            false,
                            AcpTerminationSource::Admission,
                            AcpTerminationReason::AdmissionFailed,
                            AcpTerminationClassification::Unexpected,
                        ),
                    )
                    .await;
                let mut inner = self.pending.inner.lock().await;
                inner.unreserve(&reserved.task_id, &handoff.child_connection_id);
                inner.unregister_live_run(&handoff.child_connection_id);
                return continue_reserved_error_report(
                    &reserved.task_id,
                    &req.target_task_id,
                    reserved.agent_type,
                    DelegationError::SpawnFailed("child folder missing".into()),
                    Some(reserved.child_conversation_id),
                );
            }
        };

        // Final external-cancel fence immediately before prompt enqueue (cancel
        // may buffer after post-spawn check while folder lookup / incarnation
        // checks await). Fail closed: disconnect, no prompt.
        if self
            .setup_external_cancel_observed(inflight_id, req.external_handle.as_deref())
            .await
        {
            let _ = self.spawner.disconnect(&child_connection_id).await;
            if let Some(report) = self
                .continue_abort_if_handoff_closed(ContinueHandoffGate {
                    task_id: &reserved.task_id,
                    handoff_connection_id: &child_connection_id,
                    agent_type: reserved.agent_type,
                    child_conversation_id: reserved.child_conversation_id,
                    continued_from_task_id: &req.target_task_id,
                    spawned_connection_id: Some(&child_connection_id),
                    claim_prompt_send: false,
                })
                .await
            {
                return report;
            }
            let _ = runs
                .settle_terminal(
                    &reserved.task_id,
                    explicit_cancellation_terminal(
                        "canceled",
                        DelegationRunStatus::Reserving,
                        false,
                    ),
                )
                .await;
            {
                let mut inner = self.pending.inner.lock().await;
                inner.unreserve(&reserved.task_id, &child_connection_id);
                inner.unregister_live_run(&child_connection_id);
            }
            self.drop_inflight(inflight_id).await;
            return with_continuation_run_identity(
                report_err(
                    reserved.agent_type,
                    DelegationError::Canceled {
                        reason: "canceled before prompt".into(),
                    },
                    Some(reserved.child_conversation_id),
                ),
                &reserved.task_id,
                &req.target_task_id,
            );
        }

        // Final gate immediately before prompt enqueue: open check + claim
        // the prompt-send lease under one pending lock so parent-end cannot
        // slip between the final re-check and send start.
        if let Some(report) = self
            .continue_abort_if_handoff_closed(ContinueHandoffGate {
                task_id: &reserved.task_id,
                handoff_connection_id: &child_connection_id,
                agent_type: reserved.agent_type,
                child_conversation_id: reserved.child_conversation_id,
                continued_from_task_id: &req.target_task_id,
                spawned_connection_id: Some(&child_connection_id),
                claim_prompt_send: true,
            })
            .await
        {
            return report;
        }

        let link = crate::acp::delegation::spawner::DelegationLink {
            parent_conversation_id: req.parent_conversation_id,
            parent_tool_use_id: req.parent_tool_use_id.clone(),
            delegation_call_id: reserved.task_id.clone(),
        };
        let accepted = match self
            .spawner
            .send_prompt_linked_for_delegation(
                &child_connection_id,
                dispatch_prompt,
                link,
                Some((reserved.child_conversation_id, folder_id)),
            )
            .await
        {
            Ok(a) => a,
            Err(e) => {
                self.continue_clear_prompt_send_lease(&child_connection_id)
                    .await;
                if let Some(report) = self
                    .continue_abort_if_handoff_closed(ContinueHandoffGate {
                        task_id: &reserved.task_id,
                        handoff_connection_id: &child_connection_id,
                        agent_type: reserved.agent_type,
                        child_conversation_id: reserved.child_conversation_id,
                        continued_from_task_id: &req.target_task_id,
                        spawned_connection_id: Some(&child_connection_id),
                        claim_prompt_send: false,
                    })
                    .await
                {
                    return report;
                }
                let _ = self.spawner.disconnect(&child_connection_id).await;
                let _ = runs
                    .settle_terminal(
                        &reserved.task_id,
                        failed_terminal(
                            "spawn_failed",
                            DelegationRunStatus::Reserving,
                            true,
                            AcpTerminationSource::Transport,
                            AcpTerminationReason::TransportDisconnected,
                            AcpTerminationClassification::Unexpected,
                        ),
                    )
                    .await;
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.unreserve(&reserved.task_id, &child_connection_id);
                    inner.unregister_live_run(&child_connection_id);
                }
                return continue_reserved_error_report(
                    &reserved.task_id,
                    &req.target_task_id,
                    reserved.agent_type,
                    DelegationError::SpawnFailed(e.to_string()),
                    Some(reserved.child_conversation_id),
                );
            }
        };

        // Parent-end may have settled while send was gated. Clear the lease
        // then re-check; a closed handoff cancels the accepted prompt.
        self.continue_clear_prompt_send_lease(&child_connection_id)
            .await;
        if let Some(report) = self
            .continue_abort_if_handoff_closed(ContinueHandoffGate {
                task_id: &reserved.task_id,
                handoff_connection_id: &child_connection_id,
                agent_type: reserved.agent_type,
                child_conversation_id: reserved.child_conversation_id,
                continued_from_task_id: &req.target_task_id,
                spawned_connection_id: Some(&child_connection_id),
                claim_prompt_send: false,
            })
            .await
        {
            return report;
        }

        // Task 4: shared post-accept promote helper (honest admission codes).
        let promote_outcome = match runs
            .promote_running_detailed(
                &reserved.task_id,
                &child_connection_id,
                accepted.prompt_accepted_at,
            )
            .await
        {
            Ok(outcome) => outcome,
            Err(e) => PromoteRunningOutcome {
                kind: PromoteRunningKind::Permanent {
                    message: e.to_string(),
                },
                meta: PromoteAttemptMeta::default(),
            },
        };
        match self
            .handle_post_accept_promote(
                PostAcceptPromoteCtx {
                    task_id: reserved.task_id.clone(),
                    child_connection_id: child_connection_id.clone(),
                    child_conversation_id: reserved.child_conversation_id,
                    agent_type: reserved.agent_type,
                    parent_connection_id: req.parent_connection_id.clone(),
                    parent_tool_use_id: req.parent_tool_use_id.clone(),
                    continued_from_task_id: Some(req.target_task_id.clone()),
                    generation: reserved.generation,
                    admission_class: reserved.admission_class,
                    inflight_id: None,
                    runtime: None,
                },
                promote_outcome,
            )
            .await
        {
            PostAcceptPromoteResult::Proceed { .. } => {
                // Continuation generations count at the durable accepted boundary
                // (exactly once per task_id / generation).
                self.metrics
                    .record_accepted_for_task(&reserved.task_id, reserved.agent_type);
                if let Some(report) = self
                    .continue_abort_if_handoff_closed(ContinueHandoffGate {
                        task_id: &reserved.task_id,
                        handoff_connection_id: &child_connection_id,
                        agent_type: reserved.agent_type,
                        child_conversation_id: reserved.child_conversation_id,
                        continued_from_task_id: &req.target_task_id,
                        spawned_connection_id: Some(&child_connection_id),
                        claim_prompt_send: false,
                    })
                    .await
                {
                    return report;
                }
            }
            PostAcceptPromoteResult::Failed(report) => {
                // Helper already canceled/disconnected/released; re-check handoff
                // for parent-end races that may have settled a different code.
                if let Some(handoff_report) = self
                    .continue_abort_if_handoff_closed(ContinueHandoffGate {
                        task_id: &reserved.task_id,
                        handoff_connection_id: &child_connection_id,
                        agent_type: reserved.agent_type,
                        child_conversation_id: reserved.child_conversation_id,
                        continued_from_task_id: &req.target_task_id,
                        spawned_connection_id: Some(&child_connection_id),
                        claim_prompt_send: false,
                    })
                    .await
                {
                    return handoff_report;
                }
                return report;
            }
        }

        #[cfg(any(test, feature = "test-utils"))]
        {
            LiveRuntimeState::honor_gate(&self.continue_pre_park_gate).await;
        }

        // Gen-1 first-terminal-wins park: early_complete / early_cancel /
        // admission_buffer, then re-drain after admitted_running. Parent-end
        // already unregisters the handoff — never insert Running after that.
        #[allow(clippy::large_enum_variant)] // Continue handoff resolution carries the complete terminal evidence.
        enum ContinueAdmissionDisposition {
            ChildTerminal(ObservedTerminal),
            Running,
        }
        let task_preview = reserved.task_preview.clone().unwrap_or_default();
        let started_at = Instant::now();
        let (runtime, disposition) = {
            let mut inner = self.pending.inner.lock().await;
            let mut child_terminal: Option<(u64, ObservedTerminal)> = None;
            let mut consider = |stamp: u64, terminal: ObservedTerminal| match &child_terminal {
                Some((s, _)) if *s <= stamp => {}
                _ => child_terminal = Some((stamp, terminal)),
            };
            if let Some((stamp, terminal)) = inner.take_early_complete(&reserved.task_id) {
                consider(stamp, terminal);
            }
            if let Some((stamp, terminal)) = inner.take_early_cancel(&child_connection_id) {
                consider(
                    stamp,
                    terminal
                        .with_child_identity(reserved.child_conversation_id, reserved.agent_type),
                );
            }
            if let Some((stamp, terminal)) =
                inner.take_first_admission_terminal(&child_connection_id)
            {
                consider(
                    stamp,
                    terminal
                        .with_child_identity(reserved.child_conversation_id, reserved.agent_type),
                );
            }
            let handoff_open = inner
                .live_runs_by_connection
                .contains_key(&child_connection_id)
                && inner
                    .coordination_by_child
                    .get(&child_connection_id)
                    .is_some_and(|c| !c.admitted_running && c.task_id == reserved.task_id);
            let closed_disposition = inner
                .resolve_terminal_intent(&reserved.task_id)
                .map(|intent| intent.disposition);

            if let Some(disposition) = closed_disposition {
                inner.unreserve(&reserved.task_id, &child_connection_id);
                (
                    Arc::new(LiveRuntimeState::new(
                        accepted.prompt_accepted_at,
                        PathBuf::new(),
                    )),
                    ContinueAdmissionDisposition::ChildTerminal(
                        observed_terminal_from_handoff_disposition(
                            &disposition,
                            DelegationRunStatus::Running,
                            reserved.child_conversation_id,
                            reserved.agent_type,
                        ),
                    ),
                )
            } else if let Some((_, terminal)) = child_terminal {
                inner.unreserve(&reserved.task_id, &child_connection_id);
                (
                    inner
                        .coordination_by_child
                        .get(&child_connection_id)
                        .map(|c| c.runtime.clone())
                        .unwrap_or_else(|| {
                            Arc::new(LiveRuntimeState::new(
                                accepted.prompt_accepted_at,
                                PathBuf::new(),
                            ))
                        }),
                    ContinueAdmissionDisposition::ChildTerminal(terminal),
                )
            } else if !handoff_open {
                inner.unreserve(&reserved.task_id, &child_connection_id);
                (
                    Arc::new(LiveRuntimeState::new(
                        accepted.prompt_accepted_at,
                        PathBuf::new(),
                    )),
                    {
                        let observed_at = Utc::now();
                        let outcome = DelegationOutcome::from_err(
                            DelegationError::Canceled {
                                reason: "parent_canceled".into(),
                            },
                            Some(reserved.child_conversation_id),
                        );
                        ContinueAdmissionDisposition::ChildTerminal(observed_terminal_from_outcome(
                            outcome,
                            ParentEndContext::legacy(
                                ParentTurnEndReason::ParentCanceled,
                                observed_at,
                                true,
                            )
                            .audit(
                                DelegationRunStatus::Running,
                                AdmissionClass::NormalRevision,
                                None,
                                Some(child_connection_id.clone()),
                            ),
                            observed_at,
                        ))
                    },
                )
            } else {
                if let Some(coord) = inner.coordination_by_child.get_mut(&child_connection_id) {
                    coord.admitted_running = true;
                    coord.run_registration.child_conversation_id = reserved.child_conversation_id;
                    inner
                        .live_connection_by_conversation
                        .insert(reserved.child_conversation_id, child_connection_id.clone());
                    if let Some(registration) =
                        inner.live_runs_by_connection.get_mut(&child_connection_id)
                    {
                        registration.child_conversation_id = reserved.child_conversation_id;
                    }
                }
                // Post-admit re-drain: terminal buffered during admitted_running flip.
                if let Some((_stamp, terminal)) =
                    inner.take_first_admission_terminal(&child_connection_id)
                {
                    let runtime = inner
                        .coordination_by_child
                        .get(&child_connection_id)
                        .map(|c| c.runtime.clone())
                        .unwrap_or_else(|| {
                            Arc::new(LiveRuntimeState::new(
                                accepted.prompt_accepted_at,
                                PathBuf::new(),
                            ))
                        });
                    inner.unreserve(&reserved.task_id, &child_connection_id);
                    (
                        runtime,
                        ContinueAdmissionDisposition::ChildTerminal(terminal.with_child_identity(
                            reserved.child_conversation_id,
                            reserved.agent_type,
                        )),
                    )
                } else {
                    let runtime = inner
                        .coordination_by_child
                        .get(&child_connection_id)
                        .map(|c| c.runtime.clone())
                        .unwrap_or_else(|| {
                            Arc::new(LiveRuntimeState::new(
                                accepted.prompt_accepted_at,
                                PathBuf::new(),
                            ))
                        });
                    if let Ok(mut projector) = runtime.projector.try_lock() {
                        projector.rebase_started_at(accepted.prompt_accepted_at);
                    }
                    inner.unreserve(&reserved.task_id, &child_connection_id);
                    inner.running.insert(
                        reserved.task_id.clone(),
                        RunningTask {
                            child_connection_id: child_connection_id.clone(),
                            child_conversation_id: reserved.child_conversation_id,
                            parent_connection_id: req.parent_connection_id.clone(),
                            parent_tool_use_id: req.parent_tool_use_id.clone(),
                            agent_type: reserved.agent_type,
                            generation: reserved.generation,
                            task_preview: task_preview.clone(),
                            external_handle: req.external_handle.clone(),
                            started_at,
                            runtime: runtime.clone(),
                        },
                    );
                    (runtime, ContinueAdmissionDisposition::Running)
                }
            }
        };

        if let ContinueAdmissionDisposition::ChildTerminal(observed) = disposition {
            // Prefer durable parent-end settlement if it already won.
            if let Ok(Some(existing)) = runs.load_by_task_id(&reserved.task_id).await {
                use crate::db::entities::delegation_task_run::DelegationRunStatus;
                if matches!(
                    existing.run_status,
                    DelegationRunStatus::Completed
                        | DelegationRunStatus::Failed
                        | DelegationRunStatus::Canceled
                ) {
                    let _ = self.spawner.disconnect(&child_connection_id).await;
                    {
                        let mut inner = self.pending.inner.lock().await;
                        inner.unregister_live_run(&child_connection_id);
                    }
                    return continue_idempotent_ack(&existing, req.target_task_id);
                }
            }
            let outcome = observed.outcome;
            let terminal = observed.terminal;
            let result_text = observed.result_text;
            let (extra_paths, workspace) = report_harvest_context_from_runtime(Some(&runtime));
            let (terminal, result_text, card_summary, completion_input) = self
                .prepare_terminal_for_workflow(
                    &reserved.task_id,
                    terminal,
                    result_text,
                    &extra_paths,
                    workspace.as_deref(),
                )
                .await;
            let mut ctx = SettleContext {
                parent_connection_id: req.parent_connection_id.clone(),
                parent_tool_use_id: req.parent_tool_use_id.clone(),
                child_connection_id: child_connection_id.clone(),
                child_conversation_id: reserved.child_conversation_id,
                agent_type: reserved.agent_type,
                task_preview: task_preview.clone(),
                duration_ms: started_at.elapsed().as_millis() as u64,
                cancel_turn: matches!(
                    &outcome,
                    DelegationOutcome::Err { code, .. } if is_canceled_error_code(code)
                ),
                disconnect_on_loss: true,
                message: None,
                attention_resolution: AttentionResolutionCode::TaskTerminal,
                runtime: Some(runtime),
                card_summary,
                completion_input,
            };
            let (_, _, _, message) = terminal_fields(&outcome);
            ctx.message = message;
            let mut report = self
                .settle_task(&reserved.task_id, terminal, result_text, ctx)
                .await;
            report.continued_from_task_id = Some(req.target_task_id);
            report.reused_session = None;
            return report;
        }

        self.notify_supervisor();

        // Continue owns a real parent card just like initial delegation. The
        // payload contains only the server-derived preview and never a card
        // summary or child-authored result text.
        let _publication = runtime.publication_lock.lock().await;
        LiveRuntimeState::honor_gate(&runtime.publication_gate).await;
        if !runtime.terminal.load(Ordering::Acquire) {
            let runtime_stats = runtime.projector.lock().await.snapshot();
            let attention_request = self
                .latest_open_attention(req.parent_conversation_id, &reserved.task_id)
                .await;
            let started_wall = runtime_stats.started_at;
            self.write_meta_if_real(
                &req.parent_connection_id,
                &req.parent_tool_use_id,
                build_delegation_meta(&DelegationMetaSnapshot {
                    status: "running".into(),
                    task_preview: Some(task_preview.clone()),
                    task_id: reserved.task_id.clone(),
                    child_connection_id: Some(child_connection_id.clone()),
                    child_conversation_id: reserved.child_conversation_id,
                    error_code: None,
                    text_preview: None,
                    started_at: started_wall,
                    finished_at: None,
                    runtime_stats: Some(runtime_stats.clone()),
                    attention_request: attention_request.clone(),
                }),
            )
            .await;
            self.emit_started_if_real(
                &req.parent_connection_id,
                &req.parent_tool_use_id,
                &child_connection_id,
                reserved.child_conversation_id,
                reserved.agent_type,
                &task_preview,
                &reserved.task_id,
                started_wall,
                runtime_stats,
                attention_request,
            )
            .await;
            runtime.started_published.store(true, Ordering::Release);
        }
        drop(_publication);

        // Second pre-cancel: notifications/cancelled during resume/prompt
        // admission after running registration.
        if let Some(handle) = req.external_handle.as_deref() {
            if self.take_pre_canceled_handle(handle).await {
                let removed = {
                    let mut inner = self.pending.inner.lock().await;
                    match inner.running.remove(&reserved.task_id) {
                        Some(task) => {
                            inner.settling.insert(reserved.task_id.clone(), task);
                            true
                        }
                        None => false,
                    }
                };
                if removed {
                    let duration_ms = started_at.elapsed().as_millis() as u64;
                    let outcome =
                        canceled_outcome(reserved.child_conversation_id, "canceled before await");
                    let terminal = explicit_cancellation_terminal(
                        "canceled",
                        DelegationRunStatus::Running,
                        true,
                    );
                    let result_text = None;
                    let mut ctx = SettleContext {
                        parent_connection_id: req.parent_connection_id.clone(),
                        parent_tool_use_id: req.parent_tool_use_id.clone(),
                        child_connection_id: child_connection_id.clone(),
                        child_conversation_id: reserved.child_conversation_id,
                        agent_type: reserved.agent_type,
                        task_preview: task_preview.clone(),
                        duration_ms,
                        cancel_turn: true,
                        disconnect_on_loss: true,
                        message: None,
                        attention_resolution: AttentionResolutionCode::TaskTerminal,
                        runtime: Some(runtime),
                        card_summary: None,
                        completion_input: None,
                    };
                    let (_, _, _, message) = terminal_fields(&outcome);
                    ctx.message = message;
                    let mut report = self
                        .settle_task(&reserved.task_id, terminal, result_text, ctx)
                        .await;
                    report.continued_from_task_id = Some(req.target_task_id);
                    report.reused_session = None;
                    return report;
                }
            }
        }

        continue_running_ack(
            reserved.task_id,
            reserved.child_conversation_id,
            reserved.agent_type,
            req.target_task_id,
        )
    }

    /// After bootstrap await / before prompt: if parent-end or durable
    /// terminal already closed the continue handoff, disconnect any spawned
    /// child and return the durable terminal report without prompting.
    ///
    /// Handoff openness is re-checked **after** the durable await so a concurrent
    /// parent cancel that closes the live registration (and may still be writing
    /// the terminal row) cannot be missed by a stale pre-await snapshot.
    ///
    /// When `claim_prompt_send` is true and the handoff is still open, claim
    /// the prompt-send lease under the same lock as the open check so parent
    /// end cannot slip between the final open re-check and enqueue start.
    async fn continue_abort_if_handoff_closed(
        &self,
        gate: ContinueHandoffGate<'_>,
    ) -> Option<DelegationTaskReport> {
        use crate::db::entities::delegation_task_run::DelegationRunStatus;

        let ContinueHandoffGate {
            task_id,
            handoff_connection_id,
            agent_type,
            child_conversation_id,
            continued_from_task_id,
            spawned_connection_id,
            claim_prompt_send,
        } = gate;

        let handoff_still_open = |inner: &PendingInner| {
            inner
                .live_runs_by_connection
                .contains_key(handoff_connection_id)
                && inner
                    .coordination_by_child
                    .get(handoff_connection_id)
                    .is_some_and(|c| !c.admitted_running && c.task_id == task_id)
        };

        let runs = self.run_store.as_ref()?;
        let existing = match runs.load_by_task_id(task_id).await {
            Ok(Some(run)) => run,
            Ok(None) | Err(_) => {
                // Re-check after durable await (TOCTOU: cancel may close handoff
                // while we were loading, or the row may simply be gone).
                let still_open = {
                    let mut inner = self.pending.inner.lock().await;
                    let open = handoff_still_open(&inner);
                    if open && claim_prompt_send {
                        if let Some(coord) =
                            inner.coordination_by_child.get_mut(handoff_connection_id)
                        {
                            coord.prompt_send_lease = true;
                            coord.prompt_may_have_executed = true;
                        }
                    }
                    open
                };
                if still_open {
                    return None;
                }
                if let Some(conn) = spawned_connection_id {
                    // Best-effort cancel of any accepted in-flight prompt, then disconnect.
                    let _ = self.spawner.cancel(conn).await;
                    let _ = self.spawner.disconnect(conn).await;
                }
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.unreserve(task_id, handoff_connection_id);
                    inner.unregister_live_run(handoff_connection_id);
                }
                // Prefer durable parent-end code when the row has already
                // terminalized; otherwise wire stable `parent_canceled` (not
                // generic `canceled` from DelegationError::Canceled).
                return Some(
                    self.continue_closed_handoff_report(
                        runs,
                        task_id,
                        agent_type,
                        child_conversation_id,
                        continued_from_task_id,
                    )
                    .await,
                );
            }
        };

        // Critical: re-read handoff under the lock *after* the durable await so
        // a cancel that raced load_by_task_id cannot leave a stale still_open.
        // When claiming the prompt-send lease, the open check and claim are
        // the same critical section (no await between them).
        let terminal = matches!(
            existing.run_status,
            DelegationRunStatus::Completed
                | DelegationRunStatus::Failed
                | DelegationRunStatus::Canceled
        );
        let still_open = {
            let mut inner = self.pending.inner.lock().await;
            let open = handoff_still_open(&inner);
            if open && !terminal && claim_prompt_send {
                if let Some(coord) = inner.coordination_by_child.get_mut(handoff_connection_id) {
                    coord.prompt_send_lease = true;
                    coord.prompt_may_have_executed = true;
                }
            }
            open
        };

        if !terminal && still_open {
            return None;
        }
        if terminal || !still_open {
            if let Some(conn) = spawned_connection_id {
                let _ = self.spawner.cancel(conn).await;
                let _ = self.spawner.disconnect(conn).await;
            }
            {
                let mut inner = self.pending.inner.lock().await;
                inner.unreserve(task_id, handoff_connection_id);
                inner.unregister_live_run(handoff_connection_id);
            }
            if terminal {
                return Some(continue_idempotent_ack(
                    &existing,
                    continued_from_task_id.to_string(),
                ));
            }
            // Handoff closed while durable row still looked nonterminal —
            // reload so a concurrent parent_canceled CAS is projected, else
            // report the stable parent-end wire code (not generic canceled).
            return Some(
                self.continue_closed_handoff_report(
                    runs,
                    task_id,
                    agent_type,
                    child_conversation_id,
                    continued_from_task_id,
                )
                .await,
            );
        }
        None
    }

    /// Idempotent continue response for a fingerprint / admit match, honoring
    /// process-local terminal intent when the durable row is still Reserving.
    ///
    /// Non-destructive: peeks [`PendingInner::resolve_terminal_intent`] so
    /// replay never returns a "still admitting" running ack after a claim, and
    /// never consumes the park while durable is non-terminal.
    async fn continue_idempotent_with_terminal_intent(
        &self,
        existing: &crate::acp::delegation::run_store::PersistedRun,
        continued_from_task_id: String,
    ) -> DelegationTaskReport {
        use crate::db::entities::delegation_task_run::DelegationRunStatus;

        if matches!(existing.run_status, DelegationRunStatus::Reserving) {
            let intent = {
                let inner = self.pending.inner.lock().await;
                inner.resolve_terminal_intent(&existing.task_id)
            };
            if let Some(intent) = intent {
                return intent.to_report(
                    &existing.task_id,
                    existing.agent_type,
                    existing.child_conversation_id,
                    Some(&continued_from_task_id),
                );
            }
        }
        continue_idempotent_ack(existing, continued_from_task_id)
    }

    /// Build the continue report after a closed handoff.
    ///
    /// Preference order:
    /// 1. Durable terminal row → [`continue_idempotent_ack`] (real `error_code`)
    /// 2. Parked disposition / terminal intent (non-destructive peek)
    /// 3. Re-read durable after disposition miss (settle may have committed and
    ///    cleared the park between the first load and peek)
    /// 4. Last-resort fail-closed `parent_canceled` only when re-read is still
    ///    non-terminal AND disposition is absent.
    async fn continue_closed_handoff_report(
        &self,
        runs: &Arc<crate::acp::delegation::run_store::RunStore>,
        task_id: &str,
        agent_type: AgentType,
        child_conversation_id: i32,
        continued_from_task_id: &str,
    ) -> DelegationTaskReport {
        use crate::db::entities::delegation_task_run::DelegationRunStatus;

        if let Ok(Some(run)) = runs.load_by_task_id(task_id).await {
            let terminal = matches!(
                run.run_status,
                DelegationRunStatus::Completed
                    | DelegationRunStatus::Failed
                    | DelegationRunStatus::Canceled
            );
            if terminal {
                // Durable won: drop any parked fallback for this task.
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.clear_closed_handoff_disposition(task_id);
                }
                return continue_idempotent_ack(&run, continued_from_task_id.to_string());
            }
        }

        // Tests pin here so settle can commit (and clear the park) after the
        // first durable load saw Reserving and before disposition peek.
        #[cfg(any(test, feature = "test-utils"))]
        {
            LiveRuntimeState::honor_gate(&self.continue_closed_handoff_post_durable_gate).await;
        }

        // Parent-end drain releases the handoff before durable settle commits;
        // project parked intent non-destructively so parent_turn_failed /
        // join_abandoned / parent_disconnected (and earlier child terminals)
        // are not misreported as parent_canceled, and retry peeks stay stable.
        let intent = {
            let inner = self.pending.inner.lock().await;
            inner.resolve_terminal_intent(task_id)
        };
        if let Some(intent) = intent {
            return intent.to_report(
                task_id,
                agent_type,
                child_conversation_id,
                Some(continued_from_task_id),
            );
        }

        // Race-safe recovery: settle may have committed and cleared the park
        // after the first durable load saw Reserving. Re-read durable; if now
        // terminal, project the real error_code via continue_idempotent_ack.
        if let Ok(Some(run)) = runs.load_by_task_id(task_id).await {
            let terminal = matches!(
                run.run_status,
                DelegationRunStatus::Completed
                    | DelegationRunStatus::Failed
                    | DelegationRunStatus::Canceled
            );
            if terminal {
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.clear_closed_handoff_disposition(task_id);
                }
                return continue_idempotent_ack(&run, continued_from_task_id.to_string());
            }
        }

        // Fail-closed last resort: both re-read still non-terminal AND
        // disposition absent (e.g. non-parent-end unreserve race).
        tracing::warn!(
            task_id = %task_id,
            "[delegation] continue closed handoff: no durable terminal and no parked disposition; fail-closed parent_canceled"
        );
        let mut report = parent_end_setup_report(
            agent_type,
            ParentEndContext::legacy(ParentTurnEndReason::ParentCanceled, Utc::now(), true),
            Some(child_conversation_id),
        );
        report.task_id = Some(task_id.to_string());
        report.continued_from_task_id = Some(continued_from_task_id.to_string());
        report
    }

    /// Drop a previously claimed prompt-send lease (idempotent if the handoff
    /// was already unregistered by parent-end).
    async fn continue_clear_prompt_send_lease(&self, handoff_connection_id: &str) {
        let mut inner = self.pending.inner.lock().await;
        if let Some(coord) = inner.coordination_by_child.get_mut(handoff_connection_id) {
            coord.prompt_send_lease = false;
        }
    }

    /// Shared post-accept promote outcome handler for gen-1 and continuation.
    ///
    /// Classifies [`PromoteRunningOutcome`] without collapsing through
    /// [`store_err_to_delegation_error`] (never surfaces post-accept failures as
    /// `spawn_failed`). Settlement ownership follows the bootstrap claim-first
    /// pattern: intended `admission_failed` / `budget_exhausted` payloads are
    /// retained on `PendingTerminalRetry` (no PE-rewrite arm).
    async fn handle_post_accept_promote(
        &self,
        ctx: PostAcceptPromoteCtx,
        outcome: PromoteRunningOutcome,
    ) -> PostAcceptPromoteResult {
        let PostAcceptPromoteCtx {
            task_id,
            child_connection_id,
            child_conversation_id,
            agent_type,
            parent_connection_id,
            parent_tool_use_id: _,
            continued_from_task_id,
            generation,
            admission_class,
            inflight_id,
            runtime,
        } = ctx;
        let meta = outcome.meta;
        let failure_class = promote_failure_class(&outcome.kind);
        // Promote-local retry counters (busy / locked / busy_snapshot).
        // busy_snapshot only increments when meta classified extended 517.
        self.metrics.record_promote_retries(
            meta.busy_retries,
            meta.locked_retries,
            meta.busy_snapshot_retries,
        );
        // Aggregate post-retry-loop log (full required context). Per-attempt
        // logs remain in run_store outside the Task 7 file map; this broker
        // line is the brief-compliant structured surface.
        crate::acp::delegation::metrics::emit_promote_structured_log(
            tracing::Level::INFO,
            "[delegation] post-accept promote outcome",
            &task_id,
            generation,
            agent_type,
            &admission_class,
            meta.attempts,
            meta.last_sqlite_primary,
            meta.last_sqlite_extended,
            failure_class,
            None,
            false,
        );
        // Also surface retry class totals without free-form error text.
        if meta.busy_retries > 0 || meta.locked_retries > 0 || meta.busy_snapshot_retries > 0 {
            tracing::info!(
                target: "codeg::delegation",
                task_id = %task_id,
                generation,
                agent_type = crate::acp::delegation::metrics::agent_type_label(agent_type),
                admission_class = ?admission_class,
                attempt = meta.attempts,
                busy_retries = meta.busy_retries,
                locked_retries = meta.locked_retries,
                busy_snapshot_retries = meta.busy_snapshot_retries,
                sqlite_primary = meta.last_sqlite_primary,
                sqlite_extended = meta.last_sqlite_extended,
                failure_class,
                "[delegation] post-accept promote retry totals"
            );
        }

        match outcome.kind {
            PromoteRunningKind::Promoted { .. } => PostAcceptPromoteResult::Proceed {
                already_running: false,
            },
            PromoteRunningKind::AlreadyRunning { .. } => PostAcceptPromoteResult::Proceed {
                already_running: true,
            },
            PromoteRunningKind::TerminalWinner { run } => {
                // Replay durable winner; cancel+disconnect accepted child (idempotent).
                if let Err(e) = self.spawner.cancel(&child_connection_id).await {
                    tracing::warn!(
                        task_id = %task_id,
                        error = %e,
                        "[delegation] post-accept terminal-winner cancel failed (non-blocking)"
                    );
                }
                let _ = self.spawner.disconnect(&child_connection_id).await;
                self.post_accept_release_coordination(
                    &task_id,
                    &child_connection_id,
                    inflight_id,
                    runtime.as_ref(),
                )
                .await;
                let mut report = run.to_persisted_task().to_report(None);
                report.agent_type = Some(agent_type);
                report.child_conversation_id = Some(child_conversation_id);
                if let Some(from) = continued_from_task_id {
                    report.continued_from_task_id = Some(from);
                }
                PostAcceptPromoteResult::Failed(report)
            }
            PromoteRunningKind::BudgetExhausted { message } => {
                self.metrics.record_promote_failure(
                    crate::acp::delegation::metrics::PROMOTE_FAILURE_BUDGET,
                );
                self.settle_post_accept_admission_failure(
                    &task_id,
                    &child_connection_id,
                    child_conversation_id,
                    agent_type,
                    &parent_connection_id,
                    continued_from_task_id.as_deref(),
                    generation,
                    admission_class,
                    inflight_id,
                    runtime,
                    crate::acp::delegation::metrics::BUDGET_EXHAUSTED_CODE,
                    message,
                    meta,
                    failure_class,
                    None,
                )
                .await
            }
            PromoteRunningKind::RetryExhausted { class, message } => {
                self.metrics.record_promote_failure(
                    crate::acp::delegation::metrics::PROMOTE_FAILURE_BUSY_EXHAUSTED,
                );
                // admission_failed_by_agent is counted only on durable
                // Settlement::Won with winner error_code == admission_failed
                // (see settle_post_accept_admission_failure) — never for losers.
                self.settle_post_accept_admission_failure(
                    &task_id,
                    &child_connection_id,
                    child_conversation_id,
                    agent_type,
                    &parent_connection_id,
                    continued_from_task_id.as_deref(),
                    generation,
                    admission_class,
                    inflight_id,
                    runtime,
                    crate::acp::delegation::metrics::ADMISSION_FAILED_CODE,
                    message,
                    meta,
                    failure_class,
                    Some(promote_retry_class_label(class)),
                )
                .await
            }
            PromoteRunningKind::StateConflict { class, message } => {
                self.metrics
                    .record_promote_failure(crate::acp::delegation::metrics::PROMOTE_FAILURE_CAS);
                tracing::warn!(
                    task_id = %task_id,
                    generation,
                    agent_type = ?agent_type,
                    admission_class = ?admission_class,
                    conflict_class = ?class,
                    failure_class,
                    "[delegation] post-accept promote state conflict → admission_failed"
                );
                self.settle_post_accept_admission_failure(
                    &task_id,
                    &child_connection_id,
                    child_conversation_id,
                    agent_type,
                    &parent_connection_id,
                    continued_from_task_id.as_deref(),
                    generation,
                    admission_class,
                    inflight_id,
                    runtime,
                    crate::acp::delegation::metrics::ADMISSION_FAILED_CODE,
                    message,
                    meta,
                    failure_class,
                    None,
                )
                .await
            }
            PromoteRunningKind::Permanent { message } => {
                self.metrics.record_promote_failure(
                    crate::acp::delegation::metrics::PROMOTE_FAILURE_PERMANENT,
                );
                self.settle_post_accept_admission_failure(
                    &task_id,
                    &child_connection_id,
                    child_conversation_id,
                    agent_type,
                    &parent_connection_id,
                    continued_from_task_id.as_deref(),
                    generation,
                    admission_class,
                    inflight_id,
                    runtime,
                    crate::acp::delegation::metrics::ADMISSION_FAILED_CODE,
                    message,
                    meta,
                    failure_class,
                    None,
                )
                .await
            }
        }
    }

    /// Settlement ownership protocol for post-accept admission/budget failures.
    ///
    /// Does **not** use the `settle_task` PE-rewrite arm. Cancel failure is
    /// logged and non-blocking. Coordination is released only after Won /
    /// Existing / owned retry (or frozen ownership on permanent miss).
    #[allow(clippy::too_many_arguments)]
    async fn settle_post_accept_admission_failure(
        &self,
        task_id: &str,
        child_connection_id: &str,
        child_conversation_id: i32,
        agent_type: AgentType,
        parent_connection_id: &str,
        continued_from_task_id: Option<&str>,
        generation: i64,
        admission_class: AdmissionClass,
        inflight_id: Option<u64>,
        runtime: Option<Arc<LiveRuntimeState>>,
        intended_code: &'static str,
        message: String,
        meta: PromoteAttemptMeta,
        failure_class: &'static str,
        retry_class: Option<&'static str>,
    ) -> PostAcceptPromoteResult {
        // Secret-free structured failure log (no free-form promote message / DbErr).
        crate::acp::delegation::metrics::emit_promote_structured_log(
            tracing::Level::ERROR,
            "[delegation] post-accept promote failure; settling intended terminal",
            task_id,
            generation,
            agent_type,
            &admission_class,
            meta.attempts,
            meta.last_sqlite_primary,
            meta.last_sqlite_extended,
            failure_class,
            Some(intended_code),
            false,
        );
        if let Some(retry_class) = retry_class {
            tracing::error!(
                target: "codeg::delegation",
                task_id = %task_id,
                generation,
                agent_type = crate::acp::delegation::metrics::agent_type_label(agent_type),
                admission_class = ?admission_class,
                attempt = meta.attempts,
                failure_class,
                retry_class,
                intended_code,
                "[delegation] post-accept promote failure retry class"
            );
        }

        // Stable parent-facing message (no prompt/secrets; no raw SQLite dump).
        let wire_message = match intended_code {
            crate::acp::delegation::metrics::BUDGET_EXHAUSTED_CODE => message,
            _ => format!("delegation admission failed after prompt accept ({failure_class})"),
        };
        let outcome = DelegationOutcome::Err {
            code: intended_code.to_string(),
            message: wire_message.clone(),
            child_conversation_id: Some(child_conversation_id),
        };
        let observed_at = Utc::now();
        let observed = observed_terminal_from_outcome(
            outcome.clone(),
            termination_audit(
                AcpTerminationSource::Admission,
                AcpTerminationReason::AdmissionFailed,
                AcpTerminationClassification::Unexpected,
                DelegationRunStatus::Reserving,
                true,
                None,
                observed_at,
            ),
            observed_at,
        );
        let terminal = observed.terminal.clone();

        // 1) Claim local first-terminal disposition (insert-if-absent).
        // On Occupied: report from existing TerminalIntent / durable truth —
        // never the losing promote classification (FWW).
        let claim_won = {
            use std::collections::hash_map::Entry;
            let mut inner = self.pending.inner.lock().await;
            match inner.closed_handoff_dispositions.entry(task_id.to_string()) {
                Entry::Occupied(existing) => {
                    let owner_intent = TerminalIntent {
                        disposition: existing.get().clone(),
                        completed: inner.completed.get(task_id).cloned(),
                    };
                    drop(inner);
                    if let Err(e) = self.spawner.cancel(child_connection_id).await {
                        tracing::warn!(
                            task_id = %task_id,
                            error = %e,
                            "[delegation] post-accept lost-claim cancel failed (non-blocking)"
                        );
                    }
                    let _ = self.spawner.disconnect(child_connection_id).await;
                    self.post_accept_release_coordination(
                        task_id,
                        child_connection_id,
                        inflight_id,
                        runtime.as_ref(),
                    )
                    .await;
                    // Prefer durable terminal when present; else owner intent.
                    let mut report = if let Ok(Some(task)) = self.task_store.load(task_id).await {
                        if task.status != TaskStatus::Running {
                            task.to_report(None)
                        } else {
                            owner_intent.to_report(
                                task_id,
                                agent_type,
                                child_conversation_id,
                                continued_from_task_id,
                            )
                        }
                    } else {
                        owner_intent.to_report(
                            task_id,
                            agent_type,
                            child_conversation_id,
                            continued_from_task_id,
                        )
                    };
                    report.task_id = Some(task_id.to_string());
                    report.agent_type = Some(agent_type);
                    report.child_conversation_id = Some(child_conversation_id);
                    if let Some(from) = continued_from_task_id {
                        report.continued_from_task_id = Some(from.to_string());
                    }
                    tracing::info!(
                        task_id = %task_id,
                        generation,
                        agent_type = ?agent_type,
                        admission_class = ?admission_class,
                        attempt = meta.attempts,
                        owner_code = ?report.error_code,
                        intended_code,
                        failure_class,
                        "[delegation] post-accept lost first-terminal claim; report owner"
                    );
                    return PostAcceptPromoteResult::Failed(report);
                }
                Entry::Vacant(slot) => {
                    slot.insert(ReservingHandoffDisposition::ChildTerminal(observed.clone()));
                    true
                }
            }
        };
        debug_assert!(claim_won);
        let _ = claim_won;
        self.bump_status_version();
        self.result_notify.notify_waiters();

        // 2) Cancel accepted child prompt — failure is non-blocking.
        if let Err(e) = self.spawner.cancel(child_connection_id).await {
            tracing::warn!(
                task_id = %task_id,
                error = %e,
                "[delegation] post-accept admission cancel failed (non-blocking)"
            );
        }

        let accounting = PersistenceRetryAccounting {
            parent_connection_id: parent_connection_id.to_string(),
            agent_type,
            child_conversation_id,
            duration_ms: 0,
        };

        // 3) put_retry with **intended** terminal before settle (bootstrap-style).
        // Different existing payload → adopt FWW owner (do not overwrite) and
        // align local disposition so continue_abort cannot override with stale
        // admission code.
        // Effective single-flight ownership for settlement-retry metrics.
        // Starts as the initial put result; reacquire/forced-put upgrade it to
        // true when this caller becomes the new owner after the first put lost.
        let mut settlement_retry_owner = self
            .task_store
            .put_retry(PendingTerminalRetry {
                task_id: task_id.to_string(),
                terminal: terminal.clone(),
                child_conversation_id,
                frozen: false,
            })
            .await;
        if !settlement_retry_owner {
            // Observe existing owner (clone). Must recheck under fence before
            // any disposition alignment — worker may settle Existing, clear
            // park, install overlay, and remove_retry while we hold a stale clone.
            let _observed = self.task_store.get_retry(task_id).await;
            #[cfg(any(test, feature = "test-utils"))]
            {
                LiveRuntimeState::honor_gate(&self.post_accept_adopt_retry_recheck_gate).await;
            }

            // Bounded re-resolve: durable terminal, live retry (adopt), or
            // reacquire intended ownership. Never release coordination while
            // durable is unknown/non-terminal and no retry/freeze owner exists.
            const RECHECK_REACQUIRE_ATTEMPTS: u32 = 8;
            let mut reacquired_intended = false;
            for attempt in 0..RECHECK_REACQUIRE_ATTEMPTS {
                // Fence: durable terminal wins unconditionally — never reinsert
                // process-local state from a stale retry clone.
                match self.task_store.load(task_id).await {
                    Ok(Some(task)) if task.status != TaskStatus::Running => {
                        let _ = self.spawner.disconnect(child_connection_id).await;
                        self.post_accept_release_coordination(
                            task_id,
                            child_connection_id,
                            inflight_id,
                            runtime.as_ref(),
                        )
                        .await;
                        let mut report = task.to_report(None);
                        report.task_id = Some(task_id.to_string());
                        report.agent_type = Some(agent_type);
                        report.child_conversation_id = Some(child_conversation_id);
                        if let Some(from) = continued_from_task_id {
                            report.continued_from_task_id = Some(from.to_string());
                        }
                        tracing::info!(
                            task_id = %task_id,
                            generation,
                            agent_type = ?agent_type,
                            admission_class = ?admission_class,
                            attempt = meta.attempts,
                            recheck_attempt = attempt,
                            error_code = ?report.error_code,
                            status = ?report.status,
                            intended_code,
                            sqlite_primary = meta.last_sqlite_primary,
                            sqlite_extended = meta.last_sqlite_extended,
                            failure_class,
                            "[delegation] post-accept adopt recheck: durable terminal wins (no stale align)"
                        );
                        return PostAcceptPromoteResult::Failed(report);
                    }
                    Ok(Some(_)) | Ok(None) => {
                        // Non-terminal or missing durable row — reacquire path.
                    }
                    Err(load_err) => {
                        // Error-aware: load failure is not durable terminal truth.
                        // Must reacquire settle/retry/freeze ownership before release.
                        tracing::warn!(
                            task_id = %task_id,
                            generation,
                            agent_type = ?agent_type,
                            admission_class = ?admission_class,
                            attempt = meta.attempts,
                            recheck_attempt = attempt,
                            intended_code,
                            error = %load_err,
                            sqlite_primary = meta.last_sqlite_primary,
                            sqlite_extended = meta.last_sqlite_extended,
                            failure_class,
                            "[delegation] post-accept adopt recheck: durable load failed; reacquire ownership"
                        );
                    }
                }

                // Fresh retry ownership after durable recheck.
                if let Some(existing) = self.task_store.get_retry(task_id).await {
                    let adopted_outcome = outcome_from_terminal_write(
                        &existing.terminal,
                        agent_type,
                        child_conversation_id,
                    );
                    let adopted_observed = ObservedTerminal {
                        outcome: adopted_outcome.clone(),
                        terminal: existing.terminal.clone(),
                        result_text: None,
                    };
                    // Align disposition + overlay from the **full** TerminalTaskWrite
                    // only while retry ownership is still live and finalize has not
                    // already installed a terminal overlay. Do not invent
                    // admission_failed when error_code is None (Completed owners).
                    let skip_align_for_overlay = {
                        let mut inner = self.pending.inner.lock().await;
                        let overlay_terminal = inner.completed.get(task_id).is_some_and(|c| {
                            matches!(
                                c.status,
                                TaskStatus::Completed | TaskStatus::Failed | TaskStatus::Canceled
                            )
                        });
                        if overlay_terminal {
                            true
                        } else {
                            inner.closed_handoff_dispositions.insert(
                                task_id.to_string(),
                                ReservingHandoffDisposition::ChildTerminal(adopted_observed),
                            );
                            let completed = build_completed(
                                parent_connection_id,
                                child_conversation_id,
                                agent_type,
                                0,
                                &adopted_outcome,
                            );
                            inner.insert_completed(task_id, completed);
                            false
                        }
                    };
                    tracing::info!(
                        task_id = %task_id,
                        generation,
                        agent_type = ?agent_type,
                        admission_class = ?admission_class,
                        attempt = meta.attempts,
                        recheck_attempt = attempt,
                        existing_code = ?existing.terminal.error_code,
                        existing_status = ?existing.terminal.status,
                        skip_align_for_overlay,
                        intended_code,
                        sqlite_primary = meta.last_sqlite_primary,
                        sqlite_extended = meta.last_sqlite_extended,
                        failure_class,
                        "[delegation] post-accept adopt existing retry owner (FWW); disposition aligned"
                    );
                    if !existing.frozen {
                        self.spawn_persistence_retry_worker(
                            task_id.to_string(),
                            accounting.clone(),
                        )
                        .await;
                    }
                    let _ = self.spawner.disconnect(child_connection_id).await;
                    self.post_accept_release_coordination(
                        task_id,
                        child_connection_id,
                        inflight_id,
                        runtime.as_ref(),
                    )
                    .await;
                    // Prefer durable terminal if it raced in; else finalized overlay;
                    // else full TerminalTaskWrite payload.
                    let mut report = if let Ok(Some(task)) = self.task_store.load(task_id).await {
                        if task.status != TaskStatus::Running {
                            task.to_report(None)
                        } else if skip_align_for_overlay {
                            let overlay = {
                                let inner = self.pending.inner.lock().await;
                                inner.completed.get(task_id).cloned()
                            };
                            overlay
                                .map(|c| completed_report(task_id, &c))
                                .unwrap_or_else(|| {
                                    report_from_terminal_write(
                                        task_id,
                                        agent_type,
                                        child_conversation_id,
                                        &existing.terminal,
                                        continued_from_task_id,
                                    )
                                })
                        } else {
                            report_from_terminal_write(
                                task_id,
                                agent_type,
                                child_conversation_id,
                                &existing.terminal,
                                continued_from_task_id,
                            )
                        }
                    } else {
                        report_from_terminal_write(
                            task_id,
                            agent_type,
                            child_conversation_id,
                            &existing.terminal,
                            continued_from_task_id,
                        )
                    };
                    report.task_id = Some(task_id.to_string());
                    report.agent_type = Some(agent_type);
                    report.child_conversation_id = Some(child_conversation_id);
                    if let Some(from) = continued_from_task_id {
                        report.continued_from_task_id = Some(from.to_string());
                    }
                    return PostAcceptPromoteResult::Failed(report);
                }

                // Retry gone + durable non-terminal/unknown: reacquire intended
                // settlement ownership before any coordination release.
                let claimed = self
                    .task_store
                    .put_retry(PendingTerminalRetry {
                        task_id: task_id.to_string(),
                        terminal: terminal.clone(),
                        child_conversation_id,
                        frozen: false,
                    })
                    .await;
                if claimed {
                    reacquired_intended = true;
                    // This caller is now the new single-flight owner.
                    settlement_retry_owner = true;
                    tracing::info!(
                        task_id = %task_id,
                        generation,
                        agent_type = ?agent_type,
                        admission_class = ?admission_class,
                        attempt = meta.attempts,
                        recheck_attempt = attempt,
                        intended_code,
                        sqlite_primary = meta.last_sqlite_primary,
                        sqlite_extended = meta.last_sqlite_extended,
                        failure_class,
                        "[delegation] post-accept adopt recheck: reacquired intended retry ownership"
                    );
                    break;
                }
                // Concurrent put/remove race — yield and re-resolve.
                tokio::task::yield_now().await;
            }

            if !reacquired_intended {
                // Pathological reacquire races only: force intended put so settle
                // / transient worker / permanent freeze always have an owner.
                // Never release coordination from this branch without ownership.
                tracing::error!(
                    task_id = %task_id,
                    generation,
                    agent_type = ?agent_type,
                    admission_class = ?admission_class,
                    attempt = meta.attempts,
                    intended_code,
                    sqlite_primary = meta.last_sqlite_primary,
                    sqlite_extended = meta.last_sqlite_extended,
                    failure_class,
                    "[delegation] post-accept reacquire exhaust; forcing intended put before settle"
                );
                match self.task_store.load(task_id).await {
                    Ok(Some(task)) if task.status != TaskStatus::Running => {
                        let _ = self.spawner.disconnect(child_connection_id).await;
                        self.post_accept_release_coordination(
                            task_id,
                            child_connection_id,
                            inflight_id,
                            runtime.as_ref(),
                        )
                        .await;
                        let mut report = task.to_report(None);
                        report.task_id = Some(task_id.to_string());
                        report.agent_type = Some(agent_type);
                        report.child_conversation_id = Some(child_conversation_id);
                        if let Some(from) = continued_from_task_id {
                            report.continued_from_task_id = Some(from.to_string());
                        }
                        return PostAcceptPromoteResult::Failed(report);
                    }
                    Err(load_err) => {
                        tracing::warn!(
                            task_id = %task_id,
                            error = %load_err,
                            "[delegation] post-accept reacquire exhaust: durable load still failing"
                        );
                    }
                    _ => {}
                }
                if let Some(existing) = self.task_store.get_retry(task_id).await {
                    if !existing.frozen {
                        self.spawn_persistence_retry_worker(
                            task_id.to_string(),
                            accounting.clone(),
                        )
                        .await;
                    }
                    let _ = self.spawner.disconnect(child_connection_id).await;
                    self.post_accept_release_coordination(
                        task_id,
                        child_connection_id,
                        inflight_id,
                        runtime.as_ref(),
                    )
                    .await;
                    let mut report = report_from_terminal_write(
                        task_id,
                        agent_type,
                        child_conversation_id,
                        &existing.terminal,
                        continued_from_task_id,
                    );
                    report.task_id = Some(task_id.to_string());
                    report.agent_type = Some(agent_type);
                    report.child_conversation_id = Some(child_conversation_id);
                    if let Some(from) = continued_from_task_id {
                        report.continued_from_task_id = Some(from.to_string());
                    }
                    return PostAcceptPromoteResult::Failed(report);
                }
                let forced = self
                    .task_store
                    .put_retry(PendingTerminalRetry {
                        task_id: task_id.to_string(),
                        terminal: terminal.clone(),
                        child_conversation_id,
                        frozen: false,
                    })
                    .await;
                if forced {
                    settlement_retry_owner = true;
                } else {
                    // Occupied between check and put — adopt concurrent owner.
                    if let Some(existing) = self.task_store.get_retry(task_id).await {
                        if !existing.frozen {
                            self.spawn_persistence_retry_worker(
                                task_id.to_string(),
                                accounting.clone(),
                            )
                            .await;
                        }
                        let _ = self.spawner.disconnect(child_connection_id).await;
                        self.post_accept_release_coordination(
                            task_id,
                            child_connection_id,
                            inflight_id,
                            runtime.as_ref(),
                        )
                        .await;
                        let mut report = report_from_terminal_write(
                            task_id,
                            agent_type,
                            child_conversation_id,
                            &existing.terminal,
                            continued_from_task_id,
                        );
                        report.task_id = Some(task_id.to_string());
                        report.agent_type = Some(agent_type);
                        report.child_conversation_id = Some(child_conversation_id);
                        if let Some(from) = continued_from_task_id {
                            report.continued_from_task_id = Some(from.to_string());
                        }
                        return PostAcceptPromoteResult::Failed(report);
                    }
                    // Still vacant (extreme race): put once more for settle ownership.
                    if self
                        .task_store
                        .put_retry(PendingTerminalRetry {
                            task_id: task_id.to_string(),
                            terminal: terminal.clone(),
                            child_conversation_id,
                            frozen: false,
                        })
                        .await
                    {
                        settlement_retry_owner = true;
                    }
                }
            }
            // Fall through to settle_with_retry with intended ownership.
            // reacquired_intended is folded into settlement_retry_owner above.
            let _ = reacquired_intended;
        } else {
            tracing::info!(
                task_id = %task_id,
                generation,
                agent_type = ?agent_type,
                admission_class = ?admission_class,
                attempt = meta.attempts,
                intended_code,
                sqlite_primary = meta.last_sqlite_primary,
                sqlite_extended = meta.last_sqlite_extended,
                failure_class,
                "[delegation] post-accept retry ownership enqueued with intended terminal"
            );
        }

        // 4) Bounded settle with intended code (no PE rewrite).
        match self
            .settle_with_retry(task_id, terminal.clone(), None)
            .await
        {
            Ok((Settlement::Won(report), _)) => {
                self.finalize_durable_settlement(
                    task_id,
                    Settlement::Won(report.clone()),
                    Some(&accounting),
                    true,
                )
                .await;
                let _ = self.spawner.disconnect(child_connection_id).await;
                self.post_accept_release_coordination(
                    task_id,
                    child_connection_id,
                    inflight_id,
                    runtime.as_ref(),
                )
                .await;
                self.task_store.remove_retry(task_id).await;
                let mut report = report;
                report.task_id = Some(task_id.to_string());
                report.agent_type = Some(agent_type);
                report.child_conversation_id = Some(child_conversation_id);
                if report.error_code.is_none() {
                    report.error_code = Some(intended_code.to_string());
                }
                if report.message.is_none() {
                    report.message = Some(wire_message);
                }
                if let Some(from) = continued_from_task_id {
                    report.continued_from_task_id = Some(from.to_string());
                }
                // Terminal admission metric only for durable CAS winners whose
                // exact error_code is admission_failed (not budget, not losers).
                if report.error_code.as_deref()
                    == Some(crate::acp::delegation::metrics::ADMISSION_FAILED_CODE)
                {
                    self.metrics.record_admission_failed(agent_type);
                }
                tracing::info!(
                    task_id = %task_id,
                    generation,
                    agent_type = ?agent_type,
                    admission_class = ?admission_class,
                    attempt = meta.attempts,
                    error_code = ?report.error_code,
                    sqlite_primary = meta.last_sqlite_primary,
                    sqlite_extended = meta.last_sqlite_extended,
                    failure_class,
                    "[delegation] post-accept settlement durable Won"
                );
                PostAcceptPromoteResult::Failed(report)
            }
            Ok((Settlement::Existing(report), _)) => {
                self.finalize_durable_settlement(
                    task_id,
                    Settlement::Existing(report.clone()),
                    Some(&accounting),
                    false,
                )
                .await;
                let _ = self.spawner.disconnect(child_connection_id).await;
                self.post_accept_release_coordination(
                    task_id,
                    child_connection_id,
                    inflight_id,
                    runtime.as_ref(),
                )
                .await;
                self.task_store.remove_retry(task_id).await;
                let mut report = report;
                report.task_id = Some(task_id.to_string());
                report.agent_type = Some(agent_type);
                report.child_conversation_id = Some(child_conversation_id);
                if let Some(from) = continued_from_task_id {
                    report.continued_from_task_id = Some(from.to_string());
                }
                tracing::info!(
                    task_id = %task_id,
                    generation,
                    agent_type = ?agent_type,
                    admission_class = ?admission_class,
                    attempt = meta.attempts,
                    error_code = ?report.error_code,
                    sqlite_primary = meta.last_sqlite_primary,
                    sqlite_extended = meta.last_sqlite_extended,
                    failure_class,
                    "[delegation] post-accept settlement durable Existing (replay winner)"
                );
                // Replay durable winner identity/code (may differ from intended).
                PostAcceptPromoteResult::Failed(report)
            }
            Err(err) if err.is_transient() => {
                // Settlement loop exhausted → hand to retry owner.
                // Pairing: new owner (including reacquire/forced-put) increments
                // both counters; existing owner increments only exhausted.
                let _ = err; // do not log raw DbErr (paths/config may appear)
                self.metrics.record_settlement_retry_exhausted();
                if settlement_retry_owner {
                    self.metrics.record_settlement_retry_enqueued();
                }
                // Keep original terminal on PendingTerminalRetry; spawn worker.
                self.spawn_persistence_retry_worker(task_id.to_string(), accounting)
                    .await;
                let _ = self.spawner.disconnect(child_connection_id).await;
                self.post_accept_release_coordination(
                    task_id,
                    child_connection_id,
                    inflight_id,
                    runtime.as_ref(),
                )
                .await;
                crate::acp::delegation::metrics::emit_promote_structured_log(
                    tracing::Level::ERROR,
                    "[delegation] post-accept settlement transient exhaust; parked intended retry",
                    task_id,
                    generation,
                    agent_type,
                    &admission_class,
                    meta.attempts,
                    meta.last_sqlite_primary,
                    meta.last_sqlite_extended,
                    failure_class,
                    Some(intended_code),
                    settlement_retry_owner,
                );
                let mut report = report_from_outcome(
                    Some(task_id.to_string()),
                    Some(agent_type),
                    &outcome,
                    None,
                );
                if let Some(from) = continued_from_task_id {
                    report.continued_from_task_id = Some(from.to_string());
                }
                PostAcceptPromoteResult::Failed(report)
            }
            Err(err) => {
                // Permanent miss: freeze ownership with intended terminal; caller
                // gets sanitized persistence_error. Never release without freeze.
                let _ = err; // do not log raw DbErr (paths/config may appear)
                crate::acp::delegation::metrics::emit_promote_structured_log(
                    tracing::Level::ERROR,
                    "[delegation] post-accept settlement permanent failure; freeze ownership",
                    task_id,
                    generation,
                    agent_type,
                    &admission_class,
                    meta.attempts,
                    meta.last_sqlite_primary,
                    meta.last_sqlite_extended,
                    failure_class,
                    Some(intended_code),
                    settlement_retry_owner,
                );
                // Ensure intended retry record exists then freeze.
                let freeze_owned = self
                    .task_store
                    .put_retry(PendingTerminalRetry {
                        task_id: task_id.to_string(),
                        terminal: terminal.clone(),
                        child_conversation_id,
                        frozen: false,
                    })
                    .await;
                if freeze_owned {
                    settlement_retry_owner = true;
                }
                self.task_store.freeze_retry(task_id).await;
                // Exhaust always; enqueued only for a new ownership/freeze install.
                self.metrics.record_settlement_retry_exhausted();
                if settlement_retry_owner {
                    self.metrics.record_settlement_retry_enqueued();
                }
                match self
                    .finalize_permanent_persistence_failure(task_id, Some(&accounting), true)
                    .await
                {
                    PermanentPersistenceFinalize::DurableAlreadyTerminal { error_code } => {
                        let _ = self.spawner.disconnect(child_connection_id).await;
                        self.post_accept_release_coordination(
                            task_id,
                            child_connection_id,
                            inflight_id,
                            runtime.as_ref(),
                        )
                        .await;
                        let mut report = if let Ok(Some(task)) = self.task_store.load(task_id).await
                        {
                            task.to_report(None)
                        } else {
                            report_from_outcome(
                                Some(task_id.to_string()),
                                Some(agent_type),
                                &outcome,
                                None,
                            )
                        };
                        report.task_id = Some(task_id.to_string());
                        report.agent_type = Some(agent_type);
                        report.child_conversation_id = Some(child_conversation_id);
                        if report.error_code.is_none() {
                            report.error_code = error_code;
                        }
                        if let Some(from) = continued_from_task_id {
                            report.continued_from_task_id = Some(from.to_string());
                        }
                        PostAcceptPromoteResult::Failed(report)
                    }
                    PermanentPersistenceFinalize::AccountedAsPermanent => {
                        let _ = self.spawner.disconnect(child_connection_id).await;
                        self.post_accept_release_coordination(
                            task_id,
                            child_connection_id,
                            inflight_id,
                            runtime.as_ref(),
                        )
                        .await;
                        let pe = DelegationOutcome::Err {
                            code: "persistence_error".into(),
                            message: bootstrap_refuse_message(
                                BootstrapRefuseKind::PersistenceError,
                            ),
                            child_conversation_id: Some(child_conversation_id),
                        };
                        let mut report = report_from_outcome(
                            Some(task_id.to_string()),
                            Some(agent_type),
                            &pe,
                            None,
                        );
                        if let Some(from) = continued_from_task_id {
                            report.continued_from_task_id = Some(from.to_string());
                        }
                        PostAcceptPromoteResult::Failed(report)
                    }
                }
            }
        }
    }

    async fn post_accept_release_coordination(
        &self,
        task_id: &str,
        child_connection_id: &str,
        inflight_id: Option<u64>,
        runtime: Option<&Arc<LiveRuntimeState>>,
    ) {
        if let Some(runtime) = runtime {
            runtime.terminal.store(true, Ordering::Release);
        }
        let mut inner = self.pending.inner.lock().await;
        inner.unreserve(task_id, child_connection_id);
        inner.unregister_live_run(child_connection_id);
        inner.coordination_by_child.remove(child_connection_id);
        if let Some(id) = inflight_id {
            inner.deregister_inflight(id);
        }
    }

    /// Claim-first durable settle for ResumeExistingOnly bootstrap refusal
    /// (missing external id, resume/load RPC failure, returned-id mismatch).
    ///
    /// Process-local first-terminal claim under `pending.inner` decides bootstrap
    /// vs parent-end intent **before** any durable CAS. Callers pass the
    /// reserved `task_id` (and optional live child connection incarnation).
    /// On `Existing` / `PendingCompensation` / `PermanentPersistenceError` the
    /// caller must **not** call `settle_terminal` again.
    pub(crate) async fn settle_bootstrap_unresumable(
        &self,
        task_id: &str,
        child_connection_id: Option<&str>,
        message: impl Into<String>,
    ) -> BootstrapSettleResult {
        let raw_message = message.into();
        let stable_message = sanitize_bootstrap_unresumable_message(&raw_message);
        let outcome =
            DelegationOutcome::from_err(DelegationError::Unresumable(stable_message), None);
        let observed_at = Utc::now();
        let observed = observed_terminal_from_outcome(
            outcome.clone(),
            termination_audit(
                AcpTerminationSource::Session,
                AcpTerminationReason::SessionLost,
                AcpTerminationClassification::Unexpected,
                DelegationRunStatus::Reserving,
                false,
                None,
                observed_at,
            ),
            observed_at,
        );
        let terminal = observed.terminal.clone();

        // Test-only / no durable store: buffer admission-window outcome.
        if self.run_store.is_none() {
            let mut inner = self.pending.inner.lock().await;
            if let Some(conn) = child_connection_id {
                let _ = inner.buffer_admission_window_terminal(conn, observed.clone());
            }
            inner.buffer_early_complete(task_id, observed);
            return BootstrapSettleResult::Won;
        }

        // Durable already terminal (parent-end or prior child won): return
        // Existing without claiming or performing bootstrap CAS.
        if let Ok(Some(task)) = self.task_store.load(task_id).await {
            if task.status != TaskStatus::Running {
                let code = task.error_code.clone();
                let report = task.to_report(None);
                self.finalize_durable_settlement(
                    task_id,
                    Settlement::Existing(report),
                    None,
                    false,
                )
                .await;
                self.bootstrap_cleanup_after_durable(task_id, child_connection_id)
                    .await;
                return BootstrapSettleResult::Existing { error_code: code };
            }
        }

        let overlay_identity = self
            .resolve_bootstrap_overlay_identity(task_id, child_connection_id)
            .await;

        // §3.1 claim-before-CAS: insert-if-absent ChildTerminal under one lock.
        let claim_won = {
            use std::collections::hash_map::Entry;
            let mut inner = self.pending.inner.lock().await;
            match inner.closed_handoff_dispositions.entry(task_id.to_string()) {
                Entry::Occupied(existing) => {
                    let code = disposition_error_code(existing.get());
                    drop(inner);
                    return self
                        .bootstrap_return_existing(task_id, child_connection_id, code)
                        .await;
                }
                Entry::Vacant(slot) => {
                    slot.insert(ReservingHandoffDisposition::ChildTerminal(observed.clone()));
                    if let Some(ref id) = overlay_identity {
                        inner.insert_completed(
                            task_id,
                            build_completed(
                                &id.parent_connection_id,
                                id.child_conversation_id,
                                id.agent_type,
                                0,
                                &outcome,
                            ),
                        );
                    }
                    true
                }
            }
        };
        debug_assert!(claim_won);
        self.bump_status_version();
        self.result_notify.notify_waiters();

        let child_conversation_id = overlay_identity
            .as_ref()
            .map(|id| id.child_conversation_id)
            .unwrap_or(0);
        let accounting = PersistenceRetryAccounting {
            parent_connection_id: overlay_identity
                .as_ref()
                .map(|id| id.parent_connection_id.clone())
                .unwrap_or_default(),
            agent_type: overlay_identity
                .as_ref()
                .map(|id| id.agent_type)
                .unwrap_or(AgentType::ClaudeCode),
            child_conversation_id,
            duration_ms: 0,
        };

        // put_retry before settle/worker — single-flight ownership key.
        let retry_owned = self
            .task_store
            .put_retry(PendingTerminalRetry {
                task_id: task_id.to_string(),
                terminal: terminal.clone(),
                child_conversation_id,
                frozen: false,
            })
            .await;
        if !retry_owned {
            return self
                .bootstrap_return_existing(task_id, child_connection_id, None)
                .await;
        }

        match self
            .settle_with_retry(task_id, terminal.clone(), None)
            .await
        {
            Ok((Settlement::Won(report), _)) => {
                self.finalize_durable_settlement(
                    task_id,
                    Settlement::Won(report),
                    Some(&accounting),
                    true,
                )
                .await;
                self.bootstrap_cleanup_after_durable(task_id, child_connection_id)
                    .await;
                tracing::info!(
                    task_id = %task_id,
                    child_connection_id = ?child_connection_id,
                    "[delegation] settle_bootstrap_unresumable: durable failed/unresumable"
                );
                BootstrapSettleResult::Won
            }
            Ok((Settlement::Existing(report), _)) => {
                let code = report.error_code.clone();
                self.finalize_durable_settlement(
                    task_id,
                    Settlement::Existing(report),
                    Some(&accounting),
                    false,
                )
                .await;
                self.bootstrap_cleanup_after_durable(task_id, child_connection_id)
                    .await;
                tracing::info!(
                    task_id = %task_id,
                    existing_code = ?code,
                    "[delegation] settle_bootstrap_unresumable: already terminal"
                );
                BootstrapSettleResult::Existing { error_code: code }
            }
            Err(err) if err.is_transient() => {
                // Keep claim + overlay + original retry payload; spawn worker.
                self.spawn_persistence_retry_worker(task_id.to_string(), accounting)
                    .await;
                self.bootstrap_unregister_live_only(task_id, child_connection_id)
                    .await;
                tracing::error!(
                    task_id = %task_id,
                    error = %err,
                    "[delegation] settle_bootstrap_unresumable: transient exhaustion; parked"
                );
                BootstrapSettleResult::PendingCompensation
            }
            Err(err) => {
                // Permanent: re-read durable first; if a concurrent CAS already
                // won a different code, finalize Existing (no PE account).
                tracing::error!(
                    task_id = %task_id,
                    error = %err,
                    "[delegation] settle_bootstrap_unresumable: permanent persist failure"
                );
                match self
                    .finalize_permanent_persistence_failure(task_id, Some(&accounting), true)
                    .await
                {
                    PermanentPersistenceFinalize::DurableAlreadyTerminal { error_code } => {
                        self.bootstrap_cleanup_after_durable(task_id, child_connection_id)
                            .await;
                        BootstrapSettleResult::Existing { error_code }
                    }
                    PermanentPersistenceFinalize::AccountedAsPermanent => {
                        self.bootstrap_unregister_live_only(task_id, child_connection_id)
                            .await;
                        BootstrapSettleResult::PermanentPersistenceError
                    }
                }
            }
        }
    }

    async fn resolve_bootstrap_overlay_identity(
        &self,
        task_id: &str,
        child_connection_id: Option<&str>,
    ) -> Option<BootstrapOverlayIdentity> {
        let from_pending = {
            let inner = self.pending.inner.lock().await;
            let coord = child_connection_id
                .and_then(|conn| inner.coordination_by_child.get(conn))
                .or_else(|| {
                    inner
                        .coordination_by_child
                        .values()
                        .find(|c| c.task_id == task_id)
                });
            coord.map(|coord| {
                (
                    coord.parent_connection_id.clone(),
                    coord.run_registration.child_conversation_id,
                )
            })
        };
        if let Some((parent_connection_id, child_conversation_id)) = from_pending {
            let agent_type = if let Some(runs) = self.run_store.as_ref() {
                runs.load_by_task_id(task_id)
                    .await
                    .ok()
                    .flatten()
                    .map(|run| run.agent_type)
                    .unwrap_or(AgentType::ClaudeCode)
            } else {
                AgentType::ClaudeCode
            };
            return Some(BootstrapOverlayIdentity {
                parent_connection_id,
                child_conversation_id,
                agent_type,
            });
        }
        if let Some(runs) = self.run_store.as_ref() {
            if let Ok(Some(run)) = runs.load_by_task_id(task_id).await {
                return Some(BootstrapOverlayIdentity {
                    parent_connection_id: String::new(),
                    child_conversation_id: run.child_conversation_id,
                    agent_type: run.agent_type,
                });
            }
        }
        None
    }

    /// Lost claim / durable Existing path: replace overlay with winner when known;
    /// never attempt bootstrap CAS.
    async fn bootstrap_return_existing(
        &self,
        task_id: &str,
        child_connection_id: Option<&str>,
        claimed_code: Option<String>,
    ) -> BootstrapSettleResult {
        // Prefer durable winner when present.
        if let Ok(Some(task)) = self.task_store.load(task_id).await {
            if task.status != TaskStatus::Running {
                let report = task.to_report(None);
                self.finalize_durable_settlement(
                    task_id,
                    Settlement::Existing(report.clone()),
                    None,
                    false,
                )
                .await;
                self.bootstrap_cleanup_after_durable(task_id, child_connection_id)
                    .await;
                return BootstrapSettleResult::Existing {
                    error_code: report.error_code,
                };
            }
        }
        let code = {
            let inner = self.pending.inner.lock().await;
            claimed_code.or_else(|| {
                inner
                    .closed_handoff_dispositions
                    .get(task_id)
                    .and_then(disposition_error_code)
            })
        };
        self.bootstrap_unregister_live_only(task_id, child_connection_id)
            .await;
        BootstrapSettleResult::Existing { error_code: code }
    }

    /// Permanent store failure after a business refuse / retry payload is known:
    /// same-owner upgrade park+overlay to sanitized `persistence_error`, freeze
    /// the retry record, optionally count logical `persistence_error` once.
    ///
    /// Claim selection is serialized with parent-end durable CAS under
    /// `pending.inner`: permanent holds `permanent_pe_claim` from park upgrade
    /// through durable re-read + PE account; parent-end marks `durable_cas_claim`
    /// immediately before CAS. Permanent never accounts PE when durable is
    /// already any terminal after re-read.
    async fn finalize_permanent_persistence_failure(
        &self,
        task_id: &str,
        accounting: Option<&PersistenceRetryAccounting>,
        record_metrics: bool,
    ) -> PermanentPersistenceFinalize {
        // Fast path: durable already won before PE finalize starts.
        if let Some(done) = self.finalize_if_durable_terminal(task_id, accounting).await {
            return done;
        }

        // Wait out any in-flight parent-end CAS selection before taking PE claim.
        self.wait_out_durable_cas_claim(task_id).await;
        if let Some(done) = self.finalize_if_durable_terminal(task_id, accounting).await {
            return done;
        }

        let persistence_message = bootstrap_refuse_message(BootstrapRefuseKind::PersistenceError);
        let retry_evidence = self
            .task_store
            .get_retry(task_id)
            .await
            .and_then(|retry| retry.terminal.termination_evidence().cloned());
        let prior_status = retry_evidence
            .as_ref()
            .map(|audit| audit.prior_status.clone())
            .unwrap_or(DelegationRunStatus::Running);
        let prompt_may_have_executed = retry_evidence
            .as_ref()
            .is_some_and(|audit| audit.termination.prompt_may_have_executed);
        let persistence_observed = persistence_error_observation(
            prior_status,
            prompt_may_have_executed,
            Utc::now(),
            accounting.map(|a| a.child_conversation_id),
        );

        // Critical section: durable_cas free → take permanent_pe_claim, park,
        // re-read durable, (optionally test-gate), re-check durable + claim fence.
        let should_record = {
            let mut inner = self.pending.inner.lock().await;
            while inner.durable_cas_claim.contains(task_id) {
                drop(inner);
                self.wait_out_durable_cas_claim(task_id).await;
                if let Some(done) = self.finalize_if_durable_terminal(task_id, accounting).await {
                    return done;
                }
                inner = self.pending.inner.lock().await;
            }

            // Own PE claim selection for park → re-read → account.
            inner.begin_permanent_pe_claim(task_id);

            // Re-read durable under PE claim ownership (may await while holding
            // the mutex — rare permanent path; serializes disposition readers).
            if let Ok(Some(task)) = self.task_store.load(task_id).await {
                if task.status != TaskStatus::Running {
                    let error_code = task.error_code.clone();
                    let report = task.to_report(None);
                    inner.end_permanent_pe_claim(task_id);
                    drop(inner);
                    self.finalize_durable_settlement(
                        task_id,
                        Settlement::Existing(report),
                        accounting,
                        false,
                    )
                    .await;
                    return PermanentPersistenceFinalize::DurableAlreadyTerminal { error_code };
                }
            }

            // Same-owner compare-and-replace: only replace our ChildTerminal
            // bootstrap/persistence/admission claim (never overwrite ParentEnded).
            // Task 4: admission_failed / budget_exhausted are same-owner intended
            // payloads alongside unresumable / persistence_error.
            let is_same_owner = matches!(
                inner.closed_handoff_dispositions.get(task_id),
                Some(ReservingHandoffDisposition::ChildTerminal(ObservedTerminal {
                    outcome: DelegationOutcome::Err { code, .. },
                    ..
                })) if is_same_owner_intended_error_code(code)
            );
            if is_same_owner {
                inner.closed_handoff_dispositions.insert(
                    task_id.to_string(),
                    ReservingHandoffDisposition::ChildTerminal(persistence_observed.clone()),
                );
            }
            // Upgrade process-local overlay when it is our business refuse or
            // already persistence_error (status peeks during permanent park).
            let upgrade_overlay = is_same_owner
                || inner.completed.get(task_id).is_some_and(|c| {
                    c.error_code
                        .as_deref()
                        .is_some_and(is_same_owner_intended_error_code)
                });
            if upgrade_overlay {
                if let Some(acc) = accounting {
                    let (parent_connection_id, child_conversation_id, agent_type, duration_ms) =
                        if let Some(existing) = inner.completed.get(task_id) {
                            (
                                existing.parent_connection_id.clone(),
                                existing.child_conversation_id,
                                existing.agent_type,
                                existing.duration_ms,
                            )
                        } else {
                            (
                                acc.parent_connection_id.clone(),
                                acc.child_conversation_id,
                                acc.agent_type,
                                acc.duration_ms,
                            )
                        };
                    inner.insert_completed(
                        task_id,
                        CompletedTask {
                            parent_connection_id,
                            child_conversation_id,
                            agent_type,
                            status: TaskStatus::Failed,
                            text: None,
                            error_code: Some("persistence_error".into()),
                            message: Some(persistence_message.clone()),
                            duration_ms,
                        },
                    );
                }
            }

            // Second durable re-read under the same PE claim ownership.
            if let Ok(Some(task)) = self.task_store.load(task_id).await {
                if task.status != TaskStatus::Running {
                    let error_code = task.error_code.clone();
                    let report = task.to_report(None);
                    inner.end_permanent_pe_claim(task_id);
                    drop(inner);
                    self.finalize_durable_settlement(
                        task_id,
                        Settlement::Existing(report),
                        accounting,
                        false,
                    )
                    .await;
                    return PermanentPersistenceFinalize::DurableAlreadyTerminal { error_code };
                }
            }

            // Test-only: release the mutex (PE claim remains) so parent-end can
            // win durable CAS after permanent's second load, then re-check.
            #[cfg(any(test, feature = "test-utils"))]
            {
                let gate = self.permanent_pe_post_reread_gate.lock().await.take();
                if let Some(mut gate) = gate {
                    drop(inner);
                    if let Some(tx) = gate.entered.take() {
                        let _ = tx.send(());
                    }
                    if let Some(rx) = gate.release.take() {
                        let _ = rx.await;
                    }
                    // Parent-end may have claimed durable CAS and/or won.
                    self.wait_out_durable_cas_claim(task_id).await;
                    if let Some(done) = self.finalize_if_durable_terminal(task_id, accounting).await
                    {
                        let mut inner = self.pending.inner.lock().await;
                        inner.end_permanent_pe_claim(task_id);
                        return done;
                    }
                    inner = self.pending.inner.lock().await;
                    while inner.durable_cas_claim.contains(task_id) {
                        drop(inner);
                        self.wait_out_durable_cas_claim(task_id).await;
                        if let Some(done) =
                            self.finalize_if_durable_terminal(task_id, accounting).await
                        {
                            let mut inner = self.pending.inner.lock().await;
                            inner.end_permanent_pe_claim(task_id);
                            return done;
                        }
                        inner = self.pending.inner.lock().await;
                    }
                    // Third re-read after the staged race window.
                    if let Ok(Some(task)) = self.task_store.load(task_id).await {
                        if task.status != TaskStatus::Running {
                            let error_code = task.error_code.clone();
                            let report = task.to_report(None);
                            inner.end_permanent_pe_claim(task_id);
                            drop(inner);
                            self.finalize_durable_settlement(
                                task_id,
                                Settlement::Existing(report),
                                accounting,
                                false,
                            )
                            .await;
                            return PermanentPersistenceFinalize::DurableAlreadyTerminal {
                                error_code,
                            };
                        }
                    }
                }
            }

            // Account PE only while still owning claim selection and durable
            // remains non-terminal. Fence claim is under the same critical
            // section as the post-race re-read decision.
            let should_record = if record_metrics {
                inner.claim_terminal_metrics_accounted(task_id)
            } else {
                false
            };
            inner.end_permanent_pe_claim(task_id);
            should_record
        };

        // Preserve the same producer-authored persistence payload in the park
        // and frozen retry record (no worker spin).
        self.task_store
            .replace_retry_and_freeze(task_id, persistence_observed.terminal.clone())
            .await;
        if should_record {
            // Once-only: parent-end may later durable-win the parked
            // ChildTerminal(persistence_error) and must not re-count.
            let duration_ms = accounting.map(|a| a.duration_ms).unwrap_or(0);
            self.metrics.record_terminal(
                TaskStatus::Failed,
                std::time::Duration::from_millis(duration_ms),
            );
            if let Some(acc) = accounting {
                crate::acp::delegation::metrics::DelegationAuditRecord::task_transition(
                    &acc.parent_connection_id,
                    None,
                    acc.agent_type,
                    task_id,
                    Some(acc.child_conversation_id).filter(|id| *id != 0),
                    TaskStatus::Failed,
                    Some("persistence_error"),
                    Some(duration_ms),
                    Some(true),
                )
                .emit_task_transition();
            }
        }
        self.bump_status_version();
        self.result_notify.notify_waiters();
        PermanentPersistenceFinalize::AccountedAsPermanent
    }

    /// If durable is already terminal, finalize Existing (no PE account).
    async fn finalize_if_durable_terminal(
        &self,
        task_id: &str,
        accounting: Option<&PersistenceRetryAccounting>,
    ) -> Option<PermanentPersistenceFinalize> {
        if let Ok(Some(task)) = self.task_store.load(task_id).await {
            if task.status != TaskStatus::Running {
                let error_code = task.error_code.clone();
                let report = task.to_report(None);
                self.finalize_durable_settlement(
                    task_id,
                    Settlement::Existing(report),
                    accounting,
                    false,
                )
                .await;
                return Some(PermanentPersistenceFinalize::DurableAlreadyTerminal { error_code });
            }
        }
        None
    }

    /// Spin until parent-end releases durable CAS claim selection for `task_id`.
    async fn wait_out_durable_cas_claim(&self, task_id: &str) {
        loop {
            {
                let inner = self.pending.inner.lock().await;
                if !inner.durable_cas_claim.contains(task_id) {
                    return;
                }
            }
            tokio::task::yield_now().await;
        }
    }

    /// Re-read latest disposition under lock, take **exclusive** durable CAS
    /// claim ownership, and build the terminal write. Waits if permanent PE
    /// finalize still owns claim selection and PE has not been upgraded yet
    /// (avoids stale unresumable CAS). When PE is already upgraded, proceeds
    /// with PE. A second concurrent parent-end that loses exclusive insert
    /// waits for the owner to finish, then re-reads disposition.
    ///
    /// Re-reads use [`PendingInner::resolve_terminal_intent`] only — no ad-hoc
    /// `closed_handoff_dispositions` peeks (spec §3.3 single resolver).
    async fn take_parent_end_cas_selection(
        &self,
        task_id: &str,
        fallback: ReservingHandoffDisposition,
        prior_status: DelegationRunStatus,
    ) -> (ReservingHandoffDisposition, TerminalTaskWrite) {
        loop {
            let mut inner = self.pending.inner.lock().await;
            let disposition = inner
                .resolve_terminal_intent(task_id)
                .map(|intent| intent.disposition)
                .unwrap_or_else(|| fallback.clone());
            if inner.permanent_pe_claim.contains(task_id)
                && !PendingInner::disposition_is_persistence_error(&disposition)
            {
                // Permanent owns finalize and has not upgraded park to PE yet —
                // do not CAS a stale pre-PE code. Wait for park upgrade or PE
                // claim release.
                drop(inner);
                tokio::task::yield_now().await;
                continue;
            }
            // Exclusive ownership: second parent-end must not select/CAS while
            // another owner still holds the claim through CAS + finalize.
            if !inner.begin_durable_cas_claim(task_id) {
                drop(inner);
                self.wait_out_durable_cas_claim(task_id).await;
                continue;
            }
            // Test-only: hold while exclusive claim is owned so concurrent
            // parent-end / PE can observe wait-for-owner behavior.
            #[cfg(any(test, feature = "test-utils"))]
            {
                let gate = self.durable_cas_claim_held_gate.lock().await.take();
                if let Some(mut gate) = gate {
                    drop(inner);
                    if let Some(tx) = gate.entered.take() {
                        let _ = tx.send(());
                    }
                    if let Some(rx) = gate.release.take() {
                        let _ = rx.await;
                    }
                    // Re-read via shared resolver after the staged hold (owner
                    // still holds exclusive claim; PE cannot upgrade until release).
                    inner = self.pending.inner.lock().await;
                    let disposition = inner
                        .resolve_terminal_intent(task_id)
                        .map(|intent| intent.disposition)
                        .unwrap_or_else(|| fallback.clone());
                    let terminal =
                        terminal_from_handoff_disposition(&disposition, prior_status.clone());
                    return (disposition, terminal);
                }
            }
            let terminal = terminal_from_handoff_disposition(&disposition, prior_status.clone());
            return (disposition, terminal);
        }
    }

    async fn release_durable_cas_claim(&self, task_id: &str) {
        let mut inner = self.pending.inner.lock().await;
        inner.end_durable_cas_claim(task_id);
    }

    /// Single metric/audit site for durable terminal finalization (bootstrap Won,
    /// parent-end Won of claimed terminal, worker Won). `Existing` replaces
    /// overlay/disposition without counting again — including durable
    /// [`TaskStatus::Completed`] winners that carry no `error_code`.
    ///
    /// Callers that already copied payload status/code (worker) should pass a
    /// settlement already aligned via [`align_won_settlement_to_payload`] so
    /// metrics/audit/overlay use those codes.
    async fn finalize_durable_settlement(
        &self,
        task_id: &str,
        settlement: Settlement,
        accounting: Option<&PersistenceRetryAccounting>,
        record_won_metrics: bool,
    ) {
        match settlement {
            Settlement::Won(report) => {
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.clear_closed_handoff_disposition(task_id);
                    // Keep/refresh overlay so status/report peeks stay coherent.
                    if let Some(acc) = accounting {
                        let outcome = report_to_outcome_for_meta(
                            &report,
                            &SettleContext {
                                parent_connection_id: acc.parent_connection_id.clone(),
                                parent_tool_use_id: String::new(),
                                child_connection_id: String::new(),
                                child_conversation_id: acc.child_conversation_id,
                                agent_type: acc.agent_type,
                                task_preview: String::new(),
                                duration_ms: acc.duration_ms,
                                cancel_turn: false,
                                disconnect_on_loss: false,
                                message: report.message.clone(),
                                attention_resolution: AttentionResolutionCode::TaskTerminal,
                                runtime: None,
                                card_summary: None,
                                completion_input: None,
                            },
                        );
                        inner.insert_completed(
                            task_id,
                            build_completed(
                                &acc.parent_connection_id,
                                acc.child_conversation_id,
                                acc.agent_type,
                                acc.duration_ms,
                                &outcome,
                            ),
                        );
                    }
                }
                self.task_store.remove_retry(task_id).await;
                if record_won_metrics {
                    if let Some(acc) = accounting {
                        // Skip if permanent/bootstrap already counted this terminal.
                        let should_record = {
                            let mut inner = self.pending.inner.lock().await;
                            inner.claim_terminal_metrics_accounted(task_id)
                        };
                        if should_record {
                            self.metrics.record_terminal(
                                report.status,
                                std::time::Duration::from_millis(acc.duration_ms),
                            );
                            crate::acp::delegation::metrics::DelegationAuditRecord::task_transition(
                                &acc.parent_connection_id,
                                None,
                                acc.agent_type,
                                task_id,
                                Some(acc.child_conversation_id).filter(|id| *id != 0),
                                report.status,
                                report
                                    .error_code
                                    .as_deref()
                                    .and_then(
                                        crate::acp::delegation::metrics::intern_terminal_error_code,
                                    ),
                                Some(acc.duration_ms),
                                Some(true),
                            )
                            .emit_task_transition();
                        }
                    }
                }
                // P2: durable finalization retires the fence (keep only unresolved PE).
                {
                    let mut inner = self.pending.inner.lock().await;
                    inner.retire_terminal_metrics_accounted(task_id);
                }
            }
            Settlement::Existing(report) => {
                {
                    let mut inner = self.pending.inner.lock().await;
                    // Replace disposition + overlay with durable winner under one lock.
                    // Must run for Completed winners too (no error_code): a lost
                    // bootstrap claim may still hold a failed overlay, and status
                    // would keep projecting that stale failure otherwise.
                    // Failed/Canceled preserve exact wire codes (parent_canceled,
                    // etc.) — never fold through DelegationError::Canceled →
                    // generic "canceled".
                    inner.clear_closed_handoff_disposition(task_id);

                    let parent = accounting
                        .map(|a| a.parent_connection_id.as_str())
                        .filter(|p| !p.is_empty())
                        .map(|p| p.to_string())
                        .or_else(|| {
                            inner
                                .completed
                                .get(task_id)
                                .map(|c| c.parent_connection_id.clone())
                        })
                        .unwrap_or_default();
                    let duration_ms = accounting
                        .map(|a| a.duration_ms)
                        .or_else(|| inner.completed.get(task_id).map(|c| c.duration_ms))
                        .unwrap_or(0);

                    if let Some(completed) =
                        completed_from_existing_report(&report, &parent, duration_ms)
                    {
                        inner.insert_completed(task_id, completed);
                    } else {
                        // Invalidate mixed stale claim if we cannot project a
                        // terminal winner overlay (should not happen for real
                        // Existing settlements).
                        inner.completed.remove(task_id);
                    }
                    // P2: durable terminal known — drop fence entry.
                    inner.retire_terminal_metrics_accounted(task_id);
                }
                self.task_store.remove_retry(task_id).await;
            }
        }
        self.bump_status_version();
        self.result_notify.notify_waiters();
    }

    async fn bootstrap_cleanup_after_durable(
        &self,
        task_id: &str,
        child_connection_id: Option<&str>,
    ) {
        let mut inner = self.pending.inner.lock().await;
        if let Some(conn) = child_connection_id {
            if let Some(call) = inner
                .setups
                .iter()
                .find(|(_, child)| child.as_str() == conn)
                .map(|(call, _)| call.clone())
            {
                inner.unreserve(&call, conn);
            } else {
                inner.early_completes.remove(task_id);
                inner.early_cancels.remove(conn);
            }
            inner.unregister_live_run(conn);
        } else if let Some(conn) = inner
            .coordination_by_child
            .values()
            .find(|c| c.task_id == task_id)
            .map(|c| c.child_connection_id.clone())
        {
            inner.unreserve(task_id, &conn);
            inner.unregister_live_run(&conn);
        } else {
            inner.early_completes.remove(task_id);
            // Also clear setups keyed by task_id.
            if let Some(conn) = inner.setups.remove(task_id) {
                inner.early_cancels.remove(&conn);
                inner.unregister_live_run(&conn);
            }
        }
        inner.clear_closed_handoff_disposition(task_id);
    }

    /// Unregister live handoff only; keep park / overlay / retry for pending or permanent.
    async fn bootstrap_unregister_live_only(
        &self,
        task_id: &str,
        child_connection_id: Option<&str>,
    ) {
        let mut inner = self.pending.inner.lock().await;
        if let Some(conn) = child_connection_id {
            if let Some(call) = inner
                .setups
                .iter()
                .find(|(_, child)| child.as_str() == conn)
                .map(|(call, _)| call.clone())
            {
                // Drop setups reservation without clearing closed disposition.
                inner.setups.remove(&call);
                inner.early_completes.remove(&call);
                inner.early_cancels.remove(conn);
            }
            inner.unregister_live_run(conn);
        } else if let Some(conn) = inner
            .coordination_by_child
            .values()
            .find(|c| c.task_id == task_id)
            .map(|c| c.child_connection_id.clone())
        {
            inner.setups.remove(task_id);
            inner.early_completes.remove(task_id);
            inner.early_cancels.remove(&conn);
            inner.unregister_live_run(&conn);
        }
    }

    /// Map typed bootstrap settle result onto a continue_delegation report.
    /// Bootstrap-first / pending / permanent → parent-facing `unresumable`.
    /// Parent-end-first `Existing` → durable/parent winner (not forced unresumable).
    async fn continue_report_for_bootstrap_settle(
        &self,
        settle: BootstrapSettleResult,
        task_id: &str,
        continued_from_task_id: &str,
        agent_type: AgentType,
        child_conversation_id: i32,
        kind: BootstrapRefuseKind,
    ) -> DelegationTaskReport {
        match settle {
            BootstrapSettleResult::Won
            | BootstrapSettleResult::PendingCompensation
            | BootstrapSettleResult::PermanentPersistenceError => continue_reserved_error_report(
                task_id,
                continued_from_task_id,
                agent_type,
                DelegationError::Unresumable(bootstrap_refuse_message(kind)),
                Some(child_conversation_id),
            ),
            BootstrapSettleResult::Existing { error_code } => {
                // Prefer durable / overlay winner so parent-end-first races are honest.
                if let Ok(Some(task)) = self.task_store.load(task_id).await {
                    if task.status != TaskStatus::Running {
                        let mut report = task.to_report(None);
                        report.agent_type = Some(agent_type);
                        report.child_conversation_id = Some(child_conversation_id);
                        return with_continuation_run_identity(
                            report,
                            task_id,
                            continued_from_task_id,
                        );
                    }
                }
                {
                    let inner = self.pending.inner.lock().await;
                    if let Some(completed) = inner.completed.get(task_id) {
                        let mut report = DelegationTaskReport {
                            task_id: Some(task_id.to_string()),
                            continued_from_task_id: Some(continued_from_task_id.to_string()),
                            reused_session: None,
                            status: completed.status,
                            child_conversation_id: Some(completed.child_conversation_id),
                            agent_type: Some(completed.agent_type),
                            text: completed.text.clone(),
                            error_code: completed.error_code.clone(),
                            message: completed.message.clone(),
                            duration_ms: Some(completed.duration_ms),
                            observation: None,
                            last_agent_activity_at: None,
                            stalled_since: None,
                            recovery: None,
                        };
                        if report.agent_type.is_none() {
                            report.agent_type = Some(agent_type);
                        }
                        return report;
                    }
                }
                if let Some(code) = error_code {
                    if is_canceled_error_code(&code) {
                        // Preserve parent-end / cancel wire codes exactly.
                        // Never route through DelegationError::Canceled, which
                        // collapses parent_canceled → generic "canceled".
                        let outcome = DelegationOutcome::Err {
                            code: code.clone(),
                            message: code.clone(),
                            child_conversation_id: Some(child_conversation_id),
                        };
                        return with_continuation_run_identity(
                            report_from_outcome(None, Some(agent_type), &outcome, None),
                            task_id,
                            continued_from_task_id,
                        );
                    }
                    return continue_reserved_error_report(
                        task_id,
                        continued_from_task_id,
                        agent_type,
                        DelegationError::Unresumable(code),
                        Some(child_conversation_id),
                    );
                }
                continue_reserved_error_report(
                    task_id,
                    continued_from_task_id,
                    agent_type,
                    DelegationError::Unresumable(bootstrap_refuse_message(kind)),
                    Some(child_conversation_id),
                )
            }
        }
    }

    /// Settlement-fenced completion from lifecycle: verifies
    /// `(task_id, generation, child_connection_id)` when a live registration
    /// exists; buffers during the admission window while still reserving.
    pub async fn complete_call_for_connection(
        &self,
        child_connection_id: &str,
        outcome: DelegationOutcome,
    ) {
        let observed_at = Utc::now();
        // Admission-window buffer: connection registered, not yet promote_running.
        {
            let mut inner = self.pending.inner.lock().await;
            if let Some(coord) = inner.coordination_by_child.get(child_connection_id) {
                if !coord.admitted_running {
                    let prompt_may_have_executed = coord.prompt_may_have_executed;
                    let observed = observe_child_outcome(
                        outcome,
                        DelegationRunStatus::Reserving,
                        prompt_may_have_executed,
                        observed_at,
                    );
                    let _ = inner.buffer_admission_window_terminal(child_connection_id, observed);
                    return;
                }
                // Fence: event connection must match registered incarnation.
                let reg = &coord.run_registration;
                if fence_allows_settlement(
                    Some(reg),
                    &reg.task_id,
                    reg.generation,
                    child_connection_id,
                ) != SettlementFenceDecision::Allow
                {
                    tracing::info!(
                        child_connection_id = %child_connection_id,
                        task_id = %reg.task_id,
                        "[delegation] complete_call_for_connection: fence reject"
                    );
                    return;
                }
            }
        }

        let task_id = match self
            .resolve_task_id_for_connection(child_connection_id)
            .await
        {
            Some(id) => id,
            None => {
                // Cold path.
                match self
                    .cold_resolve_task_id_for_connection(child_connection_id)
                    .await
                {
                    Some(id) => id,
                    None => {
                        tracing::info!(
                            child_connection_id = %child_connection_id,
                            "[delegation] complete_call_for_connection: no live/cold run — no-op"
                        );
                        return;
                    }
                }
            }
        };
        self.complete_call_observed(
            &task_id,
            observe_child_outcome(outcome, DelegationRunStatus::Running, true, observed_at),
        )
        .await;
    }

    /// Called by the child-session lifecycle subscriber on `TurnComplete`
    /// (success path) or by error mappers (failure path).
    ///
    /// Removes the task from `running`, settles durable terminal state first,
    /// then publishes cache / meta / event / teardown only for the CAS winner.
    ///
    /// If no entry is in `running` under `call_id`, the outcome is buffered for
    /// a racing `start_delegation` to drain at registration — but ONLY while the
    /// delegation is still reserved (mid-setup). This closes the window where a
    /// fast/empty turn's `TurnComplete` propagates through the lifecycle while
    /// `start_delegation` is still between `send_prompt` and the `running`
    /// insert: the prompt is only *enqueued* by `send_prompt`, and the child
    /// loop emits `TurnComplete` independently, so a completion CAN beat it. When
    /// the `call_id` is no longer reserved the call was already resolved by
    /// another terminal path, so the buffer is skipped (silent no-op).
    ///
    /// Prefer [`Self::complete_call_for_connection`] from lifecycle so continued
    /// runs settle by active task id rather than conversation root call id.
    pub async fn complete_call(&self, call_id: &str, outcome: DelegationOutcome) {
        let observed_at = Utc::now();
        self.complete_call_observed(
            call_id,
            observe_child_outcome(outcome, DelegationRunStatus::Running, true, observed_at),
        )
        .await;
    }

    async fn complete_call_observed(&self, call_id: &str, observed: ObservedTerminal) {
        let task = {
            let mut inner = self.pending.inner.lock().await;
            match inner.running.remove(call_id) {
                Some(task) => {
                    // Fence: if a live registration exists for this connection,
                    // require matching task_id + generation + connection.
                    if let Some(reg) = inner.live_run_for_connection(&task.child_connection_id) {
                        if fence_allows_settlement(
                            Some(reg),
                            call_id,
                            task.generation,
                            &task.child_connection_id,
                        ) != SettlementFenceDecision::Allow
                        {
                            // Put the task back — late/stale event.
                            inner.running.insert(call_id.to_string(), task);
                            tracing::info!(
                                call_id = %call_id,
                                "[delegation] complete_call: fence reject — restored running"
                            );
                            return;
                        }
                    }
                    let duration_ms = task.started_at.elapsed().as_millis() as u64;
                    // running → settling under the same lock (CAS is out of lock).
                    inner.settling.insert(call_id.to_string(), task.clone());
                    tracing::info!(
                        call_id = %call_id,
                        child_conversation_id = task.child_conversation_id,
                        duration_ms,
                        "[delegation] complete_call: running → settling"
                    );
                    Some((task, duration_ms))
                }
                None if inner.settling.contains_key(call_id) => {
                    // Another producer already owns durable settlement.
                    tracing::info!(
                        call_id = %call_id,
                        "[delegation] complete_call: already settling — no-op"
                    );
                    None
                }
                None => {
                    // Buffer for the racing `start_delegation` to drain iff still
                    // reserved (mid-setup); a no-op otherwise, so the clone only
                    // materializes on the genuine pre-registration race.
                    tracing::info!(
                        call_id = %call_id,
                        "[delegation] complete_call: not in running — buffer early complete \
                         if reserved, else no-op"
                    );
                    let observed_at = observed.terminal.finished_at;
                    inner.buffer_early_complete(
                        call_id,
                        observe_child_outcome(
                            observed.outcome.clone(),
                            DelegationRunStatus::Reserving,
                            true,
                            observed_at,
                        ),
                    );
                    None
                }
            }
        };
        if let Some((task, duration_ms)) = task {
            let terminal = observed.terminal;
            let result_text = observed.result_text;
            // Extract validated card summary (chat first, report-file harvest
            // fallback) and strip comments from parent MCP text.
            let (extra_paths, workspace) = report_harvest_context_from_runtime(Some(&task.runtime));
            let (terminal, result_text, card_summary, completion_input) = self
                .prepare_terminal_for_workflow(
                    call_id,
                    terminal,
                    result_text,
                    &extra_paths,
                    workspace.as_deref(),
                )
                .await;
            let mut ctx = SettleContext::from_running(&task, duration_ms, false);
            ctx.card_summary = card_summary;
            ctx.completion_input = completion_input;
            tracing::info!(
                call_id = %call_id,
                child_conversation_id = task.child_conversation_id,
                "[delegation] complete_call: settle_task begin"
            );
            let started = std::time::Instant::now();
            self.settle_task(call_id, terminal, result_text, ctx).await;
            // Drop live registration after settle attempt.
            {
                let mut inner = self.pending.inner.lock().await;
                inner.unregister_live_run(&task.child_connection_id);
            }
            tracing::info!(
                call_id = %call_id,
                elapsed_ms = started.elapsed().as_millis() as u64,
                "[delegation] complete_call: settle_task finished"
            );
        }
    }

    /// Internal helper — apply the meta write iff the parent's
    /// `tool_use_id` refers to a real ACP `tool_call_id`. The
    /// broker-synthesized `"delegation-<uuid>"` placeholder targets no
    /// ToolCallState, so emitting a `ToolCallUpdate` against it would be
    /// noise that the frontend would route through `apply_tool_call_update`
    /// to a non-existent entry. See `meta_writer::is_synthetic_parent_tool_use_id`.
    async fn write_meta_if_real(
        &self,
        parent_connection_id: &str,
        parent_tool_use_id: &str,
        meta: serde_json::Value,
    ) {
        if is_synthetic_parent_tool_use_id(parent_tool_use_id) {
            return;
        }
        self.meta_writer
            .write_meta(parent_connection_id, parent_tool_use_id, meta)
            .await;
    }

    /// Internal helper — emit `AcpEvent::DelegationStarted` on the parent's
    /// stream iff the `parent_tool_use_id` refers to a real ACP tool_call.
    /// Mirror of `emit_completed_if_real`: same synthetic-id skip, and the
    /// event rides the parent's stream so the frontend `DelegationContext`
    /// receives it via the parent's per-connection attach stream in
    /// web/server mode (not only via the desktop firehose).
    #[allow(clippy::too_many_arguments)]
    async fn emit_started_if_real(
        &self,
        parent_connection_id: &str,
        parent_tool_use_id: &str,
        child_connection_id: &str,
        child_conversation_id: i32,
        agent_type: AgentType,
        task_preview: &str,
        task_id: &str,
        started_at: DateTime<Utc>,
        runtime_stats: DelegationRuntimeStats,
        attention_request: Option<crate::acp::delegation::attention::AttentionRequestSummary>,
    ) {
        if is_synthetic_parent_tool_use_id(parent_tool_use_id) {
            return;
        }
        self.event_emitter
            .emit_started(
                parent_connection_id,
                parent_tool_use_id,
                child_connection_id,
                child_conversation_id,
                agent_type,
                task_preview,
                task_id,
                started_at,
                runtime_stats,
                attention_request,
            )
            .await;
    }

    /// Internal helper — emit `AcpEvent::DelegationCompleted` on the parent's
