    /// Emit one live `ConversationStatusChanged` for the child after a winning
    /// durable CAS. Production also fans out `conversation://changed` State so
    /// sub-session sidebars (`useSubsessionSync`) leave the spinning
    /// `in_progress` badge; cards already converge via meta / task status.
    async fn emit_conversation_status_if_real(
        &self,
        parent_connection_id: &str,
        child_conversation_id: i32,
        status: ConversationStatus,
    ) {
        self.event_emitter
            .emit_conversation_status_changed(parent_connection_id, child_conversation_id, status)
            .await;
    }

    /// Cancel the pending delegation whose `external_handle` matches.
    /// Called by the MCP listener on receipt of `notifications/cancelled`
    /// from a companion. When no matching running entry exists:
    /// 1. sticky-mark any mid-setup inflight with this handle (claim → create
    ///    → admit → spawn/resume window), so checkpoints fail closed without
    ///    waiting for a later buffer take; and
    /// 2. if no setup was marked, buffer the handle in `pre_canceled_handles`
    ///    for entry-side observation (cancel before inflight registration).
    pub async fn cancel_by_external_handle(&self, external_handle: &str, reason: String) {
        let observed_at = Utc::now();
        let termination =
            explicit_cancellation_audit(DelegationRunStatus::Running, true, observed_at)
                .termination;
        let drained = {
            let mut inner = self.pending.inner.lock().await;
            let keys: Vec<String> = inner
                .running
                .iter()
                .filter(|(_, v)| v.external_handle.as_deref() == Some(external_handle))
                .map(|(k, _)| k.clone())
                .collect();
            drain_running(&mut inner, keys)
        };
        if drained.is_empty() {
            let marked = {
                let mut inner = self.pending.inner.lock().await;
                inner.mark_inflight_external_canceled(external_handle)
            };
            if !marked {
                // Race: cancel beat both running registration and inflight
                // registration. Buffer so entry-side take can still drain.
                self.buffer_pre_canceled_handle(external_handle.to_string())
                    .await;
            }
            return;
        }
        // A turn is in flight, so cancel + disconnect after durable settle.
        self.settle_drained_canceled(drained, &reason, true, termination)
            .await;
    }

    /// Resolve the pending delegation whose child matches
    /// `child_connection_id` with a `canceled` outcome. Used when a child
    /// session disconnects or errors out without firing a clean
    /// TurnComplete — the parent's `tool_use_id` shouldn't dangle.
    /// No-op when no matching entry exists.
    ///
    /// `terminal_error` carries the child connection's last `AcpEvent::Error`
    /// detail when the lifecycle worker is dispatching off an `Error` event
    /// (vs. a bare `Disconnected`). When present, it gets appended to the
    /// `Canceled { reason }` string so the parent agent's tool-call result
    /// surfaces the real cause (e.g. "Authentication required",
    /// "transport closed") instead of the opaque default. Falls back to
    /// the default reason when `None`.
    pub async fn cancel_by_child_connection(
        &self,
        child_connection_id: &str,
        terminal_error: Option<&str>,
    ) {
        let observed_at = Utc::now();
        let reason = child_canceled_reason(terminal_error);
        let outcome = DelegationOutcome::from_err(
            DelegationError::Canceled {
                reason: reason.clone(),
            },
            None,
        );
        let running_termination = AcpTerminationSummaryV1::new(
            AcpTerminationSource::ChildConnection,
            AcpTerminationReason::ChildTerminal,
            AcpTerminationClassification::Unexpected,
            true,
            observed_at,
        );
        let drained = {
            let mut inner = self.pending.inner.lock().await;
            // Admission window: buffer disconnect/error while still reserving.
            if let Some(coord) = inner.coordination_by_child.get(child_connection_id) {
                if !coord.admitted_running {
                    let terminal = observe_child_outcome(
                        outcome.clone(),
                        DelegationRunStatus::Reserving,
                        coord.prompt_may_have_executed,
                        observed_at,
                    );
                    let _ = inner
                        .buffer_admission_window_terminal(child_connection_id, terminal.clone());
                    // Also keep the classic early-cancel buffer for park drain.
                    inner.buffer_child_failure(child_connection_id, terminal);
                    return;
                }
                // Fence: only settle if this connection is the registered incarnation.
                let reg = coord.run_registration.clone();
                if fence_allows_settlement(
                    Some(&reg),
                    &reg.task_id,
                    reg.generation,
                    child_connection_id,
                ) != SettlementFenceDecision::Allow
                {
                    tracing::info!(
                        child_connection_id = %child_connection_id,
                        "[delegation] cancel_by_child_connection: fence reject — no-op"
                    );
                    return;
                }
            }
            let keys: Vec<String> = inner
                .running
                .iter()
                .filter(|(_, v)| v.child_connection_id == child_connection_id)
                .map(|(k, _)| k.clone())
                .collect();
            if keys.is_empty() {
                // Already mid-settle for this child: do not start a second
                // producer and do not re-buffer (setup reservation is gone).
                let settling = inner
                    .settling
                    .values()
                    .any(|v| v.child_connection_id == child_connection_id);
                if !settling {
                    // No running entry. If the child is still reserved,
                    // `start_delegation` is mid-setup and this failure beat the
                    // `running` insert — buffer its detail for it to drain at
                    // registration instead of no-oping.
                    inner.buffer_child_failure(
                        child_connection_id,
                        observe_child_outcome(
                            outcome.clone(),
                            DelegationRunStatus::Reserving,
                            true,
                            observed_at,
                        ),
                    );
                }
                Vec::new()
            } else {
                drain_running(&mut inner, keys)
            }
        };
        // Child already disconnected/errored — disconnect-only after settle.
        self.settle_drained_canceled(drained, &reason, false, running_termination)
            .await;
        {
            let mut inner = self.pending.inner.lock().await;
            inner.unregister_live_run(child_connection_id);
        }
    }

    /// Cascade-cancel every live descendant under `parent_connection_id` when
    /// the parent **connection tears down** (disconnect / `run_connection`
    /// exit). Uses [`ParentTurnEndReason::ParentDisconnected`]. Drops each
    /// visited connection's tool_call tracker bucket (`pending` + `consumed`)
    /// since those connections are going away. Runs fully inline — the
    /// connection is already exiting, so there is no next prompt to unblock.
    pub async fn cancel_by_parent(&self, parent_connection_id: &str) {
        let context =
            ParentEndContext::legacy(ParentTurnEndReason::ParentDisconnected, Utc::now(), true);
        self.cancel_by_parent_with_context(parent_connection_id, context)
            .await;
    }

    pub(crate) async fn cancel_by_parent_with_context(
        &self,
        parent_connection_id: &str,
        context: ParentEndContext,
    ) {
        debug_assert_eq!(context.reason, ParentTurnEndReason::ParentDisconnected);
        self.clear_mandatory_profile_routes(parent_connection_id);
        let (drained, reserving, parent_conversation_ids, settling) = self
            .drain_parent_tree(parent_connection_id, &context, false)
            .await;
        // Reserving handoffs settle inline before running teardown so a later
        // bootstrap refuse cannot relabel parent_disconnected → unresumable.
        let exclude = parent_end_broker_settled_task_ids(&drained, &reserving, &settling);
        self.settle_reserving_handoffs_for_parent_end(reserving, &context)
            .await;
        // Durable non-terminal runs (post-reserve, pre-handoff) settle even
        // when no in-memory coordination entry exists yet. Exclude task ids
        // already owned by reserving-handoff or drained-running settlement so
        // this DB-only path cannot steal their CAS win and skip side effects.
        self.settle_durable_non_terminal_for_parent_end(
            parent_conversation_ids,
            &context,
            &exclude,
        )
        .await;
        self.settle_drained_for_parent_end(drained, &context).await;
    }

    /// Cascade-cancel every live descendant under `parent_connection_id` for a
    /// **turn/prompt end** where the parent connection STAYS ALIVE (user Cancel,
    /// turn failure, or clean `end_turn` that abandons live Codeg children).
    ///
    /// The fast, turn-scoped part — tombstoning the tool_call tracker and
    /// draining the entire descendant tree — runs SYNCHRONOUSLY: the caller
    /// awaits it before the connection loop accepts the next prompt, so it can't
    /// race a next-turn registration and tombstone/cancel that turn's legitimate
    /// entries (the safety the `drop_tool_calls_for_parent` invariant relies
    /// on). Only the slow child teardown (meta/emit + spawner `cancel` /
    /// `disconnect`, which can block on slow agents) is backgrounded, so the
    /// user-visible Cancel path stays responsive.
    ///
    /// A clean `end_turn` still calls this with
    /// [`ParentTurnEndReason::JoinAbandoned`]; it is a no-op when no live
    /// Codeg task remains under the tree (`drained` empty → return without
    /// spawning settle work).
    ///
    /// RETAINS each visited connection's `consumed` tool_call memory (and
    /// tombstones the cancelled turn's unclaimed `pending` ids into it):
    /// dropping it would let a host re-emit of an already-handled
    /// `tool_call_id` re-register and mis-bind the next same-key delegation on
    /// this live connection — see `drop_tool_calls_for_parent`.
    pub async fn cancel_by_parent_turn(
        &self,
        parent_connection_id: &str,
        reason: ParentTurnEndReason,
    ) {
        debug_assert!(reason != ParentTurnEndReason::ParentDisconnected);
        let context = ParentEndContext::legacy(reason, Utc::now(), true);
        // Drop the canceled turn's mention set so a late MCP call cannot ride
        // the previous prompt's mandatory routes before the next user send.
        self.clear_mandatory_profile_routes(parent_connection_id);
        let (drained, reserving, parent_conversation_ids, settling) = self
            .drain_parent_tree(parent_connection_id, &context, true)
            .await;
        // Pre-bootstrap handoffs have no running entry: settle them *inline*
        // before returning so a sequential later refuse cannot win unresumable
        // over parent_canceled. Running-task teardown stays backgrounded.
        let exclude = parent_end_broker_settled_task_ids(&drained, &reserving, &settling);
        if !reserving.is_empty() {
            self.settle_reserving_handoffs_for_parent_end(reserving, &context)
                .await;
        }
        // Durable non-terminal runs must settle even when the in-memory maps
        // are empty (post-reserve commit, pre-begin_run_admission).
        if !parent_conversation_ids.is_empty() {
            self.settle_durable_non_terminal_for_parent_end(
                parent_conversation_ids,
                &context,
                &exclude,
            )
            .await;
        }
        if drained.is_empty() {
            return;
        }
        // The fast drain above already ran inline (scoped to the just-ended
        // turn); background only the slow child teardown.
        let broker = self.clone();
        tokio::spawn(async move {
            broker
                .settle_drained_for_parent_end(drained, &context)
                .await;
        });
    }

    #[allow(
        dead_code,
        reason = "Task 7 reaches this through the coordinator worker"
    )]
    pub(crate) async fn cancel_by_parent_turn_inline(
        &self,
        parent_connection_id: &str,
        reason: ParentTurnEndReason,
    ) {
        debug_assert!(reason != ParentTurnEndReason::ParentDisconnected);
        let context = ParentEndContext::legacy(reason, Utc::now(), true);
        self.clear_mandatory_profile_routes(parent_connection_id);
        let (drained, reserving, parent_conversation_ids, settling) = self
            .drain_parent_tree(parent_connection_id, &context, true)
            .await;
        let exclude = parent_end_broker_settled_task_ids(&drained, &reserving, &settling);
        self.settle_reserving_handoffs_for_parent_end(reserving, &context)
            .await;
        self.settle_durable_non_terminal_for_parent_end(
            parent_conversation_ids,
            &context,
            &exclude,
        )
        .await;
        self.settle_drained_for_parent_end(drained, &context).await;
    }

    /// Fast, lock-guarded part of a parent end: BFS the full descendant tree
    /// under `parent_connection_id`, mark in-flight setups, collect not-yet-
    /// admitted handoffs for immediate settle, and migrate every live running
    /// task into `settling` under one `pending.inner` lock so later
    /// child-disconnect callbacks cannot relabel grandchildren. Tool-call
    /// tracker cleanup runs for every visited connection (`keep_consumed`
    /// retains `consumed` only for turn-scoped ends).
    ///
    /// `keep_consumed` also governs the completed-cache: a **turn** end
    /// (`true`) leaves completed results so the still-alive connection's LLM
    /// can still query them; a **connection teardown** (`false`) drops each
    /// visited connection's completed-cache — those connections are gone.
    ///
    /// Returns `(running_drained, reserving_handoffs, parent_conversation_ids,
    /// settling_task_ids)`.
    /// Reserving handoffs are pre-bootstrap / admission-window registrations
    /// that have no `running` entry and often no `inflight` either — they must
    /// be settled by the caller (inline) so the durable row is not left
    /// `reserving`. `parent_conversation_ids` drives the durable non-terminal
    /// settle fallback for post-reserve / pre-handoff rows.
    /// `settling_task_ids` are already mid-CAS producers owned by the tree;
    /// the durable DB-only sweep must exclude them so the original producer
    /// retains broker side effects.
    async fn drain_parent_tree(
        &self,
        parent_connection_id: &str,
        context: &ParentEndContext,
        keep_consumed: bool,
    ) -> (
        Vec<(String, RunningTask, u64)>,
        Vec<ReservingHandoffEnd>,
        HashSet<i32>,
        Vec<String>,
    ) {
        let (drained, reserving_handoffs, visited, parent_conversation_ids, settling_task_ids) = {
            let mut inner = self.pending.inner.lock().await;
            let mut frontier = VecDeque::new();
            let mut visited: HashSet<String> = HashSet::new();
            let mut drained: Vec<(String, RunningTask, u64)> = Vec::new();
            let mut reserving_handoffs: Vec<ReservingHandoffEnd> = Vec::new();
            let mut settling_task_ids: Vec<String> = Vec::new();
            let mut parent_conversation_ids: HashSet<i32> = HashSet::new();
            frontier.push_back(parent_connection_id.to_string());

            while let Some(conn_id) = frontier.pop_front() {
                if !visited.insert(conn_id.clone()) {
                    continue;
                }
                let parent_end_stamp = inner.mark_inflight_canceled_for_parent(&conn_id, context);

                // Coordination identities exist before running registration, so
                // include their child connections in the traversal even during
                // setup races. Snapshot child ids *before* taking reserving
                // handoffs (which unregisters them).
                let coord_children: Vec<(String, i32)> = inner
                    .coordination_by_child
                    .values()
                    .filter(|identity| identity.parent_connection_id == conn_id)
                    .map(|identity| {
                        (
                            identity.child_connection_id.clone(),
                            identity.parent_conversation_id,
                        )
                    })
                    .collect();
                for (_, parent_conversation_id) in &coord_children {
                    parent_conversation_ids.insert(*parent_conversation_id);
                }
                frontier.extend(coord_children.into_iter().map(|(child, _)| child));

                // Pre-bootstrap / admission-window: durable settle path for
                // handoffs that have setups+live/coord but no inflight.
                reserving_handoffs.extend(inner.take_reserving_handoffs_for_parent_end(
                    &conn_id,
                    context,
                    parent_end_stamp,
                ));

                // Already mid-settle producers: keep ownership with their
                // original settle_task path (exclude from durable DB sweep).
                // Still walk their children so the parent-tree cascade reaches
                // grandchildren under an in-flight CAS.
                let settling_level: Vec<(String, String)> = inner
                    .settling
                    .iter()
                    .filter(|(_, task)| task.parent_connection_id == conn_id)
                    .map(|(task_id, task)| (task_id.clone(), task.child_connection_id.clone()))
                    .collect();
                for (task_id, child_connection_id) in settling_level {
                    settling_task_ids.push(task_id);
                    frontier.push_back(child_connection_id);
                }

                let keys = inner
                    .running
                    .iter()
                    .filter(|(_, task)| task.parent_connection_id == conn_id)
                    .map(|(task_id, _)| task_id.clone())
                    .collect::<Vec<_>>();
                let level = drain_running(&mut inner, keys);
                frontier.extend(
                    level
                        .iter()
                        .map(|(_, task, _)| task.child_connection_id.clone()),
                );
                drained.extend(level);
            }

            parent_conversation_ids.extend(inner.parent_conversations_for(&visited));

            if !keep_consumed {
                for conn_id in &visited {
                    inner.drop_completed_for_parent(conn_id);
                }
            }
            (
                drained,
                reserving_handoffs,
                visited,
                parent_conversation_ids,
                settling_task_ids,
            )
        };

        // Tracker cleanup after ownership drain so disconnect callbacks cannot
        // re-bind drained task keys; retain `consumed` only for turn-scoped ends.
        for conn_id in &visited {
            self.drop_tool_calls_for_parent(conn_id, keep_consumed)
                .await;
        }
        (
            drained,
            reserving_handoffs,
            parent_conversation_ids,
            settling_task_ids,
        )
    }

    /// Settle every drained running task as canceled with a stable parent-end
    /// code. Only the durable CAS winner emits terminal state; a completion
    /// that already won remains completed.
    async fn settle_drained_for_parent_end(
        &self,
        drained: Vec<(String, RunningTask, u64)>,
        parent_end: &ParentEndContext,
    ) {
        for (task_id, task, duration_ms) in drained {
            let terminal = TerminalTaskWrite::canceled(
                parent_end.durable_error_code(),
                parent_end.termination.observed_at,
                parent_end.audit(
                    DelegationRunStatus::Running,
                    AdmissionClass::NormalRevision,
                    Some(task.parent_tool_use_id.clone()),
                    Some(task.child_connection_id.clone()),
                ),
            );
            let mut context = SettleContext::from_running(&task, duration_ms, true);
            context.message = Some(parent_end.reason.message().to_string());
            context.attention_resolution = parent_end.reason.attention_code();
            self.settle_task(&task_id, terminal, None, context).await;
        }
    }

    /// Immediately durable-settle pre-bootstrap / admission-window handoffs
    /// collected by [`Self::drain_parent_tree`]. Must run **inline** (not only
    /// in a background task) so a sequential later refuse cannot win
    /// `unresumable` over a parent cancel that already drained.
    ///
    /// Live registration was already dropped under the drain lock; this path
    /// only writes the durable terminal (first-write-wins).
    async fn settle_reserving_handoffs_for_parent_end(
        &self,
        handoffs: Vec<ReservingHandoffEnd>,
        fallback: &ParentEndContext,
    ) {
        let Some(runs) = self.run_store.as_ref() else {
            return;
        };
        for handoff in handoffs {
            // Serialize claim selection with permanent PE finalize: re-read
            // disposition immediately before CAS under durable_cas_claim.
            let (disposition, terminal) = self
                .take_parent_end_cas_selection(
                    &handoff.task_id,
                    handoff.disposition.clone(),
                    DelegationRunStatus::Reserving,
                )
                .await;
            match runs.settle_terminal(&handoff.task_id, terminal).await {
                Ok(settlement) => {
                    // Parent-end is finalization owner when it persists an
                    // already-claimed ChildTerminal (exactly-once audit). ParentEnded
                    // invents still clean park/retry via finalize without metrics
                    // (drained-running paths count via settle_task).
                    // Hold exclusive durable_cas_claim through CAS + finalize so a
                    // second parent-end / PE cannot interleave mid-owner path.
                    let cas_won = settlement.won();
                    let record_won =
                        matches!(&disposition, ReservingHandoffDisposition::ChildTerminal(_))
                            && cas_won;
                    let accounting = self
                        .resolve_bootstrap_overlay_identity(
                            &handoff.task_id,
                            Some(&handoff.child_connection_id),
                        )
                        .await
                        .map(|id| PersistenceRetryAccounting {
                            parent_connection_id: id.parent_connection_id,
                            agent_type: id.agent_type,
                            child_conversation_id: id.child_conversation_id,
                            duration_ms: 0,
                        })
                        .unwrap_or(PersistenceRetryAccounting {
                            parent_connection_id: String::new(),
                            agent_type: AgentType::ClaudeCode,
                            child_conversation_id: handoff.child_conversation_id,
                            duration_ms: 0,
                        });
                    let report_code = settlement.report().error_code.clone();
                    self.finalize_durable_settlement(
                        &handoff.task_id,
                        settlement,
                        Some(&accounting),
                        record_won,
                    )
                    .await;
                    self.release_durable_cas_claim(&handoff.task_id).await;
                    if cas_won {
                        tracing::info!(
                            task_id = %handoff.task_id,
                            child_connection_id = %handoff.child_connection_id,
                            child_conversation_id = handoff.child_conversation_id,
                            reason = fallback.durable_error_code(),
                            "[delegation] reserving handoff settled on parent end"
                        );
                    } else {
                        tracing::info!(
                            task_id = %handoff.task_id,
                            existing_code = ?report_code,
                            "[delegation] reserving handoff already terminal on parent end"
                        );
                    }
                }
                Err(e) => {
                    self.release_durable_cas_claim(&handoff.task_id).await;
                    tracing::error!(
                        task_id = %handoff.task_id,
                        error = %e,
                        "[delegation] reserving handoff settle_terminal failed"
                    );
                }
            }
        }
    }

    /// Settle every durable non-terminal run owned by the given parent
    /// conversations. Covers the window where a continue (or gen-1) reserve has
    /// committed but `begin_run_admission` has not yet registered a
    /// parent-visible handoff — in-memory drain alone would miss those rows.
    /// First-write-wins with any concurrent terminal (including handoff settle).
    ///
    /// `exclude_task_ids` must include every task already owned by
    /// reserving-handoff settle or drained-running settle so this DB-only path
    /// cannot steal their CAS win and skip broker side effects (events,
    /// attention, live unregister, cancel signals).
    async fn settle_durable_non_terminal_for_parent_end(
        &self,
        parent_conversation_ids: HashSet<i32>,
        parent_end: &ParentEndContext,
        exclude_task_ids: &HashSet<String>,
    ) {
        let Some(runs) = self.run_store.as_ref() else {
            return;
        };
        for parent_conversation_id in parent_conversation_ids {
            let rows = match runs
                .list_non_terminal_for_parent(parent_conversation_id)
                .await
            {
                Ok(rows) => rows,
                Err(e) => {
                    tracing::error!(
                        parent_conversation_id,
                        error = %e,
                        "[delegation] list_non_terminal_for_parent failed on parent end"
                    );
                    continue;
                }
            };
            for row in rows {
                if exclude_task_ids.contains(&row.task_id) {
                    continue;
                }
                // Pure gen-1 reserving claims that never bound a child connection
                // and never reached running still belong to the inflight admit
                // path (abandon + provisional compensate). Settling them here
                // when parent_conversations already includes this parent (e.g.
                // after a prior continuation) would leave a durable canceled
                // run + visible canceled child without compensation.
                // Continue (gen ≥ 2) and bound/running claims remain settled.
                if row.generation == 1
                    && row.run_status
                        == crate::db::entities::delegation_task_run::DelegationRunStatus::Reserving
                    && row.reached_running_at.is_none()
                    && row.child_connection_id.is_none()
                {
                    tracing::info!(
                        task_id = %row.task_id,
                        parent_conversation_id,
                        reason = parent_end.durable_error_code(),
                        "[delegation] durable non-terminal skip pure gen1 reserving; inflight owns compensate"
                    );
                    continue;
                }
                // Honor process-local bootstrap (or other) claim: never invent
                // parent_canceled over an earlier ChildTerminal park. Claim
                // selection is serialized with permanent PE finalize.
                let prior_status = row.run_status.clone();
                let prompt_may_have_executed = matches!(prior_status, DelegationRunStatus::Running);
                let fallback = ReservingHandoffDisposition::ParentEnded(
                    parent_end.with_prompt_may_have_executed(prompt_may_have_executed),
                );
                let (claimed, terminal) = self
                    .take_parent_end_cas_selection(&row.task_id, fallback, prior_status)
                    .await;
                match runs.settle_terminal(&row.task_id, terminal).await {
                    Ok(settlement) => {
                        // Hold exclusive claim through finalize; only owner clears.
                        let cas_won = settlement.won();
                        let record_won =
                            matches!(&claimed, ReservingHandoffDisposition::ChildTerminal(_))
                                && cas_won;
                        let accounting = PersistenceRetryAccounting {
                            parent_connection_id: String::new(),
                            agent_type: row.agent_type,
                            child_conversation_id: row.child_conversation_id,
                            duration_ms: 0,
                        };
                        let report_code = settlement.report().error_code.clone();
                        self.finalize_durable_settlement(
                            &row.task_id,
                            settlement,
                            Some(&accounting),
                            record_won,
                        )
                        .await;
                        self.release_durable_cas_claim(&row.task_id).await;
                        if cas_won {
                            tracing::info!(
                                task_id = %row.task_id,
                                parent_conversation_id,
                                reason = parent_end.durable_error_code(),
                                "[delegation] durable non-terminal settled on parent end"
                            );
                        } else {
                            tracing::info!(
                                task_id = %row.task_id,
                                existing_code = ?report_code,
                                "[delegation] durable non-terminal already terminal on parent end"
                            );
                        }
                    }
                    Err(e) => {
                        self.release_durable_cas_claim(&row.task_id).await;
                        tracing::error!(
                            task_id = %row.task_id,
                            error = %e,
                            "[delegation] durable non-terminal settle_terminal failed"
                        );
                    }
                }
            }
        }
    }

    /// Settle every drained running task as canceled through the shared
    /// durable path (store CAS first, then cache/meta/event/teardown). Used by
    /// non-parent paths (child disconnect, explicit cancel) that still map to
    /// generic `"canceled"`.
    async fn settle_drained_canceled(
        &self,
        drained: Vec<(String, RunningTask, u64)>,
        reason: &str,
        cancel_turn: bool,
        termination: AcpTerminationSummaryV1,
    ) {
        for (task_id, task, duration_ms) in drained {
            let outcome = canceled_outcome(task.child_conversation_id, reason);
            let terminal = TerminalTaskWrite::canceled(
                "canceled",
                termination.observed_at,
                DelegationTerminationAuditV1::new(
                    termination.clone(),
                    DelegationRunStatus::Running,
                    AdmissionClass::NormalRevision,
                    Some(task.parent_tool_use_id.clone()),
                    Some(task.child_connection_id.clone()),
                ),
            );
            let mut ctx = SettleContext::from_running(&task, duration_ms, cancel_turn);
            let (_, _, _, message) = terminal_fields(&outcome);
            ctx.message = message;
            self.settle_task(&task_id, terminal, None, ctx).await;
        }
    }

