    /// Root-terminal teardown settles the live child tree through the broker
    /// (`cancel_by_parent`), not the lifecycle generic ConversationStatus CAS.
    /// Each settled child/grandchild keeps `parent_disconnected` causality.
    #[tokio::test]
    async fn connection_teardown_cascades_parent_disconnected() {
        use crate::acp::delegation::store::DelegationTaskStore;

        let (broker, spawner, store, attention) = coordination_broker().await;
        let child = spawn_running(&broker, &spawner, "root", 1, "child-conn").await;
        let grandchild = spawn_running(&broker, &spawner, "child-conn", 2, "grand-conn").await;
        seed_edges(&store, &attention, &child, &grandchild).await;
        broker.cancel_by_parent("root").await;
        let mut settled = 0usize;
        for task_id in [&child, &grandchild] {
            let row = store.load(task_id).await.unwrap().unwrap();
            assert_eq!(
                row.status,
                TaskStatus::Canceled,
                "broker owns terminal settlement for {task_id}"
            );
            assert_eq!(
                row.error_code.as_deref(),
                Some("parent_disconnected"),
                "child causality remains parent_disconnected for {task_id}"
            );
            settled += 1;
        }
        assert_eq!(
            settled, 2,
            "broker-owned cascade must settle the full live child tree"
        );
    }

    /// A batch `Infinite` wait must NOT hold an already-terminal result hostage
    /// to a still-running sibling: when a task is terminal at call ENTRY (it
    /// completed before the poll), return immediately with the current snapshot
    /// rather than parking for the runner. This is the mixed-at-entry case the
    /// transition-only wake used to miss — distinct from
    /// [`batch_infinite_returns_when_any_settles`] (both running at entry).
    #[tokio::test]
    async fn batch_infinite_returns_immediately_when_one_already_terminal() {
        let mock = Arc::new(MockSpawner::new());
        let broker =
            DelegationBroker::new(mock.clone() as Arc<dyn ConnectionSpawner>, shallow_lookup());
        enable_delegation(&broker).await;
        let t1 = start_running(&broker, &mock, "child-1", 1, "pt-1").await;
        let t2 = start_running(&broker, &mock, "child-2", 2, "pt-2").await;
        // t1 completes BEFORE the poll; t2 keeps running.
        broker
            .complete_call(
                &t1,
                DelegationOutcome::Ok(DelegationSuccess {
                    text: "first-done".into(),
                    child_conversation_id: 1,
                    child_agent_type: AgentType::Codex,
                    turn_count: 1,
                    duration_ms: 4,
                    token_usage: None,
                }),
            )
            .await;

        // Infinite wait, but one task is already terminal at entry → must return
        // at once (a bounded timeout guards against the regression: parking here
        // would block until t2 settles, which it never does in this test).
        let ids = vec![t1.clone(), t2.clone()];
        let reports = tokio::time::timeout(
            Duration::from_secs(2),
            broker.get_tasks_status("parent-conn", Some(1), &ids, StatusWait::Terminal),
        )
        .await
        .expect("a batch with an already-terminal task must not park under Infinite");
        assert_eq!(reports.len(), 2);
        assert_eq!(reports[0].status, TaskStatus::Completed);
        assert_eq!(reports[0].text.as_deref(), Some("first-done"));
        assert_eq!(reports[1].status, TaskStatus::Running);
    }

    /// A batch `Infinite` wait where NOTHING is running (all ids unknown) must
    /// return immediately rather than parking forever.
    #[tokio::test]
    async fn batch_infinite_all_settled_returns_immediately() {
        let mock = Arc::new(MockSpawner::new());
        let broker =
            DelegationBroker::new(mock.clone() as Arc<dyn ConnectionSpawner>, shallow_lookup());
        enable_delegation(&broker).await;
        let ids = vec!["nope-1".to_string(), "nope-2".to_string()];
        let reports = tokio::time::timeout(
            Duration::from_secs(2),
            broker.get_tasks_status("parent-conn", Some(1), &ids, StatusWait::Terminal),
        )
        .await
        .expect("all-settled infinite batch must not hang");
        assert_eq!(reports.len(), 2);
        assert!(reports.iter().all(|r| r.status == TaskStatus::Unknown));
    }

    /// A bounded batch wait with no completion returns the running snapshot once
    /// the deadline elapses (the child keeps running; the caller re-polls).
    #[tokio::test]
    async fn batch_bounded_deadline_returns_running_snapshot() {
        let mock = Arc::new(MockSpawner::new());
        let broker =
            DelegationBroker::new(mock.clone() as Arc<dyn ConnectionSpawner>, shallow_lookup());
        enable_delegation(&broker).await;
        let t1 = start_running(&broker, &mock, "child-1", 1, "pt-1").await;
        let reports = broker
            .get_tasks_status(
                "parent-conn",
                Some(1),
                &[t1],
                StatusWait::Supervised(Duration::from_millis(40)),
            )
            .await;
        assert_eq!(reports.len(), 1);
        assert_eq!(reports[0].status, TaskStatus::Running);
    }

    /// A task owned by a different parent reports `Unknown` in a batch — never
    /// leaking another parent's task, just like the single-task path.
    #[tokio::test]
    async fn batch_status_scopes_to_parent() {
        let mock = Arc::new(MockSpawner::new());
        let broker =
            DelegationBroker::new(mock.clone() as Arc<dyn ConnectionSpawner>, shallow_lookup());
        enable_delegation(&broker).await;
        let t1 = start_running(&broker, &mock, "child-1", 1, "pt-1").await;
        let reports = broker
            .get_tasks_status("other-parent", Some(2), &[t1], StatusWait::Snapshot)
            .await;
        assert_eq!(reports.len(), 1);
        assert_eq!(reports[0].status, TaskStatus::Unknown);
    }

    // -- Task 4.5: error paths ---------------------------------------------

    #[test]
    fn gen1_and_continuation_instruction_failures_preserve_admission_codes() {
        let plan_error =
            WorkflowLaunchLoadError::CompletionInstruction(TaskStoreError::WorkflowAdmission {
                code: "completion_plan_material_invalid".into(),
                message: "persisted Plan changed".into(),
            });
        assert_eq!(
            plan_error.durable_error_code("spawn_failed"),
            "completion_plan_material_invalid"
        );
        assert_eq!(
            plan_error.durable_error_code(crate::acp::delegation::metrics::ADMISSION_FAILED_CODE),
            "completion_plan_material_invalid"
        );

        let persistence_error = WorkflowLaunchLoadError::CompletionInstruction(
            TaskStoreError::Permanent("instruction read failed".into()),
        );
        assert_eq!(
            persistence_error.durable_error_code("spawn_failed"),
            "completion_instruction_binding_failed"
        );

        let binding_error = WorkflowLaunchLoadError::WorkflowBinding(TaskStoreError::Permanent(
            "binding read failed".into(),
        ));
        assert_eq!(
            binding_error.durable_error_code("spawn_failed"),
            "spawn_failed"
        );
        assert_eq!(
            binding_error
                .durable_error_code(crate::acp::delegation::metrics::ADMISSION_FAILED_CODE),
            crate::acp::delegation::metrics::ADMISSION_FAILED_CODE
        );

        let binding_protocol =
            WorkflowLaunchLoadError::WorkflowBinding(TaskStoreError::WorkflowAdmission {
                code: "unsupported_completion_protocol".into(),
                message: "workflow header disappeared".into(),
            });
        assert_eq!(
            binding_protocol.durable_error_code("spawn_failed"),
            "unsupported_completion_protocol"
        );
        let binding_transient = WorkflowLaunchLoadError::WorkflowBinding(
            TaskStoreError::Transient("connection pool timed out".into()),
        );
        assert_eq!(
            binding_transient.durable_error_code("spawn_failed"),
            "persistence_error"
        );
        let instruction_transient = WorkflowLaunchLoadError::CompletionInstruction(
            TaskStoreError::Transient("connection closed".into()),
        );
        assert_eq!(
            instruction_transient.durable_error_code("spawn_failed"),
            "persistence_error"
        );
    }

    #[test]
    fn transaction_retirement_fence_preserves_navigation_in_broker_report() {
        let store_error =
            crate::acp::delegation::run_store::terminal_protocol_store_error(
                crate::acp::delegation::workflow::WorkflowStoreError::workflow_v2_retired_with_navigation(
                    41,
                    Some(84),
                    false,
                ),
            );
        let report = report_err(
            AgentType::Codex,
            store_err_to_delegation_error(store_error),
            Some(52),
        );

        assert_eq!(report.error_code.as_deref(), Some("workflow_v2_retired"));
        assert_eq!(
            report.message.as_deref(),
            Some(crate::acp::delegation::workflow::WORKFLOW_V2_RETIRED_MESSAGE)
        );
        assert_eq!(report.child_conversation_id, Some(52));
        assert_eq!(
            report.workflow_retirement(),
            Some(&WorkflowRetirementNavigation {
                source_conversation_id: Some(41),
                successor_conversation_id: Some(84),
                can_create_simple_successor: false,
            })
        );
        assert_eq!(
            serde_json::to_value(&report).unwrap()["workflow_retirement"],
            serde_json::json!({
                "source_conversation_id": 41,
                "successor_conversation_id": 84,
                "can_create_simple_successor": false,
            })
        );

        let generic = store_err_to_delegation_error(TaskStoreError::WorkflowAdmission {
            code: "gate_not_ready".into(),
            message: "ordinary workflow admission rejection".into(),
        });
        assert!(matches!(
            generic,
            DelegationError::WorkflowAdmission { ref code, ref message }
                if code == "gate_not_ready"
                    && message == "ordinary workflow admission rejection"
        ));
    }

    #[tokio::test]
    async fn agent_defaults_are_forwarded_to_spawner() {
        // Configure broker with per-agent defaults for ClaudeCode and verify
        // they reach the spawner. Other agent types should still get the
        // empty/None defaults.
        let mock = Arc::new(MockSpawner::new());
        mock.queue_spawn(Ok("child-1".into())).await;
        mock.queue_send(Err(SpawnerError::send("stop after spawn")))
            .await;
        let broker =
            DelegationBroker::new(mock.clone() as Arc<dyn ConnectionSpawner>, shallow_lookup());

        let mut claude_cfg = BTreeMap::new();
        claude_cfg.insert("model".into(), "claude-sonnet-4-5".into());
        let mut agent_defaults = BTreeMap::new();
        agent_defaults.insert(
            AgentType::ClaudeCode,
            AgentDelegationDefaults {
                mode_id: Some("auto".into()),
                config_values: claude_cfg.clone(),
            },
        );
        broker
            .set_config(DelegationConfig {
                enabled: true,
                depth_limit: 8,
                agent_defaults,
                ..DelegationConfig::default()
            })
            .await;

        let _ = broker.handle_request(request(1, "pt-1")).await;

        let args = mock.spawn_args.lock().await;
        assert_eq!(args.len(), 1);
        let call = &args[0];
        assert_eq!(call.agent_type, AgentType::ClaudeCode);
        assert_eq!(call.preferred_mode_id.as_deref(), Some("auto"));
        assert_eq!(call.preferred_config_values, claude_cfg);
    }

