    /// Divergent Existing with durable **Completed** (no error_code) must still
    /// replace/clear a failed claim overlay so status cannot keep projecting
    /// the lost bootstrap `unresumable`.
    #[tokio::test]
    async fn resolve_terminal_intent_status_follows_success_divergent_existing() {
        let (broker, runs, task_id, parent_id, parent_conn, child_id, _conn) =
            pending_compensation_setup("divergent-success").await;

        // Confirm parked claim is still failed/unresumable before Existing finalize.
        let before = broker
            .get_task_status(
                &parent_conn,
                Some(parent_id),
                &task_id,
                StatusWait::Snapshot,
            )
            .await;
        assert_eq!(
            before.error_code.as_deref(),
            Some("unresumable"),
            "{before:?}"
        );
        assert_eq!(before.status, TaskStatus::Failed, "{before:?}");

        // Durable winner is success Completed — no error_code on the report.
        let winner = DelegationTaskReport {
            task_id: Some(task_id.clone()),
            continued_from_task_id: None,
            reused_session: None,
            status: TaskStatus::Completed,
            child_conversation_id: Some(child_id),
            agent_type: Some(AgentType::ClaudeCode),
            text: Some("child finished first".into()),
            error_code: None,
            message: None,
            duration_ms: Some(42),
            observation: None,
            last_agent_activity_at: None,
            stalled_since: None,
            recovery: None,
        };
        let accounting = PersistenceRetryAccounting {
            parent_connection_id: parent_conn.clone(),
            agent_type: AgentType::ClaudeCode,
            child_conversation_id: child_id,
            duration_ms: 42,
        };
        broker
            .finalize_durable_settlement(
                &task_id,
                Settlement::Existing(winner),
                Some(&accounting),
                false,
            )
            .await;

        {
            let inner = broker.pending.inner.lock().await;
            assert!(
                !inner.closed_handoff_dispositions.contains_key(&task_id),
                "Existing Completed must clear park"
            );
            let overlay = inner
                .completed
                .get(&task_id)
                .expect("Existing Completed must replace overlay");
            assert_eq!(overlay.status, TaskStatus::Completed, "{overlay:?}");
            assert_eq!(overlay.error_code, None, "{overlay:?}");
            assert_eq!(
                overlay.parent_connection_id, parent_conn,
                "must preserve parent identity on replace"
            );
        }

        for _ in 0..3 {
            let status = broker
                .get_task_status(
                    &parent_conn,
                    Some(parent_id),
                    &task_id,
                    StatusWait::Snapshot,
                )
                .await;
            assert_eq!(
                status.status,
                TaskStatus::Completed,
                "repeated status must show durable Completed winner: {status:?}"
            );
            assert_ne!(
                status.error_code.as_deref(),
                Some("unresumable"),
                "must not keep projecting lost failed claim: {status:?}"
            );
            assert!(
                status.error_code.is_none(),
                "Completed winner has no error_code: {status:?}"
            );
        }

        // Durable row may still be reserving in this unit path (we only drove
        // process-local Existing finalize); ensure run store still loads.
        let _ = runs.load_by_task_id(&task_id).await;
    }

    /// Spec §4.10: disconnect cleanup cannot relabel a parked bootstrap
    /// `unresumable` as canceled / `parent_canceled` / `parent_disconnected`.
    #[tokio::test]
    async fn resolve_terminal_intent_disconnect_preserves_unresumable() {
        use crate::db::entities::delegation_task_run::DelegationRunStatus;

        let (broker, runs, task_id, parent_id, parent_conn, _child_id, _conn) =
            pending_compensation_setup("disconnect-410").await;
        broker
            .note_parent_conversation_for_test(&parent_conn, parent_id)
            .await;
        broker
            .cancel_parent_tree_for_test(&parent_conn, ParentTurnEndReason::ParentDisconnected)
            .await;

        let row = runs.load_by_task_id(&task_id).await.unwrap().unwrap();
        assert_eq!(row.run_status, DelegationRunStatus::Failed, "{row:?}");
        assert_eq!(
            row.error_code.as_deref(),
            Some("unresumable"),
            "§4.10 disconnect must not relabel parked unresumable: {:?}",
            row.error_code
        );
        assert_ne!(row.error_code.as_deref(), Some("parent_disconnected"));
        assert_ne!(row.error_code.as_deref(), Some("parent_canceled"));
        assert_ne!(row.error_code.as_deref(), Some("canceled"));

        let status = broker
            .get_task_status(
                &parent_conn,
                Some(parent_id),
                &task_id,
                StatusWait::Snapshot,
            )
            .await;
        assert_eq!(
            status.error_code.as_deref(),
            Some("unresumable"),
            "status after disconnect: {status:?}"
        );
    }

    /// Cross-parent status while pending compensation must not leak the other
    /// parent's terminal intent (unknown / unauthorized, not unresumable).
    #[tokio::test]
    async fn resolve_terminal_intent_cross_parent_status_does_not_leak() {
        let (broker, _runs, task_id, parent_id, parent_conn, _child_id, _conn) =
            pending_compensation_setup("cross-parent").await;

        // Owner still sees the claim.
        let owner = broker
            .get_task_status(
                &parent_conn,
                Some(parent_id),
                &task_id,
                StatusWait::Snapshot,
            )
            .await;
        assert_eq!(
            owner.error_code.as_deref(),
            Some("unresumable"),
            "{owner:?}"
        );

        let stranger = broker
            .get_task_status(
                "other-parent-conn",
                Some(parent_id.wrapping_add(9999).max(1)),
                &task_id,
                StatusWait::Snapshot,
            )
            .await;
        assert_eq!(
            stranger.status,
            TaskStatus::Unknown,
            "cross-parent must not observe other parent's intent: {stranger:?}"
        );
        assert_ne!(
            stranger.error_code.as_deref(),
            Some("unresumable"),
            "must not leak claimed terminal to other parent: {stranger:?}"
        );
    }

    /// Parent cancel during pre-bootstrap admission (after `begin_run_admission`,
    /// before spawn returns / refuse) must durable-settle `parent_canceled`.
    ///
    /// The handoff has setups + live/coord but no `inflight` record; drain must
    /// not leave the run reserving for a later unresumable refuse to win.
    #[tokio::test]
    async fn parent_cancel_during_pre_bootstrap_handoff_settles_parent_canceled() {
        use crate::acp::connection::refuse_unresumable_bootstrap;
        use crate::acp::session_state::SessionState;
        use crate::db::entities::delegation_task_run::{AdmissionClass, DelegationRunStatus};
        use crate::db::service::conversation_service;
        use crate::db::test_helpers::{fresh_in_memory_db, seed_folder};
        use crate::web::event_bridge::EventEmitter;
        use tokio::sync::RwLock;

        let db = Arc::new(fresh_in_memory_db().await);
        let folder = seed_folder(&db, "/tmp/codeg-preboot-parent-cancel").await;
        let parent = conversation_service::create(
            &db.conn,
            folder,
            AgentType::ClaudeCode,
            Some("parent-preboot-cancel".into()),
            None,
        )
        .await
        .expect("parent");
        let child = conversation_service::create(
            &db.conn,
            folder,
            AgentType::ClaudeCode,
            Some("child-preboot-cancel".into()),
            None,
        )
        .await
        .expect("child");
        let runs = Arc::new(RunStore::new(db.clone()));
        let task_id = "task-preboot-parent-cancel".to_string();
        runs.insert_reserving(ReservingRunInsert {
            task_id: task_id.clone(),
            root_task_id: task_id.clone(),
            previous_task_id: Some("task-gen1".into()),
            generation: 2,
            parent_conversation_id: parent.id,
            parent_tool_use_id: Some("pt-preboot-cancel".into()),
            child_conversation_id: child.id,
            agent_type: AgentType::ClaudeCode.to_string(),
            profile_id: None,
            workspace_path: Some("/tmp/codeg-preboot-parent-cancel".into()),
            route_fingerprint: None,
            launch_snapshot_version: None,
            mode_id: None,
            config_values_json: None,
            task_preview: Some("continue task".into()),
            request_fingerprint: Some("fp-preboot-cancel".into()),
            admission_class: AdmissionClass::NormalRevision,
            lineage_root_task_id: task_id.clone(),
            work_unit_key: Some("unit-preboot-cancel".into()),
            history_only: false,
            replaced_task_id: None,
            replacement_reason: None,
            started_at: Some(Utc::now()),
        })
        .await
        .expect("insert reserving continue-style run");

        let mock = Arc::new(MockSpawner::new());
        let broker = broker_with_run_store(mock.clone(), parent.id, runs.clone()).await;
        let parent_conn = "parent-conn-preboot-cancel";

        // 1) Pre-bootstrap handoff only — no inflight, no running, not admitted.
        let reg = broker
            .begin_run_admission(AdmissionHandoff {
                task_id: task_id.clone(),
                generation: 2,
                child_conversation_id: child.id,
                parent_connection_id: parent_conn.into(),
                parent_conversation_id: parent.id,
                parent_tool_use_id: "pt-preboot-cancel".into(),
                task_preview: "continue task".into(),
                child_connection_id: None,
            })
            .await
            .expect("begin_run_admission");
        assert!(
            broker.has_live_run_for_test(&reg.child_connection_id).await,
            "live handoff registration must exist before parent cancel"
        );
        assert_eq!(broker.inflight_count().await, 0, "handoff has no inflight");
        assert_eq!(
            broker.reserved_call_count().await,
            1,
            "handoff reserves setups"
        );

        // 2) Parent turn cancel while still pre-bootstrap (inline, deterministic).
        broker
            .cancel_parent_tree_for_test(parent_conn, ParentTurnEndReason::ParentCanceled)
            .await;

        let after_cancel = runs
            .load_by_task_id(&task_id)
            .await
            .expect("load")
            .expect("run");
        assert_eq!(
            after_cancel.run_status,
            DelegationRunStatus::Canceled,
            "parent cancel must settle durable canceled, not leave reserving; got {:?}",
            after_cancel.run_status
        );
        assert_eq!(
            after_cancel.error_code.as_deref(),
            Some("parent_canceled"),
            "stable parent-end code required"
        );
        assert!(
            !broker.has_live_run_for_test(&reg.child_connection_id).await,
            "live registration cleaned after parent-cancel settle"
        );
        assert_eq!(
            broker.reserved_call_count().await,
            0,
            "setup reservation cleared"
        );
        assert_eq!(
            mock.spawn_args.lock().await.len(),
            0,
            "cancel must not spawn"
        );

        // 3) Later resume refuse must not overwrite parent_canceled → unresumable.
        let state = Arc::new(RwLock::new(SessionState::new(
            reg.child_connection_id.clone(),
            AgentType::ClaudeCode,
            Some(std::path::PathBuf::from("/tmp/codeg-preboot-parent-cancel")),
            "main".into(),
            None,
        )));
        let emitter = EventEmitter::Noop;
        refuse_unresumable_bootstrap(
            &state,
            &emitter,
            "sess-expected",
            "resume_existing_only: external session id mismatch".into(),
            Some(broker.as_ref()),
            &reg.child_connection_id,
        )
        .await;

        let after_refuse = runs
            .load_by_task_id(&task_id)
            .await
            .expect("load")
            .expect("run");
        assert_eq!(
            after_refuse.run_status,
            DelegationRunStatus::Canceled,
            "refuse must not relabel parent_canceled as failed/unresumable"
        );
        assert_eq!(
            after_refuse.error_code.as_deref(),
            Some("parent_canceled"),
            "first-terminal-wins: parent cancel arrived first"
        );
    }

    /// The reservation is released at park, and a SUCCESSFUL completion buffers
    /// nothing. The child's post-completion disconnect (normal v1 one-shot
    /// teardown) finds the child un-reserved and must NOT buffer a spurious
    /// cancel — otherwise every completed delegation would leak a buffer entry.
    #[tokio::test]
    async fn normal_completion_leaves_no_reservation_or_buffer() {
        let mock = Arc::new(MockSpawner::new());
        mock.queue_spawn(Ok("c-clean".into())).await;
        mock.queue_send(Ok(accepted(60, Utc::now()))).await;
        let broker =
            DelegationBroker::new(mock.clone() as Arc<dyn ConnectionSpawner>, shallow_lookup());
        enable_delegation(&broker).await;

        let driver = {
            let broker = broker.clone();
            tokio::spawn(async move { broker.handle_request(request(1, "pt-clean")).await })
        };
        let call_id = loop {
            if let Some(id) = broker.peek_first_pending_call_id().await {
                break id;
            }
            tokio::time::sleep(Duration::from_millis(5)).await;
        };
        // Parked → reservation already released.
        assert_eq!(
            broker.reserved_child_count().await,
            0,
            "park releases the reservation"
        );

        broker
            .complete_call(
                &call_id,
                DelegationOutcome::Ok(DelegationSuccess {
                    text: "ok".into(),
                    child_conversation_id: 60,
                    child_agent_type: AgentType::ClaudeCode,
                    turn_count: 1,
                    duration_ms: 5,
                    token_usage: None,
                }),
            )
            .await;
        assert!(matches!(driver.await.unwrap(), DelegationOutcome::Ok(_)));

        // The child's post-completion disconnect arrives. Child is no longer
        // reserved → must NOT buffer a spurious cancel.
        broker.cancel_by_child_connection("c-clean", None).await;
        assert_eq!(
            broker.early_cancel_count().await,
            0,
            "a post-resolution teardown must not buffer a spurious cancel"
        );
        assert_eq!(broker.pending_count().await, 0);
    }

    // -- Item 1: parent-cancel coverage of the `handle_request` setup window --

    /// A parent cancel that lands while `handle_request` is INSIDE `spawn` (the
    /// child exists but no prompt has been sent) must disconnect the child and
    /// bail — never send it a prompt — instead of no-oping and letting it run
    /// orphaned. Pinned with the spawn gate.
    #[tokio::test]
    async fn parent_cancel_in_spawn_window_disconnects_child_without_sending() {
        let mock = Arc::new(MockSpawner::new());
        mock.queue_spawn(Ok("c2".into())).await;
        mock.queue_send(Ok(accepted(99, Utc::now()))).await; // staged but must NOT be consumed
        let release = mock.install_spawn_gate().await;
        let broker =
            DelegationBroker::new(mock.clone() as Arc<dyn ConnectionSpawner>, shallow_lookup());
        enable_delegation(&broker).await;

        let driver = {
            let broker = broker.clone();
            tokio::spawn(async move { broker.handle_request(request(1, "pt-2")).await })
        };
        // Inside spawn (call recorded, held by the gate): registered in-flight,
        // not yet reserved.
        loop {
            if !mock.spawn_args.lock().await.is_empty() {
                break;
            }
            tokio::time::sleep(Duration::from_millis(5)).await;
        }
        assert_eq!(broker.inflight_count().await, 1);
        assert_eq!(broker.reserved_child_count().await, 0, "not reserved yet");

        broker
            .cancel_by_parent_turn("parent-conn", ParentTurnEndReason::ParentCanceled)
            .await;
        let _ = release.send(());

        match driver.await.unwrap() {
            DelegationOutcome::Err { code, .. } => assert_eq!(code, "parent_canceled"),
            other => panic!("expected parent_canceled, got {other:?}"),
        }
        assert_eq!(mock.disconnects.lock().await.as_slice(), &["c2"]);
        assert!(
            mock.cancels.lock().await.is_empty(),
            "no prompt was sent, so no cancel — disconnect only"
        );
        assert_eq!(
            mock.send_results.lock().await.len(),
            1,
            "send must not be consumed — no prompt sent to an abandoned child"
        );
        assert_eq!(broker.inflight_count().await, 0);
        assert_eq!(broker.reserved_child_count().await, 0);
    }

    fn audited_setup_parent_loss(
        source: AcpTerminationSource,
        reason: AcpTerminationReason,
        classification: AcpTerminationClassification,
    ) -> ParentEndContext {
        let mut termination =
            AcpTerminationSummaryV1::new(source, reason, classification, false, Utc::now());
        if source == AcpTerminationSource::Frontend {
            termination.frontend_origin =
                Some(crate::acp::termination::AcpDisconnectOrigin::ExplicitUser);
        }
        ParentEndContext {
            reason: ParentTurnEndReason::ParentDisconnected,
            termination,
        }
    }

