    #[tokio::test]
    async fn emitter_harvests_card_summary_from_linked_report_file() {
        let dir = std::env::temp_dir().join(format!(
            "codeg-broker-card-harvest-{}",
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let report = dir.join("final-review.md");
        std::fs::write(
            &report,
            r#"<!-- codeg-card-summary-v1
{"kind":"review","verdict":"request_changes","critical":0,"important":1,"minor":0,"summary":"TS build fails on nullable taskIndex.","report_file":".superpowers/sdd/final-review.md"}
-->
"#,
        )
        .unwrap();

        let mock = Arc::new(MockSpawner::new());
        mock.queue_spawn(Ok("child-conn-harvest".into())).await;
        mock.queue_send(Ok(accepted(44, Utc::now()))).await;
        let writer = Arc::new(MockMetaWriter::new());
        let emitter = Arc::new(MockEventEmitter::new());
        let broker = broker_with_emitter(mock.clone(), writer.clone(), emitter.clone()).await;

        // Chat has prose + link only (no card) — mirrors session 2534 Final reviewer.
        let raw_text = format!(
            "Verdict: `request_changes`.\n\nReport: [final-review.md]({})",
            report.display()
        );

        let driver = {
            let broker = broker.clone();
            tokio::spawn(async move { broker.handle_request(request(1, "pt-harvest")).await })
        };
        let call_id = loop {
            if let Some(id) = broker.peek_first_pending_call_id().await {
                break id;
            }
            tokio::time::sleep(Duration::from_millis(5)).await;
        };
        broker
            .complete_call(
                &call_id,
                DelegationOutcome::Ok(DelegationSuccess {
                    text: raw_text,
                    child_conversation_id: 44,
                    child_agent_type: AgentType::ClaudeCode,
                    turn_count: 1,
                    duration_ms: 10,
                    token_usage: None,
                }),
            )
            .await;
        let report_out = driver.await.unwrap();
        assert!(
            matches!(report_out, DelegationOutcome::Ok(_)),
            "expected Ok, got {report_out:?}"
        );

        let calls = emitter.snapshot().await;
        assert_eq!(calls.len(), 1);
        let summary = calls[0]
            .card_summary
            .as_ref()
            .expect("report-file harvest must populate card_summary");
        match summary {
            CardSummary::Review {
                verdict: crate::acp::delegation::card_summary::ReviewVerdict::RequestChanges,
                important,
                ..
            } => assert_eq!(*important, 1),
            other => panic!("expected request_changes review, got {other:?}"),
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[tokio::test]
    async fn emitter_records_started_on_start_delegation_happy_path() {
        let mock = Arc::new(MockSpawner::new());
        mock.queue_spawn(Ok("child-conn-start".into())).await;
        mock.queue_send(Ok(accepted(55, Utc::now()))).await;
        let writer = Arc::new(MockMetaWriter::new());
        let emitter = Arc::new(MockEventEmitter::new());
        let broker = broker_with_emitter(mock.clone(), writer.clone(), emitter.clone()).await;

        let driver = {
            let broker = broker.clone();
            tokio::spawn(async move { broker.handle_request(request(1, "pt-start")).await })
        };
        let call_id = loop {
            if let Some(id) = broker.peek_first_pending_call_id().await {
                break id;
            }
            tokio::time::sleep(Duration::from_millis(5)).await;
        };

        // `started` fires after Running registration under publication_lock,
        // before handle_request parks. A pending entry can appear slightly
        // before the emit finishes, so wait for the start event.
        let started = loop {
            let snap = emitter.started_snapshot().await;
            if !snap.is_empty() {
                break snap;
            }
            tokio::task::yield_now().await;
        };
        assert_eq!(started.len(), 1, "exactly one DelegationStarted per task");
        let s = &started[0];
        assert_eq!(s.parent_connection_id, "parent-conn");
        assert_eq!(s.parent_tool_use_id, "pt-start");
        assert_eq!(s.child_connection_id, "child-conn-start");
        assert_eq!(s.child_conversation_id, 55);
        assert_eq!(s.agent_type, AgentType::ClaudeCode);
        assert_eq!(
            emitter.count().await,
            0,
            "no terminal emit before completion"
        );

        broker
            .complete_call(
                &call_id,
                DelegationOutcome::Ok(DelegationSuccess {
                    text: "done".into(),
                    child_conversation_id: 55,
                    child_agent_type: AgentType::ClaudeCode,
                    turn_count: 1,
                    duration_ms: 10,
                    token_usage: None,
                }),
            )
            .await;
        driver.await.unwrap();

        // Completion adds exactly one terminal emit; started stays at 1.
        assert_eq!(emitter.started_count().await, 1);
        assert_eq!(emitter.count().await, 1);
    }

